import type { Database } from '@oferty/shared';
import * as Sentry from '@sentry/react';
import { useEffect, useRef, useState } from 'react';

import { supabase } from '../../lib/supabase.js';
import { fetchProfile, type ProfileState, type TourScreen } from './profile-read.js';

/**
 * Hook profilu i zapisy onboardingu. Odczyt (`fetchProfile`, `parseProfileRow`,
 * kształt `AccountProfile`) żyje w `profile-read.ts`, reguła bramki regulaminu
 * w `needs-terms-screen.ts` — re-eksportowane stąd, bo konsumenci (i atrapy
 * `vi.mock('../account/use-profile.js')` w testach bramki i strony zgody)
 * znają JEDEN moduł; definicja każdej z tych funkcji jest nadal jedna.
 */
export {
  fetchProfile,
  parseProfileRow,
  TOUR_SCREENS,
  type AccountProfile,
  type AccountRole,
  type ProfileReadResult,
  type ProfileState,
  type TourScreen,
  type TourSeenFlags,
} from './profile-read.js';
export { needsTermsScreen } from './needs-terms-screen.js';

/**
 * Ładunek zapisu ograniczony TYPEM do czterech kolumn, na które
 * `authenticated` ma kolumnowy grant UPDATE. Klucz budowany wyrażeniem
 * (`{ [kolumna]: true }`) zgubiłby to zawężenie i zamieniłby literówkę
 * w nazwie kolumny w cichą odmowę PostgREST-a zamiast w błąd typu.
 */
type OnboardingPatch = Pick<
  Database['public']['Tables']['profiles']['Update'],
  'first_steps_dismissed_at' | 'tour_seen_offers' | 'tour_seen_offer_details' | 'tour_seen_templates'
>;

/** Ekran → ładunek zapisu. Jedno miejsce, w którym ekran spotyka kolumnę. */
const TOUR_PATCHES: Readonly<Record<TourScreen, OnboardingPatch>> = {
  oferty: { tour_seen_offers: true },
  oferta: { tour_seen_offer_details: true },
  szablony: { tour_seen_templates: true },
};

let isWriteFailureReported = false;

/**
 * Awaria ZAPISU własnego wiersza — OSOBNY zatrzask od odczytu. Wspólny
 * konsumowało pierwsze nieudane „Zamknij checklistę" i późniejsza realna
 * awaria odczytu `profiles` (bramka dostępu całego panelu) nie trafiłaby już
 * do Sentry w tej sesji. Dwie różne przyczyny to dwa zdarzenia, każde raz.
 */
function reportWriteFailureOnce(cause: unknown): void {
  if (isWriteFailureReported) {
    return;
  }

  isWriteFailureReported = true;
  Sentry.captureException(cause);
}

/**
 * `reloadToken` to NUMER PROŚBY o ponowny odczyt, nie flaga: prośba powtarzalna
 * (dwa kliknięcia „Pokaż przewodnik ponownie" pod rząd) musi odpalić efekt za
 * każdym razem, a `setState(true)` na już-`true` efektu nie odpala
 * (`.claude/rules/learned-patterns.md`). Przeładowanie NIE wraca do stanu
 * `ladowanie`: bramka dostępu pokazałaby wtedy ekran oczekiwania zamiast
 * panelu, w którym człowiek właśnie kliknął.
 */
export function useProfile(userId: string, reloadToken = 0): ProfileState {
  const [state, setState] = useState<ProfileState>({ status: 'ladowanie' });
  const lastUserIdRef = useRef<string | null>(null);

  useEffect(() => {
    const controller = new AbortController();

    if (lastUserIdRef.current !== userId) {
      lastUserIdRef.current = userId;
      setState({ status: 'ladowanie' });
    }

    void fetchProfile(userId, controller.signal).then((next) => {
      if (controller.signal.aborted) {
        return;
      }

      setState(next);
    });

    return () => {
      controller.abort();
    };
  }, [userId, reloadToken]);

  return state;
}

/**
 * Zapisy WŁASNEGO wiersza `profiles` — jedyne cztery kolumny, na które
 * `authenticated` ma grant UPDATE (migracja `20260914100000`). Filtr po `id`
 * nie jest zabezpieczeniem (jest nim polityka `profiles_update_own`), tylko
 * jedynym sposobem wskazania wiersza: bez niego `update` dotyczyłby wszystkich
 * wierszy, które polityka przepuści.
 *
 * Oba zapisy są BEST-EFFORT i nie mają ścieżki błędu na ekranie: nieudany
 * zapis znaczy tyle, że karta albo przewodnik wrócą przy następnym wejściu —
 * a użytkownik nie ma na tę awarię żadnej reakcji poza powtórzeniem gestu.
 * Raport idzie do Sentry przez WŁASNY zatrzask zapisów (`reportWriteFailureOnce`),
 * osobny od zatrzasku odczytu: jedna przyczyna (obraz przed migracją, odebrany
 * grant) dotyczy KAŻDEGO konta i zalałaby monitoring jednym zdarzeniem
 * z każdej sesji, ale nieudany zapis nie ma prawa zjeść raportu o nieudanym
 * ODCZYCIE profilu, na którym stoi bramka dostępu.
 */
async function updateOwnProfile(userId: string, patch: OnboardingPatch): Promise<boolean> {
  try {
    const { error } = await supabase.from('profiles').update(patch).eq('id', userId);

    if (error !== null) {
      reportWriteFailureOnce(error);

      return false;
    }

    return true;
  } catch (cause) {
    reportWriteFailureOnce(cause);

    return false;
  }
}

/** Zamknięcie checklisty „Pierwsze kroki" (D17) — stempel chwili zamknięcia. */
export async function dismissFirstSteps(userId: string): Promise<boolean> {
  return updateOwnProfile(userId, { first_steps_dismissed_at: new Date().toISOString() });
}

/** Przewodnik danego ekranu zamknięty (D18) — ładunek z `TOUR_PATCHES`. */
export async function markTourSeen(userId: string, screen: TourScreen): Promise<boolean> {
  return updateOwnProfile(userId, TOUR_PATCHES[screen]);
}

/**
 * „Pokaż przewodnik ponownie" z ekranu pomocy (R14) — zeruje WSZYSTKIE trzy
 * kolumny jednym zapisem. Jedna instrukcja, nie pętla po `TOUR_SCREENS`: trzy
 * osobne `update` mogłyby skończyć się stanem, w którym przewodnik wraca na
 * jednym ekranie z trzech, a użytkownik zobaczyłby to dopiero za tydzień.
 *
 * Kolumny wypisane wprost, a nie zbudowane z `TOUR_PATCHES` przez odwrócenie
 * wartości: klucz z wyrażenia gubi zawężenie typu `OnboardingPatch`, przez
 * które literówka w nazwie kolumny jest dziś błędem kompilacji, a nie cichą
 * odmową PostgREST-a.
 */
export async function resetTours(userId: string): Promise<boolean> {
  return updateOwnProfile(userId, {
    tour_seen_offers: false,
    tour_seen_offer_details: false,
    tour_seen_templates: false,
  });
}

