import { MIN_USABLE_FRAME_PX } from '@oferty/shared';
import * as Sentry from '@sentry/react';
import { useCallback, useEffect, useState } from 'react';

import { track } from '../../lib/analytics.js';
import { ANALYTICS_EVENTS } from '../../lib/analytics-events.js';
import { supabase } from '../../lib/supabase.js';
import { dismissFirstSteps } from '../account/use-profile.js';
import { useAccountAccess, useAccountAccessReload } from '../auth/access-gate.js';

/**
 * Checklista „Pierwsze kroki" (D17, R12) — liczona Z DANYCH, nigdy z osobnego
 * licznika postępu w bazie. Odhaczenie kroku jest FAKTEM o koncie (jest token
 * albo zgoda OAuth, jest szablon, jest oferta, jest wizyta), więc stan
 * odtwarza się sam po każdym zalogowaniu i nie ma jak rozjechać się z rzeczywistością.
 *
 * Widoczna na liście ofert do czasu 4/4 albo ręcznego zamknięcia — TAKŻE gdy
 * lista ofert nie jest pusta. Krok „webhook" jest OPCJONALNY: nie wchodzi do
 * licznika i jego brak nie trzyma karty na ekranie.
 *
 * Konto `ograniczone` / `oczekujace` nie dostaje karty w ogóle (D17): baner
 * trybu ograniczonego ma pierwszeństwo, a checklista zachęcałaby do czynności,
 * których baza i tak odmówi.
 *
 * CZEGO TA KARTA NIE ROBI: nie pokazuje kroku jako niezrobionego, gdy nie
 * udało się go SPRAWDZIĆ. Awaria któregokolwiek odczytu gasi całą kartę
 * (stan `ukryta`), bo „Opublikuj pierwszą ofertę." pokazane komuś, kto ma
 * dwadzieścia ofert, jest nieprawdą — a użytkownik nie ma na tę awarię żadnej
 * reakcji poza odświeżeniem, które i tak sam zrobi.
 */

/** Krok checklisty; `webhook` jest jedynym opcjonalnym (D17). */
export const FIRST_STEP_IDS = ['mcp', 'szablon', 'oferta', 'wizyta', 'webhook'] as const;

export type FirstStepId = (typeof FIRST_STEP_IDS)[number];

const OPTIONAL_STEP_IDS: ReadonlySet<FirstStepId> = new Set<FirstStepId>(['webhook']);

export interface FirstStep {
  readonly id: FirstStepId;
  readonly isDone: boolean;
  readonly isOptional: boolean;
}

export type FirstStepsState =
  /**
   * Odczyt postępu jeszcze trwa. Stan ISTNIEJE osobno od `ukryta`, bo o tym,
   * czy karta będzie na ekranie, decyduje INNE zapytanie niż lista ofert —
   * a przewodnik listy celuje w tę kartę pierwszym krokiem i musi poczekać na
   * OBA źródła (start na jednorazowym snapshocie DOM-u bez karty po cichu
   * gubi krok pierwszy).
   */
  | { readonly status: 'ladowanie' }
  | { readonly status: 'ukryta' }
  | {
      readonly status: 'gotowa';
      readonly steps: readonly FirstStep[];
      /** Odhaczone kroki OBOWIĄZKOWE — licznik „{n} z 4 gotowe". */
      readonly doneCount: number;
      readonly requiredCount: number;
      readonly dismiss: () => void;
    };

interface FirstStepsProgress {
  readonly hasMcp: boolean;
  readonly hasTemplate: boolean;
  readonly hasOffer: boolean;
  readonly hasVisit: boolean;
}

/** `null` = „nie wiadomo" (awaria odczytu), nie „nie ma". */
type Probe = boolean | null;

let isProgressFailureReported = false;

/**
 * Konta, dla których checklista już domknęła się w tej sesji (4/4). Zatrzask
 * MODUŁOWY, kluczowany identyfikatorem konta: karta znika bez zapisu do bazy,
 * więc bez niego każde wejście na listę ofert powtarzało pięć zapytań (w tym
 * `listGrants()` do GoTrue) po to, żeby znów niczego nie narysować — a
 * przewodnik ekranu czekał na najwolniejszą z nich.
 */
const completedOwners = new Set<string>();

/**
 * Raport awarii odczytu postępu — RAZ na proces. Bez PII: do Sentry idzie
 * wyłącznie wyjątek klienta, bez identyfikatora konta i bez slugów ofert.
 */
function reportProgressFailureOnce(cause: unknown): void {
  if (isProgressFailureReported) {
    return;
  }

  isProgressFailureReported = true;
  Sentry.captureException(cause);
}

/**
 * Czy konto ma WŁASNY wiersz `mcp_tokens`. Zapytanie nie filtruje po
 * właścicielu: robi to RLS (tabela ma PK na `owner_id`), a filtr w kliencie
 * tylko udawałby, że to on jest zabezpieczeniem.
 */
async function probeMcpToken(signal: AbortSignal): Promise<Probe> {
  const { data, error } = await supabase
    .from('mcp_tokens')
    .select('owner_id')
    .limit(1)
    .abortSignal(signal);

  if (error !== null || data === null) {
    return null;
  }

  return data.length > 0;
}

/**
 * Czy konto podłączyło Claude'a przez OAuth. Drugi tor tego samego kroku:
 * connector nie zostawia wiersza w `mcp_tokens`, tylko zgodę w GoTrue.
 * `listGrants()` nie przyjmuje sygnału (kontrakt biblioteki) — przerwanie
 * działa przez odsiew odpowiedzi u wołającego.
 */
async function probeOauthGrants(): Promise<Probe> {
  try {
    const { data, error } = await supabase.auth.oauth.listGrants();

    if (error !== null) {
      return null;
    }

    return data.length > 0;
  } catch {
    // Wyłączony serwer OAuth na projekcie (staging) wygląda stąd tak samo jak
    // awaria sieci — w obu wypadkach ten tor po prostu nic nie rozstrzyga.
    return null;
  }
}

/** Czy konto ma choć jeden WŁASNY szablon. Układy wbudowane nie mają wierszy. */
async function probeTemplate(signal: AbortSignal): Promise<Probe> {
  const { data, error } = await supabase
    .from('offer_templates')
    .select('id')
    .limit(1)
    .abortSignal(signal);

  if (error !== null || data === null) {
    return null;
  }

  return data.length > 0;
}

/**
 * Czy konto ma choć jedną ofertę. JEDEN wiersz, nie lista identyfikatorów:
 * krok jest boolem, a lista do tysiąca uuid-ów szła wyłącznie po to, żeby
 * policzyć `length > 0` — obok zapytania, które ta sama strona robi w tym
 * samym renderze (`useOffers`).
 */
async function probeOffer(signal: AbortSignal): Promise<Probe> {
  const { data, error } = await supabase.from('offers').select('id').limit(1).abortSignal(signal);

  if (error !== null || data === null) {
    return null;
  }

  return data.length > 0;
}

/**
 * Czy konto ma choć jedną wizytę LICZONĄ. Sonda na `visits` z tym samym progiem
 * geometrii co reszta panelu (`docs/CONCEPTS.md` → „wizyta liczona"), a nie RPC
 * `offers_visit_summary` z tablicą identyfikatorów: agregat przechodzi po
 * WSZYSTKICH wizytach konta, a tu potrzebny jest jeden bool. Zapytanie nie
 * filtruje po właścicielu — robi to RLS (`exists` na `offers.owner_id`).
 */
async function probeVisit(signal: AbortSignal): Promise<Probe> {
  const { data, error } = await supabase
    .from('visits')
    .select('id')
    .gte('viewport_width', MIN_USABLE_FRAME_PX)
    .gte('doc_height', MIN_USABLE_FRAME_PX)
    .limit(1)
    .abortSignal(signal);

  if (error !== null || data === null) {
    return null;
  }

  return data.length > 0;
}

/**
 * Stan czterech kroków obowiązkowych. `null` znaczy „któregoś z nich nie dało
 * się sprawdzić" — wołający gasi wtedy kartę zamiast zgadywać.
 *
 * Krok „MCP" jest ALTERNATYWĄ: token albo zgoda OAuth. Dlatego brak tokenu
 * przy nierozstrzygniętych zgodach (wyłączony serwer OAuth, awaria) jest
 * „nie wiadomo", a token bez zgód — „gotowe": drugiego toru nie trzeba wtedy
 * znać.
 */
export async function fetchFirstStepsProgress(
  signal: AbortSignal,
): Promise<FirstStepsProgress | null> {
  const [mcpToken, grants, template, offer, visit] = await Promise.all([
    probeMcpToken(signal),
    probeOauthGrants(),
    probeTemplate(signal),
    probeOffer(signal),
    probeVisit(signal),
  ]);

  if (signal.aborted) {
    return null;
  }

  const hasMcp = anyOf(mcpToken, grants);

  if (hasMcp === null || template === null || offer === null || visit === null) {
    return null;
  }

  return {
    hasMcp,
    hasTemplate: template,
    hasOffer: offer,
    hasVisit: visit,
  };
}

/**
 * Alternatywa dwóch sond: `true` gdy którakolwiek potwierdza, `false` gdy OBIE
 * zaprzeczają, `null` gdy żadna nie potwierdza, a co najmniej jedna nie
 * rozstrzyga. Osobna funkcja, a nie ternary w ternary: to jedyne miejsce, gdzie
 * „nie wiadomo" musi przegrać z „na pewno tak" i wygrać z „na pewno nie".
 */
function anyOf(first: Probe, second: Probe): Probe {
  if (first === true || second === true) {
    return true;
  }

  return first === null || second === null ? null : false;
}

/** Postęp + flaga webhooka → kroki w kolejności z planu. */
export function toFirstSteps(progress: FirstStepsProgress, hasWebhook: boolean): readonly FirstStep[] {
  const doneById: Readonly<Record<FirstStepId, boolean>> = {
    mcp: progress.hasMcp,
    szablon: progress.hasTemplate,
    oferta: progress.hasOffer,
    wizyta: progress.hasVisit,
    webhook: hasWebhook,
  };

  return FIRST_STEP_IDS.map((id) => ({
    id,
    isDone: doneById[id],
    isOptional: OPTIONAL_STEP_IDS.has(id),
  }));
}

/** Stan odczytu postępu; `awaria` gasi kartę, `ladowanie` wstrzymuje przewodnik. */
type ProbeState =
  | { readonly status: 'ladowanie' }
  | { readonly status: 'gotowe'; readonly progress: FirstStepsProgress }
  | { readonly status: 'awaria' };

export function useFirstSteps(): FirstStepsState {
  const profile = useAccountAccess();
  const [probe, setProbe] = useState<ProbeState>({ status: 'ladowanie' });
  /**
   * Zamknięcie ręczne trzymane LOKALNIE, żeby karta znikała od razu — profil
   * bramki dostępu nie jest po zapisie przeładowywany. Jeden stan na jeden
   * wybór: `isFirstStepsDismissed` z profilu ustawia go na starcie, a klik
   * przestawia go bez czekania na odpowiedź bazy.
   */
  const [isDismissed, setIsDismissed] = useState(profile?.isFirstStepsDismissed === true);
  const reloadProfile = useAccountAccessReload();
  const userId = profile?.id ?? null;
  const accessState = profile?.accessState ?? null;
  const isEligible =
    accessState === 'aktywne' && !isDismissed && !completedOwners.has(userId ?? '');

  useEffect(() => {
    if (!isEligible) {
      return;
    }

    const controller = new AbortController();

    void (async () => {
      try {
        const next = await fetchFirstStepsProgress(controller.signal);

        if (controller.signal.aborted) {
          return;
        }

        setProbe(next === null ? { status: 'awaria' } : { status: 'gotowe', progress: next });
      } catch (cause) {
        /*
         * Wyjątek synchroniczny klienta — karta znika tak samo jak przy
         * odmowie odczytu. Raport idzie STĄD, bo ŻADNA z pięciu sond nie
         * raportuje sama: każda oddaje `null` przy odmowie odczytu, więc rzut
         * synchroniczny klienta nie zostawiłby inaczej ani jednego śladu.
         * Zatrzask modułowy, nie stan komponentu — kartę montuje każde
         * wejście na listę ofert, więc jedna przyczyna (obraz przed migracją)
         * dawałaby dziesiątki identycznych zdarzeń z jednej sesji.
         */
        reportProgressFailureOnce(cause);

        if (!controller.signal.aborted) {
          setProbe({ status: 'awaria' });
        }
      }
    })();

    return () => {
      controller.abort();
    };
  }, [isEligible]);

  const dismiss = useCallback(() => {
    setIsDismissed(true);
    track(ANALYTICS_EVENTS.firstStepsDismissed);

    if (userId !== null) {
      /*
       * Po UDANYM zapisie prosimy bramkę o ponowny odczyt wiersza: stan
       * lokalny znika razem z komponentem, a profil bramki czytany jest raz
       * NAD `Outlet`-em routera. Bez tego nawigacja SPA na `/szablony` i powrót
       * przywracały kartę, a kolejne kliknięcie wysyłało drugi zapis i drugie
       * zdarzenie `checklista_zamknieta`.
       */
      void dismissFirstSteps(userId).then((isSaved) => {
        if (isSaved) {
          reloadProfile();
        }
      });
    }
  }, [reloadProfile, userId]);

  if (!isEligible || profile === null || probe.status === 'awaria') {
    return { status: 'ukryta' };
  }

  if (probe.status === 'ladowanie') {
    return { status: 'ladowanie' };
  }

  const steps = toFirstSteps(probe.progress, profile.hasWebhook);
  const required = steps.filter((step) => !step.isOptional);
  const doneCount = required.filter((step) => step.isDone).length;

  // Komplet kroków obowiązkowych = koniec onboardingu. Karta znika BEZ zapisu
  // do bazy: stan liczy się z danych, więc i tak nigdy już się nie pokaże.
  // Zatrzask modułowy zdejmuje przy okazji sondy z każdego kolejnego wejścia
  // na listę ofert — bez niego konto 4/4 płaciło pięcioma zapytaniami za brak
  // karty, a przewodnik ekranu czekał na ich odpowiedź.
  if (doneCount === required.length) {
    if (userId !== null) {
      completedOwners.add(userId);
    }

    return { status: 'ukryta' };
  }

  return {
    status: 'gotowa',
    steps,
    doneCount,
    requiredCount: required.length,
    dismiss,
  };
}

