import { driver, type Driver } from 'driver.js';
import 'driver.js/dist/driver.css';
import { useEffect, useRef } from 'react';

import { track } from '../../lib/analytics.js';
import { ANALYTICS_EVENTS, type AnalyticsEvent } from '../../lib/analytics-events.js';
import { markTourSeen, type TourScreen } from '../account/use-profile.js';
import { useAccountAccess, useAccountAccessReload } from '../auth/access-gate.js';
import { TOURS, buildSteps, expandCollapsedTargets } from './tours.js';
import { TOUR_TEXTS } from './texts.js';
import './tour.css';

/**
 * Przewodnik po ekranie (D18, R13) — JEDEN raz na konto i ekran, nigdy więcej.
 *
 * Kiedy startuje: konto jest w stanie `aktywne` (tryb ograniczony i oczekujący
 * mają baner, nie wycieczkę), kolumna `tour_seen_*` jest `false`, a dane ekranu
 * są już na miejscu (`isPending === false`). Start przed danymi pokazywałby
 * strzałki na szkielecie ładowania — dlatego konsumenci przekazują
 * `state.status !== 'ready'`, a nie `=== 'loading'`: na ekranie błędu i „nie ma
 * takiej oferty" też nie ma czego podświetlić, a przewodnik jednorazowy
 * spaliłby się wtedy na komunikacie o awarii. Z tego samego powodu start
 * wymaga CO NAJMNIEJ JEDNEGO kroku z elementem: kroki bez celu stoją na środku
 * ekranu i same w sobie nie dowodzą, że ekran w ogóle ma treść.
 *
 * Kiedy się zapisuje: `onDestroyed`, czyli po „Koniec", po zamknięciu i po
 * `Esc` — ale NIE przy odmontowaniu ekranu. To dwa różne zdarzenia (wniosek
 * z `.claude/rules/learned-patterns.md`): wyjście z widoku w połowie
 * przewodnika nie jest decyzją „już to widziałem", więc przewodnik ma wtedy
 * wrócić przy kolejnym wejściu. Flaga odmontowania zeruje się w CIELE efektu,
 * bo `<StrictMode>` montuje komponent dwa razy.
 *
 * „Przewodnik jest już uruchomiony" trzyma REFERENCJA DO ŻYWEJ INSTANCJI, nie
 * flaga podnoszona raz na zawsze. Flaga nie wracała do `false`, a sprzątanie
 * bezwarunkowo woła `destroy()`, więc pod `<StrictMode>` (efekt → sprzątanie →
 * efekt) przewodnik ginął po pierwszym cyklu i nie wracał ANI RAZU. Sprzątanie
 * ma w Reakcie odwracać skutek efektu w całości — także ten zapisany w ref.
 * Samo sprzątanie (`destroy()`) należy do hooka, nie do konwencji konsumenta —
 * wyrwana z drzewa nakładka przewodnika zostawiłaby zasłonięty ekran
 * i przechwycone klawisze.
 */

/** Ekran → zdarzenie analityki. Osobne nazwy, bo właściwości są tylko liczbami. */
const TOUR_EVENTS: Readonly<Record<TourScreen, AnalyticsEvent>> = {
  oferty: ANALYTICS_EVENTS.tourFinishedOffers,
  oferta: ANALYTICS_EVENTS.tourFinishedOfferDetails,
  szablony: ANALYTICS_EVENTS.tourFinishedTemplates,
};

export function useScreenTour(screen: TourScreen, isPending: boolean): void {
  const profile = useAccountAccess();
  const reloadProfile = useAccountAccessReload();
  /** Żywa instancja przewodnika — `null` znaczy „nie ma czego sprzątać". */
  const instanceRef = useRef<Driver | null>(null);
  /** „Ekran znika", a nie „użytkownik skończył" — patrz komentarz wyżej. */
  const isUnmountingRef = useRef(false);

  const userId = profile?.id ?? null;
  const isEligible =
    !isPending && profile !== null && profile.accessState === 'aktywne' && !profile.tourSeen[screen];

  useEffect(() => {
    isUnmountingRef.current = false;

    if (!isEligible || instanceRef.current !== null) {
      return;
    }

    // Na telefonie pozycje nawigacji są za ☰: rozwijamy je PRZED budową
    // kroków, żeby przewodnik wskazał właściwą pozycję, a zwijamy po nim.
    const { collapse: collapseTargets, hasExpanded } = expandCollapsedTargets(
      TOURS[screen],
      document,
    );
    let instance: Driver | null = null;
    let isCancelled = false;

    const start = (): void => {
      if (isCancelled) {
        return;
      }

      const steps = buildSteps(TOURS[screen], document);

      // Ani jednego kroku Z CELEM = nie ma czego pokazać. Nie odhaczamy wtedy
      // przewodnika: człowiek go nie widział, więc ma dostać go następnym razem.
      if (!steps.some((step) => step.element !== undefined)) {
        collapseTargets();

        return;
      }

      instance = driver({
        steps,
        showProgress: true,
        progressText: '{{current}} z {{total}}',
        // Cele są już rozwiązane do konkretnych węzłów (`buildSteps`), ale
        // element może zniknąć MIĘDZY startem a dojściem do kroku (odświeżenie
        // listy) — wtedy krok ma wypaść, a nie zawiesić przewodnik.
        skipMissingElement: true,
        popoverClass: 'traferto-tour',
        nextBtnText: TOUR_TEXTS.next,
        prevBtnText: TOUR_TEXTS.previous,
        doneBtnText: TOUR_TEXTS.done,
        onDestroyed: (_element, _step, opts) => {
          // Menu rozwinięte na potrzeby przewodnika wraca do stanu sprzed startu
          // — także przy odmontowaniu, bo layout z ☰ żyje dłużej niż ekran.
          collapseTargets();

          if (isUnmountingRef.current) {
            return;
          }

          // Numer kroku dla człowieka (od 1), nie indeks tablicy.
          track(TOUR_EVENTS[screen], { krok: (opts.index ?? 0) + 1 });

          if (userId !== null) {
            /*
             * Po UDANYM zapisie bramka czyta wiersz od nowa. Profil pobierany
             * jest raz, NAD `Outlet`-em routera, więc bez tego nawigacja SPA
             * z powrotem na ten ekran zastawała `tour_seen_* = false` i uruchamiała
             * przewodnik PONOWNIE — drugi zapis i drugie zdarzenie analityki,
             * wbrew kontraktowi „jeden raz na konto i ekran" (D18, R13).
             */
            void markTourSeen(userId, screen).then((isSaved) => {
              if (isSaved) {
                reloadProfile();
              }
            });
          }
        },
      });

      instanceRef.current = instance;
      instance.drive();
    };

    /*
     * Programowy `click()` w ☰ ustawia stan Reacta, a React 19 domyka go
     * w MIKROTASKU, nie w trakcie `dispatchEvent` — `buildSteps` tuż po
     * kliknięciu widziało jeszcze zwinięte menu i podświetlało sam ☰ (smoke
     * 9b, tura 2 na telefonie). `flushSync` z wnętrza efektu React odrzuca
     * („cannot flush when React is already rendering"), więc kroki budujemy
     * w KOLEJNYM mikrotasku — React swój zakolejkował wcześniej, w trakcie
     * kliknięcia, więc rozwinięte menu jest już wtedy w DOM. Bez rozwinięcia
     * nie ma na co czekać i start zostaje synchroniczny.
     */
    if (hasExpanded) {
      queueMicrotask(start);
    } else {
      start();
    }

    return () => {
      isCancelled = true;
      isUnmountingRef.current = true;
      instanceRef.current = null;

      if (instance !== null) {
        instance.destroy();
      } else {
        // Sprzątnięcie PRZED mikrotaskiem: przewodnik nie wystartował, więc
        // `onDestroyed` nie zwinie menu za nas.
        collapseTargets();
      }
    };
  }, [isEligible, reloadProfile, screen, userId]);
}

