import { LEGAL_PATHS } from '@oferty/shared';
import * as Sentry from '@sentry/react';
import { AuthError } from '@supabase/supabase-js';
import { cleanup, fireEvent, render, screen, waitFor } from '@testing-library/react';
import type { JSX } from 'react';
import { BrowserRouter, MemoryRouter, Route, Routes, useLocation } from 'react-router';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

import { AUTH_CALLBACK_PATH, INVITATION_PATH } from '../../routes.js';
import { requireElement } from '../../test/require-element.js';
import type { AccountProfile, ProfileReadResult } from '../account/use-profile.js';
import { AUTH_TEXTS } from '../auth/texts.js';
import { ConsentPage } from './consent-page.js';
import { readAuthorizationId } from './consent-request.js';
import { CONSENT_TEXTS } from './texts.js';

/** Kształt wydawany przez Supabase: 32 znaki base32, bez myślników. */
const AUTHORIZATION_ID = 'drs4p6cdwu7jttylrcajgnhwnmg3iyha';
const CONSENT_PATH = `/oauth/consent?authorization_id=${AUTHORIZATION_ID}`;
const REDIRECT_URL = 'https://claude.ai/api/mcp/auth_callback?code=abc&state=xyz';
/** Ścieżka logo z serwera (`BrandLogo`) — jedyny obraz, jaki strona zgody ma prawo nieść. */
const TRAFERTO_LOGO_SRC = '/brand/traferto-logo.svg';

const getUser = vi.fn();
const getAuthorizationDetails = vi.fn();
const approveAuthorization = vi.fn();
const denyAuthorization = vi.fn();
const signOut = vi.fn();

interface OtpCall {
  readonly email: string;
  readonly options: { readonly shouldCreateUser: boolean; readonly emailRedirectTo: string };
}

// Atrapa jest OTYPOWANA (wzorzec `login-page.test.tsx`), żeby `mock.calls`
// niosło `[OtpCall]` zamiast `any[]`: rzutowanie odczytu przepuściłoby zmianę
// ładunku po stronie `LoginForm` — a to on buduje adres powrotu na prośbę.
const signInWithOtp = vi.fn<(params: OtpCall) => unknown>();
const onAuthStateChange = vi.fn();

type AuthStateListener = (event: string, session: unknown) => void;

let authStateListener: AuthStateListener | null = null;

vi.mock('../../lib/supabase.js', () => ({
  supabase: {
    auth: {
      getUser: (): unknown => getUser(),
      signOut: (options: unknown): unknown => signOut(options),
      signInWithOtp: (params: OtpCall): unknown => signInWithOtp(params),
      onAuthStateChange: (listener: AuthStateListener): unknown => onAuthStateChange(listener),
      oauth: {
        getAuthorizationDetails: (id: string): unknown => getAuthorizationDetails(id),
        approveAuthorization: (id: string, options: unknown): unknown =>
          approveAuthorization(id, options),
        denyAuthorization: (id: string, options: unknown): unknown => denyAuthorization(id, options),
      },
    },
  },
}));

vi.mock('@sentry/react', () => ({
  captureException: vi.fn(),
}));

const fetchProfile = vi.fn<(userId: string, signal: AbortSignal) => Promise<ProfileReadResult>>();

vi.mock('../account/use-profile.js', async (importOriginal) => ({
  ...(await importOriginal<typeof import('../account/use-profile.js')>()),
  fetchProfile: (userId: string, signal: AbortSignal): Promise<ProfileReadResult> =>
    fetchProfile(userId, signal),
}));

/** Profil wpuszczany do panelu (kształt `AccountProfile` z `use-profile.ts`). */
function activeProfile(overrides: Partial<AccountProfile> = {}): ProfileReadResult {
  return {
    status: 'gotowe',
    profile: {
      id: 'user-1',
      accessState: 'aktywne',
      role: 'user',
      source: 'akademia',
      termsAcceptedAt: new Date('2026-09-14T09:00:00+00:00'),
      deletionRequestedAt: null,
      hasWebhook: false,
      isFirstStepsDismissed: false,
      tourSeen: { oferty: true, oferta: true, szablony: true },
      ...overrides,
    },
  };
}

const navigateTo = vi.fn();

vi.mock('../../lib/browser-navigation.js', () => ({
  navigateTo: (url: string): void => {
    navigateTo(url);
  },
}));

function authorizationDetails(clientName: string, redirectUri?: string): Record<string, unknown> {
  return {
    authorization_id: AUTHORIZATION_ID,
    redirect_uri: redirectUri ?? 'https://claude.ai/api/mcp/auth_callback',
    client: {
      id: '9a0f2b7c-1d3e-4f50-8a61-2b3c4d5e6f70',
      name: clientName,
      uri: 'https://claude.ai',
      logo_uri: 'https://claude.ai/logo.png',
    },
    user: { id: '11111111-1111-4111-8111-111111111111', email: 'kacper@twojafirma.pl' },
    scope: '',
  };
}

function renderConsent(path = CONSENT_PATH): void {
  render(
    <MemoryRouter initialEntries={[path]}>
      <ConsentPage />
    </MemoryRouter>,
  );
}

beforeEach(() => {
  getUser.mockResolvedValue({ data: { user: { id: 'user-1' } }, error: null });
  fetchProfile.mockResolvedValue(activeProfile());
  onAuthStateChange.mockImplementation((listener: AuthStateListener) => {
    authStateListener = listener;
    return { data: { subscription: { unsubscribe: vi.fn() } } };
  });
  signOut.mockResolvedValue({ error: null });
});

afterEach(() => {
  cleanup();
  vi.clearAllMocks();
  authStateListener = null;
  window.history.pushState({}, '', '/');
});

describe('ConsentPage — brak albo zły identyfikator prośby', () => {
  it.each([
    ['bez parametru', '/oauth/consent'],
    ['z wartością o złym kształcie', '/oauth/consent?authorization_id=nie-identyfikator'],
    // UUID to kształt `client_id`, nie prośby — nie wolno go przepuścić.
    [
      'z UUID zamiast identyfikatora prośby',
      '/oauth/consent?authorization_id=37d3dc5a-2145-4996-b7a5-597bdbcf63e0',
    ],
  ])('%s pokazuje planszę nieaktualnej prośby i NIE pyta Auth API', async (_case, path) => {
    renderConsent(path);

    expect(await screen.findByText(CONSENT_TEXTS.errorTitle)).toBeDefined();
    expect(screen.getByText(CONSENT_TEXTS.errorBody)).toBeDefined();
    expect(screen.getByRole('link', { name: CONSENT_TEXTS.toPanel }).getAttribute('href')).toBe(
      '/oferty',
    );
    expect(getAuthorizationDetails).not.toHaveBeenCalled();
    expect(getUser).not.toHaveBeenCalled();
  });

  it('karta błędu NIE zaprasza do kontaktu', () => {
    // Rozstrzygnięcie planu wbrew makiecie: komunikaty awarii nie mówią
    // „napisz do nas", tylko co zrobić.
    expect(CONSENT_TEXTS.errorBody).not.toContain('napisz do nas');
  });
});

