describe('ConsentPage — prośba z nazwą klienta', () => {
  beforeEach(() => {
    getAuthorizationDetails.mockResolvedValue({
      data: authorizationDetails('Claude'),
      error: null,
    });
  });

  it('pokazuje tytuł z nazwą, cztery punkty zakresu, host powrotu i e-mail', async () => {
    renderConsent();

    expect(await screen.findByRole('heading', { level: 1 })).toHaveProperty(
      'textContent',
      'Claude PROSI O DOSTĘP DO TWOJEGO KONTA',
    );
    expect(screen.getByText(CONSENT_TEXTS.eyebrow)).toBeDefined();

    for (const item of CONSENT_TEXTS.scopeItems) {
      expect(screen.getByText(item)).toBeDefined();
    }
    expect(screen.getAllByRole('listitem')).toHaveLength(CONSENT_TEXTS.scopeItems.length);

    expect(screen.getByText(/kacper@twojafirma\.pl/)).toBeDefined();
    expect(screen.getByText('Po decyzji wrócisz na claude.ai.')).toBeDefined();
    expect(screen.getByText(CONSENT_TEXTS.footnote)).toBeDefined();
    expect(screen.queryByText(CONSENT_TEXTS.missingNameWarning)).toBeNull();
  });

  it('pokazuje linki do regulaminu i prywatności pod kartą', async () => {
    // Ekran decyzji (zalogowany, „Zezwól/Odmów") jedzie przez `ConsentShell`,
    // nie przez `AuthCard` — bez własnego wiersza linków zalogowany handlowiec
    // nie miałby na tej stronie dojścia do dokumentów.
    const { container } = render(
      <MemoryRouter initialEntries={[CONSENT_PATH]}>
        <ConsentPage />
      </MemoryRouter>,
    );

    await screen.findByRole('heading', { level: 1 });

    const termsLinks = screen.getAllByRole('link', { name: 'Regulamin' });
    const privacyLinks = screen.getAllByRole('link', { name: 'Prywatność' });

    expect(termsLinks).toHaveLength(1);
    expect(privacyLinks).toHaveLength(1);

    for (const [link, path] of [
      [termsLinks[0], LEGAL_PATHS.terms],
      [privacyLinks[0], LEGAL_PATHS.privacy],
    ] as const) {
      const anchor = requireElement(link, 'link do dokumentu');
      const main = requireElement(container.querySelector('main'), 'oprawa strony zgody');

      // Trasa serwera na `APP_ORIGIN`, poza SPA: zwykłe `<a>`, ten sam origin,
      // bez nowej karty. Wiersz stoi POZA kartą decyzji, wewnątrz `main`.
      expect(anchor.getAttribute('href')).toBe(path);
      expect(anchor.getAttribute('target')).toBeNull();
      expect(main.contains(anchor)).toBe(true);
      expect(requireElement(main.firstElementChild, 'karta decyzji').contains(anchor)).toBe(false);
    }
  });

  it('nie linkuje ani nie ładuje client_uri i logo_uri', async () => {
    // Obrazek z adresu podanego przez rejestrującego to żądanie wychodzące
    // z konta handlowca (potwierdzenie, że ekran zgody został pokazany),
    // a link nadaje deklaracji rejestrującego wygląd zweryfikowanej.
    const { container } = render(
      <MemoryRouter initialEntries={[CONSENT_PATH]}>
        <ConsentPage />
      </MemoryRouter>,
    );

    await screen.findByRole('heading', { level: 1 });

    // JEDYNY obraz na stronie to logo Traferto (znak zasobu, ścieżka z naszego
    // serwera). Lista `src`, nie licznik: sam „jeden obraz" przepuściłby
    // `logo_uri` klienta wyrenderowane ZAMIAST naszego logo.
    expect([...container.querySelectorAll('img')].map((img) => img.getAttribute('src'))).toEqual([
      TRAFERTO_LOGO_SRC,
    ]);
    expect(container.querySelectorAll('a[href^="https://claude.ai"]')).toHaveLength(0);
  });

  it('logo Traferto oznacza ZASÓB, a nazwa klienta idzie wyłącznie do tytułu', async () => {
    // Nazwa klienta-atrapy CELOWO różna od nazwy produktu: gdyby brzmiała
    // „Traferto", test nie odróżniłby znaku zasobu od deklaracji rejestrującego.
    getAuthorizationDetails.mockResolvedValue({
      data: authorizationDetails('Aplikacja testowa'),
      error: null,
    });

    renderConsent();

    expect(await screen.findByRole('heading', { level: 1 })).toHaveProperty(
      'textContent',
      'Aplikacja testowa PROSI O DOSTĘP DO TWOJEGO KONTA',
    );

    const logos = screen.getAllByAltText('Traferto');

    expect(logos).toHaveLength(1);
    expect(requireElement(logos[0], 'logo Traferto').getAttribute('src')).toBe(TRAFERTO_LOGO_SRC);
    expect(screen.queryByAltText('Aplikacja testowa')).toBeNull();
    expect(document.body.textContent).not.toMatch(/Oferta\s*Online/);
  });
});

describe('ConsentPage — nazwa klienta zza granicy zaufania', () => {
  it('renderuje nazwę ze znacznikiem jako TEKST, bez tworzenia elementu', async () => {
    getAuthorizationDetails.mockResolvedValue({
      data: authorizationDetails('<img src=x onerror=alert(1)>'),
      error: null,
    });

    const { container } = render(
      <MemoryRouter initialEntries={[CONSENT_PATH]}>
        <ConsentPage />
      </MemoryRouter>,
    );

    const heading = await screen.findByRole('heading', { level: 1 });

    expect(heading.textContent).toBe('<img src=x onerror=alert(1)> PROSI O DOSTĘP DO TWOJEGO KONTA');
    // Jedyny `<img>` w drzewie to logo Traferto z naszego serwera — znacznik
    // z nazwy klienta nie utworzył elementu (lista `src`, nie licznik).
    expect([...container.querySelectorAll('img')].map((img) => img.getAttribute('src'))).toEqual([
      TRAFERTO_LOGO_SRC,
    ]);
  });

  it('nie rozwija wzorców $ z nazwy klienta w tytule', async () => {
    // `$'` w łańcuchu zastępującym `String.replace` znaczy „reszta tekstu po
    // dopasowaniu", więc nazwa `Claude$'` dublowała tytuł, a 32 powtórzenia
    // (64 znaki, czyli PRZECHODZĄCE sanityzację) rozwijały się w ~1 KB w <h1>.
    getAuthorizationDetails.mockResolvedValue({
      data: authorizationDetails("Claude$'"),
      error: null,
    });

    renderConsent();

    const heading = await screen.findByRole('heading', { level: 1 });

    expect(heading.textContent).toBe("Claude$' PROSI O DOSTĘP DO TWOJEGO KONTA");
  });

  it("nazwa z 32 powtórzeniami $' nie rozdmuchuje tytułu", async () => {
    const name = "$'".repeat(32);

    getAuthorizationDetails.mockResolvedValue({
      data: authorizationDetails(name),
      error: null,
    });

    renderConsent();

    const heading = await screen.findByRole('heading', { level: 1 });

    expect(heading.textContent).toBe(`${name} PROSI O DOSTĘP DO TWOJEGO KONTA`);
    expect(heading.textContent?.length).toBe(
      name.length + ' PROSI O DOSTĘP DO TWOJEGO KONTA'.length,
    );
  });

  it('przycina nazwę 300-znakową do 64 znaków', async () => {
    getAuthorizationDetails.mockResolvedValue({
      data: authorizationDetails('x'.repeat(300)),
      error: null,
    });

    renderConsent();

    const heading = await screen.findByRole('heading', { level: 1 });

    expect(heading.textContent).toBe(`${'x'.repeat(64)} PROSI O DOSTĘP DO TWOJEGO KONTA`);
  });

  it('pusta nazwa daje tytuł zastępczy, ostrzeżenie i inny dopisek', async () => {
    getAuthorizationDetails.mockResolvedValue({
      data: authorizationDetails('   '),
      error: null,
    });

    renderConsent();

    expect(await screen.findByRole('heading', { level: 1 })).toHaveProperty(
      'textContent',
      CONSENT_TEXTS.titleFallback,
    );
    expect(screen.getByText(CONSENT_TEXTS.missingNameWarning)).toBeDefined();
    expect(screen.getByText(CONSENT_TEXTS.footnoteFallback)).toBeDefined();
    expect(screen.queryByText(CONSENT_TEXTS.footnote)).toBeNull();
  });

  it('adres powrotu w pętli zwrotnej dokłada ostrzeżenie', async () => {
    getAuthorizationDetails.mockResolvedValue({
      data: authorizationDetails('Claude', 'http://127.0.0.1:9876/oauth/callback'),
      error: null,
    });

    renderConsent();

    expect(
      await screen.findByText(/odeśle Cię na adres na Twoim komputerze \(127\.0\.0\.1:9876\)/),
    ).toBeDefined();
  });
});

