describe('ConsentPage — decyzje', () => {
  beforeEach(() => {
    getAuthorizationDetails.mockResolvedValue({
      data: authorizationDetails('Claude'),
      error: null,
    });
  });

  it('dwa kliknięcia „Zezwól" dają JEDNO żądanie i przekierowanie', async () => {
    approveAuthorization.mockResolvedValue({ data: { redirect_url: REDIRECT_URL }, error: null });

    renderConsent();

    const approve = await screen.findByRole('button', { name: CONSENT_TEXTS.approve });
    fireEvent.click(approve);
    fireEvent.click(approve);

    await waitFor(() => {
      expect(navigateTo).toHaveBeenCalledExactlyOnceWith(REDIRECT_URL);
    });
    expect(approveAuthorization).toHaveBeenCalledExactlyOnceWith(AUTHORIZATION_ID, {
      skipBrowserRedirect: true,
    });
  });

  it('po „Zezwól" podpis szkieletu mówi o powrocie, nie o sprawdzaniu prośby', async () => {
    // Decyzja operatora 2026-09-08 (smoke fazy 8, poz. 5.4b): makiety nie mają
    // artboardu przekierowania, a „Sprawdzamy, kto prosi o dostęp…" PO decyzji
    // jest zdaniem nie na temat — przy wolnym łączu handlowiec je przeczyta.
    approveAuthorization.mockResolvedValue({ data: { redirect_url: REDIRECT_URL }, error: null });

    renderConsent();

    fireEvent.click(await screen.findByRole('button', { name: CONSENT_TEXTS.approve }));

    expect(await screen.findByText(CONSENT_TEXTS.redirecting)).toBeDefined();
    expect(screen.queryByText(CONSENT_TEXTS.loading)).toBeNull();
    expect(screen.queryByRole('button', { name: CONSENT_TEXTS.approve })).toBeNull();
    await waitFor(() => {
      expect(navigateTo).toHaveBeenCalledExactlyOnceWith(REDIRECT_URL);
    });
  });

  it('„Odmów" pokazuje planszę odmowy i przekierowuje z błędem access_denied', async () => {
    const deniedUrl = 'https://claude.ai/api/mcp/auth_callback?error=access_denied';
    denyAuthorization.mockResolvedValue({ data: { redirect_url: deniedUrl }, error: null });

    renderConsent();

    fireEvent.click(await screen.findByRole('button', { name: CONSENT_TEXTS.deny }));

    expect(await screen.findByText(CONSENT_TEXTS.deniedTitle)).toBeDefined();
    expect(screen.getByText(CONSENT_TEXTS.deniedBody)).toBeDefined();
    expect(denyAuthorization).toHaveBeenCalledExactlyOnceWith(AUTHORIZATION_ID, {
      skipBrowserRedirect: true,
    });
    expect(navigateTo).toHaveBeenCalledExactlyOnceWith(deniedUrl);
  });

  it('„To nie Ty? Wyloguj się" wylogowuje lokalnie i wraca do karty logowania', async () => {
    renderConsent();

    fireEvent.click(await screen.findByRole('button', { name: CONSENT_TEXTS.signOut }));

    expect(await screen.findByRole('heading', { level: 1, name: AUTH_TEXTS.title })).toBeDefined();
    expect(signOut).toHaveBeenCalledExactlyOnceWith({ scope: 'local' });
  });

  it('utrata sesji w trakcie prośby odsyła na kartę logowania', async () => {
    renderConsent();

    await screen.findByRole('button', { name: CONSENT_TEXTS.approve });

    requireElement(authStateListener, 'słuchacz onAuthStateChange')('SIGNED_OUT', null);

    expect(await screen.findByRole('heading', { level: 1, name: AUTH_TEXTS.title })).toBeDefined();
    expect(screen.getByText(CONSENT_TEXTS.loginNotice)).toBeDefined();
  });
});

