describe('ConsentPage — niezalogowany', () => {
  beforeEach(() => {
    getUser.mockResolvedValue({
      data: { user: null },
      error: new AuthError('Auth session missing!', 400, 'session_not_found'),
    });
  });

  it('pokazuje kartę logowania z dopiskiem o powrocie do prośby', async () => {
    renderConsent();

    expect(await screen.findByRole('heading', { level: 1, name: AUTH_TEXTS.title })).toBeDefined();
    expect(screen.getByText(CONSENT_TEXTS.loginNotice)).toBeDefined();
    expect(screen.queryByRole('button', { name: CONSENT_TEXTS.approve })).toBeNull();
  });

  it('magic link wraca na TĘ SAMĄ prośbę', async () => {
    signInWithOtp.mockResolvedValue({ error: null });

    renderConsent();

    const input = await screen.findByLabelText(AUTH_TEXTS.emailLabel);
    fireEvent.change(input, { target: { value: 'kacper@twojafirma.pl' } });
    fireEvent.submit(requireElement(input.closest('form'), 'formularz logowania'));

    await waitFor(() => {
      expect(signInWithOtp).toHaveBeenCalledTimes(1);
    });

    const [call] = requireElement(signInWithOtp.mock.calls[0], 'wywołanie signInWithOtp');

    expect(call.options.emailRedirectTo).toBe(
      `${window.location.origin}/oauth/consent?authorization_id=${AUTHORIZATION_ID}`,
    );
  });

  it('limit mailera pokazuje ten sam komunikat co na /logowanie', async () => {
    signInWithOtp.mockResolvedValue({
      error: new AuthError('rate limit', 429, 'over_email_send_rate_limit'),
    });

    renderConsent();

    const input = await screen.findByLabelText(AUTH_TEXTS.emailLabel);
    fireEvent.change(input, { target: { value: 'kacper@twojafirma.pl' } });
    fireEvent.submit(requireElement(input.closest('form'), 'formularz logowania'));

    expect(await screen.findByRole('alert')).toHaveProperty(
      'textContent',
      AUTH_TEXTS.rateLimitError,
    );
  });
});

describe('ConsentPage — wygasły magic link', () => {
  it('pokazuje planszę wygasłego linku z ponowną wysyłką i zachowuje authorization_id', async () => {
    // Wygasły link znaczy „nie zalogowano", więc kontroler musi POTWIERDZIĆ
    // brak sesji — plansza nie wygrywa już bezwarunkowo.
    getUser.mockResolvedValue({
      data: { user: null },
      error: new AuthError('Auth session missing!', 400, 'session_not_found'),
    });
    signInWithOtp.mockResolvedValue({ error: null });

    renderConsent(`${CONSENT_PATH}#error=access_denied&error_code=otp_expired`);

    expect(await screen.findByRole('alert')).toHaveProperty(
      'textContent',
      AUTH_TEXTS.expiredLink,
    );
    // Bez pytania o szczegóły: sesji nie ma, a prośba czeka na zalogowanie.
    expect(getAuthorizationDetails).not.toHaveBeenCalled();

    const input = screen.getByLabelText(AUTH_TEXTS.emailLabel);
    fireEvent.change(input, { target: { value: 'kacper@twojafirma.pl' } });
    fireEvent.submit(requireElement(input.closest('form'), 'formularz logowania'));

    await waitFor(() => {
      expect(signInWithOtp).toHaveBeenCalledTimes(1);
    });

    const [call] = requireElement(signInWithOtp.mock.calls[0], 'wywołanie signInWithOtp');

    expect(call.options.emailRedirectTo).toContain(`authorization_id=${AUTHORIZATION_ID}`);
  });

  it('zalogowany z zużytym linkiem widzi PROŚBĘ, nie planszę wygasłego linku', async () => {
    // Ten sam adres otwarty z historii poczty: sesja w przeglądarce jest
    // ważna, więc decyzję da się podjąć od razu. Plansza „link wygasł"
    // odsyłałaby po kolejny mail (limit 2/h) przy prośbie żyjącej 10 minut.
    getAuthorizationDetails.mockResolvedValue({
      data: authorizationDetails('Claude'),
      error: null,
    });

    renderConsent(`${CONSENT_PATH}#error=access_denied&error_code=otp_expired`);

    expect(await screen.findByRole('heading', { level: 1 })).toHaveProperty(
      'textContent',
      'Claude PROSI O DOSTĘP DO TWOJEGO KONTA',
    );
    expect(screen.getByRole('button', { name: CONSENT_TEXTS.approve })).toBeDefined();
    expect(screen.queryByText(AUTH_TEXTS.expiredLink)).toBeNull();
    expect(getAuthorizationDetails).toHaveBeenCalledWith(AUTHORIZATION_ID);
  });

  it.each([
    ['bez parametru', '/oauth/consent'],
    ['z parametrem o złym kształcie', '/oauth/consent?authorization_id=nie-identyfikator'],
  ])(
    'wygasły link %s daje kartę logowania z ponowną wysyłką, nie ślepą planszę',
    async (_case, path) => {
      // Bez identyfikatora prośby kontroler wchodzi prosto w `invalid_id`,
      // więc plansza wygasłego linku NIE może zależeć od stanu `anonymous` —
      // inaczej jedyne, co widzi handlowiec po zużytym linku bez parametru, to
      // „ta prośba jest już nieaktualna" bez ani jednej akcji.
      signInWithOtp.mockResolvedValue({ error: null });

      renderConsent(`${path}#error=access_denied&error_code=otp_expired`);

      expect(await screen.findByRole('alert')).toHaveProperty(
        'textContent',
        AUTH_TEXTS.expiredLink,
      );
      expect(screen.queryByText(CONSENT_TEXTS.errorTitle)).toBeNull();

      const input = screen.getByLabelText(AUTH_TEXTS.emailLabel);
      fireEvent.change(input, { target: { value: 'kacper@twojafirma.pl' } });
      fireEvent.submit(requireElement(input.closest('form'), 'formularz logowania'));

      await waitFor(() => {
        expect(signInWithOtp).toHaveBeenCalledTimes(1);
      });

      // Prośby nie znamy, więc powrót celuje w zwykły callback panelu.
      expect(signInWithOtp).toHaveBeenCalledWith(
        expect.objectContaining({
          options: expect.objectContaining({
            emailRedirectTo: `${window.location.origin}${AUTH_CALLBACK_PATH}`,
          }),
        }),
      );
      expect(getAuthorizationDetails).not.toHaveBeenCalled();
    },
  );
});

describe('ConsentPage — identyfikator prośby a konsumpcja fragmentu', () => {
  it('przeżywa replaceState, który kasuje WYŁĄCZNIE fragment adresu', async () => {
    getAuthorizationDetails.mockResolvedValue({
      data: authorizationDetails('Claude'),
      error: null,
    });

    window.history.pushState({}, '', `${CONSENT_PATH}#access_token=abc&type=magiclink`);
    // Dokładnie to robi `detectSessionInUrl` w flow implicit (`lib/supabase.ts`):
    // przypisuje pusty `location.hash`, zostawiając ścieżkę i część zapytania
    // nietknięte. `history.replaceState` auth-js stosuje wyłącznie w gałęzi
    // PKCE, którą ten panel nie idzie.
    window.location.hash = '';

    expect(window.location.hash).toBe('');
    expect(window.location.search).toBe(`?authorization_id=${AUTHORIZATION_ID}`);
    expect(readAuthorizationId(window.location.search)).toBe(AUTHORIZATION_ID);

    render(
      <BrowserRouter>
        <ConsentPage />
      </BrowserRouter>,
    );

    expect(await screen.findByRole('heading', { level: 1 })).toHaveProperty(
      'textContent',
      'Claude PROSI O DOSTĘP DO TWOJEGO KONTA',
    );
    expect(getAuthorizationDetails).toHaveBeenCalledWith(AUTHORIZATION_ID);
  });
});

describe('ConsentPage — awaria odczytu prośby', () => {
  it('404 daje planszę nieaktualnej prośby, a raport do Sentry nie niesie authorization_id', async () => {
    getAuthorizationDetails.mockResolvedValue({
      data: null,
      error: new AuthError('Authorization request not found', 404, 'not_found'),
    });

    renderConsent();

    expect(await screen.findByText(CONSENT_TEXTS.errorTitle)).toBeDefined();

    const calls = vi.mocked(Sentry.captureException).mock.calls;
    expect(calls).toHaveLength(1);

    const [reported] = requireElement(calls[0], 'wywołanie captureException');
    const message = reported instanceof Error ? reported.message : String(reported);

    expect(message).not.toContain(AUTHORIZATION_ID);
  });
});

