import { MIN_USABLE_FRAME_PX } from '@oferty/shared';
import { cleanup, fireEvent, render, screen, waitFor, within } from '@testing-library/react';
import type { JSX } from 'react';
import { MemoryRouter, Route, Routes, useLocation, useParams } from 'react-router';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

import { requireElement, requireInstance } from '../../test/require-element.js';
import type { AccountLimitsState } from '../account/use-account-limits.js';
import type { FirstStepsState } from '../onboarding/use-first-steps.js';
import { OffersPage } from './offers-page.js';
import { OFFERS_TEXTS, STATUS_LABELS } from './texts.js';

const from = vi.fn();
const select = vi.fn();
const order = vi.fn();
const abortSignal = vi.fn();
/**
 * Liczniki „Wizyty"/„Osoby" idą DRUGIM żądaniem — RPC `offers_visit_summary`
 * po `id[]` ofert (faza 9a). Atrapa oddaje wiersze dla ofert, które w fikszturze
 * dostały liczby (`summaryFor`), a pozostałe zostają bez wiersza = zera.
 */
const rpc = vi.fn();
const rpcAbortSignal = vi.fn();

vi.mock('../../lib/supabase.js', () => ({
  supabase: {
    from: (table: string): unknown => from(table),
    rpc: (fn: string, args: unknown): unknown => rpc(fn, args),
  },
}));

/**
 * Hook limitów jako atrapa MODUŁU, nie atrapa `supabase.rpc`: strona ma
 * reagować na STAN hooka, a arytmetyka progów i kształt RPC mają własne testy
 * w `features/account`. Domyślnie `niedostepne` — wariant, w którym lista
 * MUSI działać jak przed fazą 9a.
 */
const accountLimits = vi.fn<() => AccountLimitsState>(() => ({ status: 'niedostepne' }));

vi.mock('../account/use-account-limits.js', () => ({
  useAccountLimits: (): AccountLimitsState => accountLimits(),
}));

/**
 * Onboarding (faza 9b) jako atrapy MODUŁÓW: checklista ma własne testy
 * (`features/onboarding`) i własne zapytania do bazy, a przewodnik dotyka
 * `driver.js` i kontekstu bramki dostępu. Ta strona odpowiada wyłącznie za to,
 * GDZIE karta stoi i że stan pusty listy jest jednym zdaniem pod nią.
 */
const firstStepsCard = vi.fn<() => JSX.Element | null>(() => null);
const screenTour = vi.fn<(screen: string, isPending: boolean) => void>();
/** Stan checklisty — strona czyta go sama, bo od niego zależy start przewodnika. */
const firstSteps = vi.fn<() => FirstStepsState>(() => ({ status: 'ukryta' }));

vi.mock('../onboarding/first-steps-card.js', () => ({
  FirstStepsCard: (): JSX.Element | null => firstStepsCard(),
}));

vi.mock('../onboarding/use-first-steps.js', () => ({
  useFirstSteps: (): FirstStepsState => firstSteps(),
}));

vi.mock('../onboarding/use-screen-tour.js', () => ({
  useScreenTour: (screen: string, isPending: boolean): void => {
    screenTour(screen, isPending);
  },
}));

function limitsReady(used: number, limit: number): void {
  accountLimits.mockReturnValue({
    status: 'gotowe',
    limits: {
      oferty_miesiac: { used, limit, resetsAt: new Date('2026-10-01T00:00:00+00:00') },
      publikacje_godzina: { used: 0, limit: 25, resetsAt: null },
      szablony: { used: 0, limit: 10, resetsAt: null },
      storage: { used: 0, limit: 209_715_200, resetsAt: null },
    },
  });
}

/** DOKŁADNIE kolumny z `OFFER_COLUMNS` produkcji — bez `visits`, z `id`. */
interface FakeRow {
  readonly id: string;
  readonly slug: string;
  readonly offer_title: string;
  readonly status: string;
  readonly created_at: string;
  readonly expires_at: string;
}

/** Wiersz RPC w kształcie migracji `20260913140000`. */
interface FakeSummaryRow {
  readonly offer_id: string;
  readonly visit_count: number;
  readonly people_estimate: number;
  readonly last_visit_at: string | null;
}

/**
 * Agregat oferty: `count` wizyt od `people` osób — liczby, które przed fazą 9a
 * panel wyprowadzał z osadzonych hashy, a teraz dostaje gotowe z bazy.
 */
function summaryFor(id: string, count: number, people: number): FakeSummaryRow {
  return {
    offer_id: id,
    visit_count: count,
    people_estimate: people,
    last_visit_at: '2026-09-10T10:00:00.000Z',
  };
}

function offerRow(overrides: Partial<FakeRow> = {}): FakeRow {
  const slug = overrides.slug ?? 'oferta-alfa';

  return {
    // `id` wyprowadzone ze sluga, żeby fikstura RPC mogła wskazać ofertę po
    // slugu (`summaryFor(idOf('alfa'), …)`) bez drugiej mapy w teście.
    id: idOf(slug),
    slug,
    offer_title: 'Automatyzacja obsługi zgłoszeń — Biurowiec Alfa',
    status: 'wyslana',
    created_at: '2026-08-25T09:00:00.000Z',
    expires_at: '2126-09-24T09:00:00.000Z',
    ...overrides,
  };
}

function idOf(slug: string): string {
  return `id-${slug}`;
}

function respondWith(result: unknown): void {
  abortSignal.mockResolvedValue(result);
}

function respondWithSummaries(rows: readonly FakeSummaryRow[]): void {
  rpcAbortSignal.mockResolvedValue({ data: rows, error: null });
}

/** Sonda adresu — filtr i sortowanie żyją w nim, więc test musi go widzieć. */
function CurrentSearch(): JSX.Element {
  const location = useLocation();

  return <span data-testid="search">{location.search}</span>;
}

function currentSearch(): string {
  return screen.getByTestId('search').textContent ?? '';
}

function renderPage(entry = '/oferty'): void {
  render(
    <MemoryRouter initialEntries={[entry]}>
      <CurrentSearch />
      <OffersPage />
    </MemoryRouter>,
  );
}

/** Sonda widoku oferty — test nawigacji sprawdza adres, nie zawartość widoku. */
function OfferDetailsProbe(): JSX.Element {
  const { slug } = useParams<{ slug: string }>();

  return <p>{`widok oferty: ${slug ?? ''}`}</p>;
}

function renderWithRoutes(): void {
  render(
    <MemoryRouter initialEntries={['/oferty']}>
      <Routes>
        <Route path="/oferty" element={<OffersPage />} />
        <Route path="/oferty/:slug" element={<OfferDetailsProbe />} />
      </Routes>
    </MemoryRouter>,
  );
}

beforeEach(() => {
  // `resetAllMocks` w `afterEach` przywraca implementacje z `vi.fn(impl)`;
  // stan checklisty i tak stoi tu jawnie, żeby domyślną wartość testu było
  // widać w jednym miejscu.
  firstSteps.mockReturnValue({ status: 'ukryta' });
  from.mockReturnValue({ select });
  select.mockReturnValue({ order });
  order.mockReturnValue({ abortSignal });
  rpc.mockReturnValue({ abortSignal: rpcAbortSignal });
  respondWith({ data: [], error: null });
  respondWithSummaries([]);
});

afterEach(() => {
  cleanup();
  // `resetAllMocks`, nie `clearAllMocks`: `clear` kasuje tylko historię
  // wywołań, a `mockReturnValue` z pojedynczego przypadku (np. checklista
  // podstawiona `<section>`) przeciekałby do następnego testu.
  vi.resetAllMocks();
  accountLimits.mockReturnValue({ status: 'niedostepne' });
});

describe('OffersPage — baner limitu ofert w miesiącu', () => {
  it('stan `niedostepne` hooka → lista renderuje się bez banera', async () => {
    respondWith({ data: [offerRow({ slug: 'alfa' })], error: null });

    renderPage();

    expect(await screen.findByRole('table')).toBeDefined();
    expect(screen.queryByRole('status')).toBeNull();
  });

  it('4 z 5 → baner „uwaga" nad listą, z tekstem verbatim z planu', async () => {
    respondWith({ data: [offerRow({ slug: 'alfa' })], error: null });
    limitsReady(4, 5);

    renderPage();

    const table = await screen.findByRole('table');
    const banner = screen.getByRole('status');

    expect(banner.textContent).toBe(
      'Wykorzystujesz 4 z 5 ofert w tym miesiącu. Licznik zeruje się 01.10.2026.',
    );
    // NAD listą: baner poprzedza tabelę w porządku dokumentu.
    expect(banner.compareDocumentPosition(table) & Node.DOCUMENT_POSITION_FOLLOWING).toBeTruthy();
  });

  it('5 z 5 → baner „limit" także przy koncie bez ofert na liście', async () => {
    // Oferty liczy RPC (miesiąc kalendarzowy), nie tablica listy — baner
    // nie jest zależny od tego, czy tabela ma wiersze.
    limitsReady(5, 5);

    renderPage();

    expect(await screen.findByText(OFFERS_TEXTS.emptyList)).toBeDefined();
    expect(screen.getByRole('status').textContent).toBe(
      'Limit 5 ofert w tym miesiącu jest wykorzystany. Kolejną ofertę opublikujesz od 01.10.2026.',
    );
  });

  it('3 z 5 → bez banera', async () => {
    respondWith({ data: [offerRow({ slug: 'alfa' })], error: null });
    limitsReady(3, 5);

    renderPage();

    expect(await screen.findByRole('table')).toBeDefined();
    expect(screen.queryByRole('status')).toBeNull();
  });
});


describe('OffersPage — stan pusty', () => {
  it('konto bez ofert dostaje jedno zdanie POD checklistą, nie kartę onboardingu', async () => {
    firstStepsCard.mockReturnValue(<section data-testid="checklista" />);

    renderPage();

    const empty = await screen.findByText(OFFERS_TEXTS.emptyList);
    const card = screen.getByTestId('checklista');

    // Kolejność z R12: checklista prowadzi, zdanie o pustej liście idzie pod nią.
    expect(card.compareDocumentPosition(empty) & Node.DOCUMENT_POSITION_FOLLOWING).toBeTruthy();
    expect(screen.queryByRole('table')).toBeNull();
  });

  it('konto bez ofert nie dostaje ani kafli, ani kontrolek — nie ma czego filtrować', async () => {
    renderPage();

    expect(await screen.findByText(OFFERS_TEXTS.emptyList)).toBeDefined();
    expect(screen.queryByLabelText(OFFERS_TEXTS.filterStatusLabel)).toBeNull();
    expect(screen.queryByLabelText(OFFERS_TEXTS.sortLabel)).toBeNull();
    expect(screen.queryByText(OFFERS_TEXTS.statTotal)).toBeNull();
  });

  it('checklista stoi na liście TAKŻE wtedy, gdy oferty są (R12)', async () => {
    firstStepsCard.mockReturnValue(<section data-testid="checklista" />);
    respondWith({ data: [offerRow({ slug: 'alfa' })], error: null });

    renderPage();

    expect(await screen.findByRole('table')).toBeDefined();
    expect(screen.getByTestId('checklista')).toBeDefined();
    expect(screen.queryByText(OFFERS_TEXTS.emptyList)).toBeNull();
  });

  it('przewodnik dostaje ekran „oferty" i czeka na odpowiedź listy', async () => {
    renderPage();

    await screen.findByText(OFFERS_TEXTS.emptyList);

    expect(screenTour).toHaveBeenCalledWith('oferty', true);
    expect(screenTour).toHaveBeenLastCalledWith('oferty', false);
  });

  it('przewodnik czeka TAKŻE na checklistę, mimo gotowej listy', async () => {
    // Pierwszy krok przewodnika celuje w kartę checklisty, a rysuje ją inny
    // łańcuch zapytań niż listę ofert: start na samej „liście gotowej" gubił
    // ten krok po cichu (`buildSteps` robi jednorazowy snapshot DOM-u).
    firstSteps.mockReturnValue({ status: 'ladowanie' });

    renderPage();

    await screen.findByText(OFFERS_TEXTS.emptyList);

    expect(screenTour).toHaveBeenLastCalledWith('oferty', true);
  });
});

describe('OffersPage — lista z danymi', () => {
  beforeEach(() => {
    respondWithSummaries([summaryFor(idOf('alfa'), 7, 4)]);
    respondWith({
      data: [
        offerRow({ slug: 'alfa' }),
        offerRow({ slug: 'beta', offer_title: 'Wdrożenie wentylacji — Nord Vent' }),
        offerRow({
          slug: 'gamma',
          offer_title: 'Audyt procesów — Kancelaria Lex',
          status: 'otwarta',
          expires_at: '2026-08-01T09:00:00.000Z',
        }),
        offerRow({ slug: 'delta', offer_title: 'Szkolenia — Studio Kreska', status: 'otwarta' }),
      ],
      error: null,
    });
  });

  it('pas statystyk liczy zbiorczo statusy wyświetlane, nie kolumnę status', async () => {
    renderPage();

    expect(await screen.findByRole('table')).toBeDefined();

    const tileValue = (label: string): string =>
      requireElement(screen.getByText(label).previousElementSibling, `liczba kafla „${label}”`)
        .textContent ?? '';

    expect(tileValue(OFFERS_TEXTS.statTotal)).toBe('4');
    expect(tileValue(OFFERS_TEXTS.statSent)).toBe('2');
    expect(tileValue(OFFERS_TEXTS.statOpen)).toBe('1');
    expect(tileValue(OFFERS_TEXTS.statAccepted)).toBe('0');
    expect(tileValue(OFFERS_TEXTS.statExpired)).toBe('1');
  });

  it('tabela desktop pokazuje daty, badge wyprowadzony z expires_at i realne liczniki', async () => {
    renderPage();

    const table = within(await screen.findByRole('table'));

    // Dopisek „(szacunek)" jest obowiązkiem R9, nie ozdobą nagłówka.
    expect(table.getByRole('columnheader', { name: OFFERS_TEXTS.columnPeople }).textContent).toBe(
      'Osoby (szacunek)',
    );

    const expiredRow = table.getByRole('row', { name: /Audyt procesów/ });
    expect(within(expiredRow).getByText(STATUS_LABELS.wygasla)).toBeDefined();
    expect(within(expiredRow).getByText('01.08.2026')).toBeDefined();
    // Oferta bez wizyt pokazuje zera, nie myślnik z tooltipem.
    expect(within(expiredRow).getAllByText('0')).toHaveLength(2);

    const sentRow = table.getByRole('row', { name: /Biurowiec Alfa/ });
    expect(within(sentRow).getByText(STATUS_LABELS.wyslana)).toBeDefined();
    expect(within(sentRow).getByText('25.08.2026')).toBeDefined();
    expect(await within(sentRow).findByText('7')).toBeDefined();
    expect(within(sentRow).getByText('4')).toBeDefined();
    expect(screen.queryByText(/pojawią się wkrótce/)).toBeNull();
    // Liczniki idą z RPC po `id[]` WSZYSTKICH ofert, nie z osadzonych wizyt.
    expect(rpc).toHaveBeenCalledWith('offers_visit_summary', {
      p_offer_ids: ['id-alfa', 'id-beta', 'id-gamma', 'id-delta'],
      p_min_frame_px: MIN_USABLE_FRAME_PX,
    });
  });

  it('awaria RPC (obraz przed migracją) zostawia oferty, a kolumny liczników pokazują pauzę', async () => {
    rpcAbortSignal.mockResolvedValue({
      data: null,
      error: { code: 'PGRST202', message: 'Could not find the function' },
    });

    renderPage();

    const table = within(await screen.findByRole('table'));
    const sentRow = table.getByRole('row', { name: /Biurowiec Alfa/ });
    const dashes = await within(sentRow).findAllByLabelText(OFFERS_TEXTS.counterUnavailableLabel);

    expect(dashes).toHaveLength(2);
    expect(table.getAllByRole('row')).toHaveLength(5);
    expect(screen.queryByText(OFFERS_TEXTS.loadError)).toBeNull();
    // Pas statystyk nie zależy od wizyt — liczy statusy jak przed fazą 9a.
    expect(screen.getByText(OFFERS_TEXTS.statTotal)).toBeDefined();
  });

  it('wariant mobilny daje metę z zakresem dat, wizytami i szacunkiem osób', async () => {
    renderPage();

    const rows = within(await screen.findByRole('list')).getAllByRole('listitem');

    expect(rows).toHaveLength(4);
    const [first, second] = rows.map((row, index) =>
      requireElement(row, `wiersz listy nr ${String(index)}`),
    );

    expect(
      await within(requireElement(first, 'wiersz pierwszej oferty')).findByText(
        '25.08 → 24.09 · 7 wizyt · ~4 osoby',
      ),
    ).toBeDefined();
    expect(
      within(requireElement(second, 'wiersz drugiej oferty')).getByText('25.08 → 24.09 · 0 wizyt'),
    ).toBeDefined();
  });

  it('kliknięcie wiersza prowadzi do widoku oferty pod jej slugiem', async () => {
    renderWithRoutes();

    const table = within(await screen.findByRole('table'));
    const link = within(table.getByRole('row', { name: /Biurowiec Alfa/ })).getByRole('link');

    expect(link).toHaveProperty('pathname', '/oferty/alfa');

    fireEvent.click(link);

    expect(await screen.findByText('widok oferty: alfa')).toBeDefined();
  });
});

/**
 * Czternaście ofert: 4 wysłane · 3 otwarte · 6 zaakceptowanych · 1 wygasła
 * (po `expires_at`, w bazie „wyslana"). Ta sama rozpiska co w scenariuszach
 * planu — kafle mają pokazać `14/4/3/6/1`.
 */
const FOURTEEN_OFFERS: readonly FakeRow[] = [
  offerRow({ slug: 'w1', offer_title: 'Alfa audyt', created_at: '2026-09-01T09:00:00.000Z' }),
  offerRow({
    slug: 'w2',
    offer_title: 'Ąkcent wdrożenie',
    created_at: '2026-08-30T09:00:00.000Z',
  }),
  offerRow({ slug: 'w3', offer_title: 'Beta migracja', created_at: '2026-08-29T09:00:00.000Z' }),
  offerRow({ slug: 'w4', offer_title: 'Cegła szkolenia', created_at: '2026-08-28T09:00:00.000Z' }),
  offerRow({
    slug: 'o1',
    offer_title: 'Dach serwis',
    status: 'otwarta',
    created_at: '2026-09-05T09:00:00.000Z',
  }),
  offerRow({
    slug: 'o2',
    offer_title: 'Elektryka audyt',
    status: 'otwarta',
    created_at: '2026-08-27T09:00:00.000Z',
  }),
  offerRow({
    slug: 'o3',
    offer_title: 'Fabryka linia',
    status: 'otwarta',
    created_at: '2026-08-26T09:00:00.000Z',
  }),
  offerRow({ slug: 'z1', offer_title: 'Gwarancja plan', status: 'zaakceptowana', created_at: '2026-08-25T09:00:00.000Z' }),
  offerRow({ slug: 'z2', offer_title: 'Hala montaż', status: 'zaakceptowana', created_at: '2026-08-24T09:00:00.000Z' }),
  offerRow({ slug: 'z3', offer_title: 'Instalacja pomp', status: 'zaakceptowana', created_at: '2026-08-23T09:00:00.000Z' }),
  offerRow({ slug: 'z4', offer_title: 'Jakość kontrola', status: 'zaakceptowana', created_at: '2026-08-22T09:00:00.000Z' }),
  offerRow({ slug: 'z5', offer_title: 'Kadry portal', status: 'zaakceptowana', created_at: '2026-08-21T09:00:00.000Z' }),
  offerRow({ slug: 'z6', offer_title: 'Logistyka mapa', status: 'zaakceptowana', created_at: '2026-08-20T09:00:00.000Z' }),
  offerRow({
    slug: 'x1',
    offer_title: 'Magazyn WMS',
    created_at: '2026-07-01T09:00:00.000Z',
    expires_at: '2026-08-01T09:00:00.000Z',
  }),
];

/**
 * Agregaty dla czternastu ofert: dwie po 12 wizyt (remis rozstrzyga data
 * publikacji) i jedna z trzema — reszta bez wiersza, czyli zera.
 */
const FOURTEEN_SUMMARIES: readonly FakeSummaryRow[] = [
  summaryFor(idOf('w2'), 12, 5),
  summaryFor(idOf('o1'), 12, 3),
  summaryFor(idOf('o2'), 3, 2),
];

/**
 * Tytuły wierszy tabeli w kolejności wyświetlania. Wiersz pustego wyniku nie ma
 * `rowheader`, więc szukamy go zapytaniem `queryAll` i odsiewamy — pusta lista
 * tytułów jest tu poprawnym wynikiem, nie błędem zapytania.
 */
function rowTitles(): readonly string[] {
  return within(screen.getByRole('table'))
    .getAllByRole('row')
    .slice(1)
    .flatMap((row) => within(row).queryAllByRole('rowheader'))
    .map((header) => header.textContent ?? '');
}

function statusSelect(): HTMLSelectElement {
  return requireInstance(
    screen.getByLabelText(OFFERS_TEXTS.filterStatusLabel),
    HTMLSelectElement,
    'select statusu',
  );
}

describe('OffersPage — filtr statusu w adresie', () => {
  beforeEach(() => {
    respondWith({ data: FOURTEEN_OFFERS, error: null });
  });

  it('bez parametrów pokazuje komplet ofert i licznik bez „z"', async () => {
    renderPage();

    expect(await screen.findByRole('table')).toBeDefined();
    expect(rowTitles()).toHaveLength(14);
    expect(screen.getByText('14 ofert')).toBeDefined();
    expect(statusSelect().value).toBe('wszystkie');
  });

  it('„?status=wygasla" zostawia same wygasłe i mówi, ile z ilu', async () => {
    renderPage('/oferty?status=wygasla');

    expect(await screen.findByRole('table')).toBeDefined();
    expect(rowTitles()).toEqual(['Magazyn WMS']);
    expect(screen.getByText('1 z 14 ofert')).toBeDefined();
    expect(statusSelect().value).toBe('wygasla');
    // Kafle liczą CAŁY portfel, nie wynik filtra (makieta `233:200`).
    expect(
      requireElement(
        screen.getByText(OFFERS_TEXTS.statTotal).previousElementSibling,
        'liczba kafla „Łącznie”',
      ).textContent,
    ).toBe('14');
  });

  it('filtr obejmujący KOMPLET ofert dalej mówi „z", a nie samą liczbę', async () => {
    // Sześć z sześciu ofert ma status „zaakceptowana". Obie liczby licznika są
    // wtedy równe, a wariant rozpoznawany po `shown === total` gubił
    // informację, że handlowiec patrzy na wynik filtra, nie na cały portfel.
    respondWith({
      data: FOURTEEN_OFFERS.filter((row) => row.status === 'zaakceptowana'),
      error: null,
    });

    renderPage('/oferty?status=zaakceptowana');

    expect(await screen.findByRole('table')).toBeDefined();
    expect(rowTitles()).toHaveLength(6);
    expect(screen.getByText('6 z 6 ofert')).toBeDefined();
  });

  it('nieznana wartość jest ignorowana i znika z adresu', async () => {
    renderPage('/oferty?status=xyz');

    expect(await screen.findByRole('table')).toBeDefined();
    await waitFor(() => {
      expect(currentSearch()).toBe('');
    });
    expect(rowTitles()).toHaveLength(14);
    expect(statusSelect().value).toBe('wszystkie');
  });

  it('wybór w selekcie ląduje w adresie', async () => {
    renderPage();

    expect(await screen.findByRole('table')).toBeDefined();

    fireEvent.change(statusSelect(), { target: { value: 'otwarta' } });

    await waitFor(() => {
      expect(currentSearch()).toBe('?status=otwarta');
    });
    expect(rowTitles()).toEqual(['Dach serwis', 'Elektryka audyt', 'Fabryka linia']);
  });

  it('filtr bez trafień zostawia kafle i kontrolki, a komunikat wstawia w tabelę', async () => {
    respondWith({
      data: FOURTEEN_OFFERS.filter((row) => row.slug !== 'x1'),
      error: null,
    });

    renderPage('/oferty?status=wygasla');

    expect(await screen.findByRole('table')).toBeDefined();
    expect(rowTitles()).toHaveLength(0);
    expect(
      within(screen.getByRole('table')).getByText('Żadna oferta nie ma statusu „wygasłe”'),
    ).toBeDefined();
    expect(screen.getAllByText(OFFERS_TEXTS.filterEmptyBody).length).toBeGreaterThan(0);
    expect(screen.getByText('0 z 13 ofert')).toBeDefined();
    expect(screen.getByText(OFFERS_TEXTS.statTotal)).toBeDefined();
    expect(statusSelect().value).toBe('wygasla');
  });
});

describe('OffersPage — sortowanie w adresie', () => {
  beforeEach(() => {
    respondWith({ data: FOURTEEN_OFFERS, error: null });
    respondWithSummaries(FOURTEEN_SUMMARIES);
  });

  it('domyślnie od najnowszej, ze strzałką przy „Opublikowana"', async () => {
    renderPage();

    expect(await screen.findByRole('table')).toBeDefined();
    expect(rowTitles()[0]).toBe('Dach serwis');
    expect(
      screen.getByRole('columnheader', { name: /^Opublikowana/ }).getAttribute('aria-sort'),
    ).toBe('descending');
  });

  it('„?sort=najwiecej-wizyt" liczy malejąco, a remis rozstrzyga data publikacji', async () => {
    renderPage('/oferty?sort=najwiecej-wizyt');

    expect(await screen.findByRole('table')).toBeDefined();

    // Liczniki dojeżdżają DRUGIM żądaniem — porządek po wizytach ustala się
    // dopiero po nim; do tego czasu lista stoi w porządku po dacie.
    await waitFor(() => {
      expect(rowTitles().slice(0, 3)).toEqual(['Dach serwis', 'Ąkcent wdrożenie', 'Elektryka audyt']);
    });

    // Obie po 12 wizyt: nowsza („Dach serwis", 05.09) przed starszą (30.08).
    const titles = rowTitles();
    expect(titles.slice(0, 3)).toEqual(['Dach serwis', 'Ąkcent wdrożenie', 'Elektryka audyt']);

    const visits = screen.getByRole('columnheader', { name: /^Wizyty/ });
    expect(visits.getAttribute('aria-sort')).toBe('descending');
    expect(visits.textContent).toContain('↓');
  });

  it('„?sort=nazwa" układa alfabetem polskim: Ą po A, przed B', async () => {
    renderPage('/oferty?sort=nazwa');

    expect(await screen.findByRole('table')).toBeDefined();
    expect(rowTitles().slice(0, 3)).toEqual(['Alfa audyt', 'Ąkcent wdrożenie', 'Beta migracja']);
    expect(screen.getByRole('columnheader', { name: /^Oferta/ }).getAttribute('aria-sort')).toBe(
      'ascending',
    );
  });

  it('nieznane sortowanie znika z adresu, a filtr obok niego zostaje', async () => {
    renderPage('/oferty?status=otwarta&sort=byle-jak');

    expect(await screen.findByRole('table')).toBeDefined();
    await waitFor(() => {
      expect(currentSearch()).toBe('?status=otwarta');
    });
    expect(rowTitles()).toEqual(['Dach serwis', 'Elektryka audyt', 'Fabryka linia']);
  });
});

describe('OffersPage — błąd pobrania', () => {
  it('pokazuje komunikat błędu zamiast pustej listy i onboardingu', async () => {
    respondWith({ data: null, error: { message: 'permission denied' } });

    renderPage();

    expect((await screen.findByRole('alert')).textContent).toBe(OFFERS_TEXTS.loadError);
    expect(screen.queryByText(OFFERS_TEXTS.emptyList)).toBeNull();
    expect(screen.queryByRole('table')).toBeNull();
  });
});

describe('OffersPage — ładowanie', () => {
  it('do czasu odpowiedzi pokazuje stan ładowania', async () => {
    respondWith(new Promise(() => undefined));

    renderPage();

    await waitFor(() => {
      expect(screen.getByRole('status').textContent).toBe(OFFERS_TEXTS.loading);
    });
    expect(screen.queryByText(OFFERS_TEXTS.emptyList)).toBeNull();
  });
});

