import * as Sentry from '@sentry/react';
import { AuthError } from '@supabase/supabase-js';
import { act, cleanup, renderHook, waitFor } from '@testing-library/react';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

import { requireElement } from '../../test/require-element.js';
import { consentReturnState } from '../../routes.js';
import type { AccountProfile, ProfileReadResult } from '../account/use-profile.js';
import { useConsent } from './use-consent.js';

/** Kształt wydawany przez Supabase: 32 znaki base32, bez myślników. */
const AUTHORIZATION_ID = 'drs4p6cdwu7jttylrcajgnhwnmg3iyha';
const OTHER_AUTHORIZATION_ID = 'epvfd7nqr7hegeve2owpfdfke6ej3pno';
const REDIRECT_URL = 'https://claude.ai/api/mcp/auth_callback?code=abc&state=xyz';

const getUser = vi.fn();
const getAuthorizationDetails = vi.fn();
const approveAuthorization = vi.fn();
const denyAuthorization = vi.fn();
const signOut = vi.fn();
const onAuthStateChange = vi.fn();

type AuthStateListener = (event: string, session: unknown) => void;

let authStateListener: AuthStateListener | null = null;

vi.mock('../../lib/supabase.js', () => ({
  supabase: {
    auth: {
      getUser: (): unknown => getUser(),
      signOut: (options: unknown): unknown => signOut(options),
      onAuthStateChange: (listener: AuthStateListener): unknown => onAuthStateChange(listener),
      oauth: {
        getAuthorizationDetails: (id: string): unknown => getAuthorizationDetails(id),
        approveAuthorization: (id: string, options: unknown): unknown =>
          approveAuthorization(id, options),
        denyAuthorization: (id: string, options: unknown): unknown => denyAuthorization(id, options),
      },
    },
  },
}));

vi.mock('@sentry/react', () => ({
  captureException: vi.fn(),
}));

const fetchProfile = vi.fn<(userId: string, signal: AbortSignal) => Promise<ProfileReadResult>>();

// Atrapa tylko ODCZYTU: reguła `needsTermsScreen` zostaje prawdziwa, bo to
// ona jest bramką, którą ten plik ma udowodnić.
vi.mock('../account/use-profile.js', async (importOriginal) => ({
  ...(await importOriginal<typeof import('../account/use-profile.js')>()),
  fetchProfile: (userId: string, signal: AbortSignal): Promise<ProfileReadResult> =>
    fetchProfile(userId, signal),
}));

/** Profil wpuszczany do panelu; nadpisania robią z niego konto bez dostępu. */
function accountProfile(overrides: Partial<AccountProfile> = {}): ProfileReadResult {
  return {
    status: 'gotowe',
    profile: {
      id: 'user-1',
      accessState: 'aktywne',
      role: 'user',
      source: 'akademia',
      termsAcceptedAt: new Date('2026-09-14T09:00:00+00:00'),
      deletionRequestedAt: null,
      hasWebhook: false,
      isFirstStepsDismissed: false,
      tourSeen: { oferty: true, oferta: true, szablony: true },
      ...overrides,
    },
  };
}

const navigateTo = vi.fn();

vi.mock('../../lib/browser-navigation.js', () => ({
  navigateTo: (url: string): void => {
    navigateTo(url);
  },
}));

function authorizationDetails(clientName: string, redirectUri?: string): Record<string, unknown> {
  return {
    authorization_id: AUTHORIZATION_ID,
    redirect_uri: redirectUri ?? 'https://claude.ai/api/mcp/auth_callback',
    client: {
      id: '9a0f2b7c-1d3e-4f50-8a61-2b3c4d5e6f70',
      name: clientName,
      uri: 'https://claude.ai',
      logo_uri: 'https://claude.ai/logo.png',
    },
    user: { id: '11111111-1111-4111-8111-111111111111', email: 'kacper@twojafirma.pl' },
    scope: '',
  };
}

beforeEach(() => {
  getUser.mockResolvedValue({ data: { user: { id: 'user-1' } }, error: null });
  fetchProfile.mockResolvedValue(accountProfile());
  onAuthStateChange.mockImplementation((listener: AuthStateListener) => {
    authStateListener = listener;
    return { data: { subscription: { unsubscribe: vi.fn() } } };
  });
  signOut.mockResolvedValue({ error: null });
});

afterEach(() => {
  cleanup();
  vi.clearAllMocks();
  vi.restoreAllMocks();
  authStateListener = null;
});

describe('useConsent', () => {
  it('bez identyfikatora daje stan błędu i NIE pyta Auth API', async () => {
    const { result } = renderHook(() => useConsent(null));

    await waitFor(() => {
      expect(result.current.state).toEqual({ status: 'error', reason: 'invalid_id' });
    });
    expect(getAuthorizationDetails).not.toHaveBeenCalled();
    expect(getUser).not.toHaveBeenCalled();
  });

  it('bez sesji daje stan anonimowy i nie pyta o szczegóły prośby', async () => {
    getUser.mockResolvedValue({
      data: { user: null },
      error: new AuthError('Auth session missing!', 400, 'session_not_found'),
    });

    const { result } = renderHook(() => useConsent(AUTHORIZATION_ID));

    await waitFor(() => {
      expect(result.current.state.status).toBe('anonymous');
    });
    expect(getAuthorizationDetails).not.toHaveBeenCalled();
  });

  it('z sesją oddaje szczegóły prośby z nazwą po sanityzacji i hostem powrotu', async () => {
    getAuthorizationDetails.mockResolvedValue({
      data: authorizationDetails('  Claude   Desktop '),
      error: null,
    });

    const { result } = renderHook(() => useConsent(AUTHORIZATION_ID));

    await waitFor(() => {
      expect(result.current.state.status).toBe('details');
    });

    const state = result.current.state;

    if (state.status !== 'details') {
      throw new Error(`Oczekiwano stanu „details", jest „${state.status}"`);
    }

    expect(state.clientName).toBe('Claude Desktop');
    expect(state.user.email).toBe('kacper@twojafirma.pl');
    expect(state.redirect).toEqual({ host: 'claude.ai', trust: 'trusted' });
    expect(state.pending).toBeNull();
    expect(getAuthorizationDetails).toHaveBeenCalledWith(AUTHORIZATION_ID);
  });

  it('klient z obcym adresem powrotu nie dostaje ekranu decyzji — stan „unsupported" z hostem', async () => {
    // Rejestracja klientów jest otwarta, nazwę wybiera rejestrujący, a token
    // po zgodzie otwiera Data API w pełnym zakresie RLS handlowca. Jedyna
    // część prośby, której rejestrujący nie podmieni, to adres odbioru kodu —
    // obcy host nie dostaje więc przycisku „Zezwól", a bez zgody nie ma tokenu.
    getAuthorizationDetails.mockResolvedValue({
      data: authorizationDetails('Aplikacja testowa', 'https://atakujacy.example/oauth/callback'),
      error: null,
    });

    const { result } = renderHook(() => useConsent(AUTHORIZATION_ID));

    await waitFor(() => {
      expect(result.current.state).toEqual({ status: 'unsupported', host: 'atakujacy.example' });
    });

    await act(async () => {
      result.current.approve();
      await Promise.resolve();
    });

    expect(approveAuthorization).not.toHaveBeenCalled();
    expect(navigateTo).not.toHaveBeenCalled();
  });

  it.each([
    ['konto `oczekujace` bez regulaminu', { accessState: 'oczekujace', termsAcceptedAt: null }],
    ['konto `oczekujace` z regulaminem', { accessState: 'oczekujace' }],
    ['konto `aktywne` bez regulaminu', { termsAcceptedAt: null }],
  ] as const)('%s nie dostaje decyzji: stan „access_pending" bez pytania o prośbę', async (_case, overrides) => {
    // Strona zgody stoi POZA bramką panelu, więc bez tej gałęzi „Zezwól"
    // wydawałoby connectorowi token kontu, którego bramka nie wpuściła.
    fetchProfile.mockResolvedValue(accountProfile(overrides));
    getAuthorizationDetails.mockResolvedValue({
      data: authorizationDetails('Claude'),
      error: null,
    });

    const { result } = renderHook(() => useConsent(AUTHORIZATION_ID));

    await waitFor(() => {
      expect(result.current.state).toEqual({
        status: 'access_pending',
        returnState: consentReturnState(AUTHORIZATION_ID),
      });
    });
    expect(fetchProfile).toHaveBeenCalledWith('user-1', expect.any(AbortSignal));
    expect(getAuthorizationDetails).not.toHaveBeenCalled();

    await act(async () => {
      result.current.approve();
      await Promise.resolve();
    });

    expect(approveAuthorization).not.toHaveBeenCalled();
    expect(navigateTo).not.toHaveBeenCalled();
  });

  it.each([
    ['awaria odczytu profilu', { status: 'awaria' } as const],
    ['brak wiersza profilu (konto skasowane)', { status: 'brak' } as const],
  ])('%s kończy błędem bez ekranu decyzji (fail-closed)', async (_case, read) => {
    fetchProfile.mockResolvedValue(read);
    getAuthorizationDetails.mockResolvedValue({
      data: authorizationDetails('Claude'),
      error: null,
    });

    const { result } = renderHook(() => useConsent(AUTHORIZATION_ID));

    await waitFor(() => {
      expect(result.current.state).toEqual({ status: 'error', reason: 'unknown_or_expired' });
    });
    expect(getAuthorizationDetails).not.toHaveBeenCalled();
  });

  it('odpowiedź z samym redirect_url przekierowuje bez pytania o zgodę', async () => {
    getAuthorizationDetails.mockResolvedValue({
      data: { redirect_url: REDIRECT_URL },
      error: null,
    });

    const { result } = renderHook(() => useConsent(AUTHORIZATION_ID));

    await waitFor(() => {
      expect(result.current.state.status).toBe('redirecting');
    });
    expect(navigateTo).toHaveBeenCalledWith(REDIRECT_URL);
  });

  it('dwa kliknięcia „Zezwól" wysyłają JEDNO żądanie i kończą przekierowaniem', async () => {
    getAuthorizationDetails.mockResolvedValue({
      data: authorizationDetails('Claude'),
      error: null,
    });
    approveAuthorization.mockResolvedValue({ data: { redirect_url: REDIRECT_URL }, error: null });

    const { result } = renderHook(() => useConsent(AUTHORIZATION_ID));

    await waitFor(() => {
      expect(result.current.state.status).toBe('details');
    });

    await act(async () => {
      result.current.approve();
      result.current.approve();
      await Promise.resolve();
    });

    await waitFor(() => {
      expect(result.current.state.status).toBe('redirecting');
    });
    expect(approveAuthorization).toHaveBeenCalledTimes(1);
    expect(approveAuthorization).toHaveBeenCalledWith(AUTHORIZATION_ID, {
      skipBrowserRedirect: true,
    });
    expect(navigateTo).toHaveBeenCalledExactlyOnceWith(REDIRECT_URL);
  });

  it('„Odmów" woła denyAuthorization, pokazuje planszę odmowy i przekierowuje', async () => {
    const deniedUrl = 'https://claude.ai/api/mcp/auth_callback?error=access_denied';
    getAuthorizationDetails.mockResolvedValue({
      data: authorizationDetails('Claude'),
      error: null,
    });
    denyAuthorization.mockResolvedValue({ data: { redirect_url: deniedUrl }, error: null });

    const { result } = renderHook(() => useConsent(AUTHORIZATION_ID));

    await waitFor(() => {
      expect(result.current.state.status).toBe('details');
    });

    await act(async () => {
      result.current.deny();
      await Promise.resolve();
    });

    await waitFor(() => {
      expect(result.current.state.status).toBe('denied');
    });
    expect(denyAuthorization).toHaveBeenCalledExactlyOnceWith(AUTHORIZATION_ID, {
      skipBrowserRedirect: true,
    });
    expect(approveAuthorization).not.toHaveBeenCalled();
    expect(navigateTo).toHaveBeenCalledExactlyOnceWith(deniedUrl);
  });

  it('błąd decyzji daje stan błędu, raport bez authorization_id i BEZ przekierowania', async () => {
    getAuthorizationDetails.mockResolvedValue({
      data: authorizationDetails('Claude'),
      error: null,
    });
    approveAuthorization.mockResolvedValue({
      data: null,
      error: new AuthError('boom', 500, 'unexpected'),
    });

    const { result } = renderHook(() => useConsent(AUTHORIZATION_ID));

    await waitFor(() => {
      expect(result.current.state.status).toBe('details');
    });

    await act(async () => {
      result.current.approve();
      await Promise.resolve();
    });

    await waitFor(() => {
      expect(result.current.state).toEqual({ status: 'error', reason: 'unknown_or_expired' });
    });

    const captured = vi.mocked(Sentry.captureException).mock.calls;
    expect(captured).toHaveLength(1);

    const [reported] = requireElement(captured[0], 'wywołanie captureException');
    const message = reported instanceof Error ? reported.message : String(reported);

    expect(message).not.toContain(AUTHORIZATION_ID);
    expect(navigateTo).not.toHaveBeenCalled();
  });

  it('nie przekierowuje pod redirect_url o schemacie javascript, mimo udanej decyzji', async () => {
    // Adres pochodzi od klienta zarejestrowanego przez DCR, czyli spoza granicy
    // zaufania. GoTrue odrzuca dziś takie schematy przy rejestracji (pomiar
    // 2026-09-07), ale bramka stoi po naszej stronie: koszt pomyłki to
    // `javascript:` wykonany w originie panelu z żywą sesją handlowca.
    getAuthorizationDetails.mockResolvedValue({
      data: authorizationDetails('Claude'),
      error: null,
    });
    approveAuthorization.mockResolvedValue({
      data: { redirect_url: 'javascript:alert(document.cookie)' },
      error: null,
    });

    const { result } = renderHook(() => useConsent(AUTHORIZATION_ID));

    await waitFor(() => {
      expect(result.current.state.status).toBe('details');
    });

    await act(async () => {
      result.current.approve();
      await Promise.resolve();
    });

    await waitFor(() => {
      expect(result.current.state).toEqual({ status: 'error', reason: 'unknown_or_expired' });
    });
    expect(navigateTo).not.toHaveBeenCalled();
  });

  it('po nieudanej decyzji zatrzask jest ZWOLNIONY — ponowne „Zezwól" wysyła drugie żądanie', async () => {
    // Bez zwolnienia `isDecidingRef` oba przyciski byłyby martwe do końca
    // życia strony: jedna nieudana próba i prośby nie da się już zatwierdzić.
    getAuthorizationDetails.mockResolvedValue({
      data: authorizationDetails('Claude'),
      error: null,
    });
    approveAuthorization.mockResolvedValue({
      data: null,
      error: new AuthError('boom', 500, 'unexpected'),
    });

    const { result } = renderHook(() => useConsent(AUTHORIZATION_ID));

    await waitFor(() => {
      expect(result.current.state.status).toBe('details');
    });

    await act(async () => {
      result.current.approve();
      await Promise.resolve();
    });

    await waitFor(() => {
      expect(result.current.state.status).toBe('error');
    });

    approveAuthorization.mockResolvedValue({ data: { redirect_url: REDIRECT_URL }, error: null });

    await act(async () => {
      result.current.approve();
      await Promise.resolve();
    });

    await waitFor(() => {
      expect(approveAuthorization).toHaveBeenCalledTimes(2);
    });
    expect(navigateTo).toHaveBeenCalledExactlyOnceWith(REDIRECT_URL);
  });

  it('utrata sesji w trakcie prośby daje stan session_lost', async () => {
    getAuthorizationDetails.mockResolvedValue({
      data: authorizationDetails('Claude'),
      error: null,
    });

    const { result } = renderHook(() => useConsent(AUTHORIZATION_ID));

    await waitFor(() => {
      expect(result.current.state.status).toBe('details');
    });

    act(() => {
      requireElement(authStateListener, 'słuchacz onAuthStateChange')('SIGNED_OUT', null);
    });

    expect(result.current.state).toEqual({ status: 'error', reason: 'session_lost' });
  });

  it('zdarzenie z sesją NIE rusza stanu prośby', async () => {
    // Bez tej asercji poprzedni test przechodzi także dla kodu, który wywala
    // stronę przy KAŻDYM zdarzeniu auth (np. odświeżeniu tokenu).
    getAuthorizationDetails.mockResolvedValue({
      data: authorizationDetails('Claude'),
      error: null,
    });

    const { result } = renderHook(() => useConsent(AUTHORIZATION_ID));

    await waitFor(() => {
      expect(result.current.state.status).toBe('details');
    });

    act(() => {
      requireElement(authStateListener, 'słuchacz onAuthStateChange')('TOKEN_REFRESHED', {
        access_token: 'nowy',
      });
    });

    expect(result.current.state.status).toBe('details');
  });

  it('błąd odczytu szczegółów daje stan błędu, a raport do Sentry nie niesie authorization_id', async () => {
    getAuthorizationDetails.mockResolvedValue({
      data: null,
      error: new AuthError('Authorization request not found', 404, 'not_found'),
    });

    const { result } = renderHook(() => useConsent(AUTHORIZATION_ID));

    await waitFor(() => {
      expect(result.current.state).toEqual({ status: 'error', reason: 'unknown_or_expired' });
    });

    const captured = vi.mocked(Sentry.captureException).mock.calls;
    expect(captured).toHaveLength(1);

    const [reported] = requireElement(captured[0], 'wywołanie captureException');
    const message = reported instanceof Error ? reported.message : String(reported);

    expect(message).not.toContain(AUTHORIZATION_ID);
    expect(message).toContain('Strona zgody OAuth');
  });

  it('wyjątek rzucony przez Auth API kończy stanem błędu, nie zawieszonym ładowaniem', async () => {
    getAuthorizationDetails.mockRejectedValue(new Error('fetch padł'));

    const { result } = renderHook(() => useConsent(AUTHORIZATION_ID));

    await waitFor(() => {
      expect(result.current.state).toEqual({ status: 'error', reason: 'unknown_or_expired' });
    });
    expect(vi.mocked(Sentry.captureException)).toHaveBeenCalledTimes(1);
  });

  it('„Wyloguj się" wylogowuje LOKALNIE i wraca do karty logowania', async () => {
    getAuthorizationDetails.mockResolvedValue({
      data: authorizationDetails('Claude'),
      error: null,
    });

    const { result } = renderHook(() => useConsent(AUTHORIZATION_ID));

    await waitFor(() => {
      expect(result.current.state.status).toBe('details');
    });

    await act(async () => {
      result.current.signOutLocal();
      await Promise.resolve();
    });

    await waitFor(() => {
      expect(result.current.state.status).toBe('anonymous');
    });
    // Zakres globalny ubiłby sesje mintowane dla MCP — connector padłby przy
    // okazji zmiany konta w panelu.
    expect(signOut).toHaveBeenCalledExactlyOnceWith({ scope: 'local' });
  });

  it('odpowiedź na nieaktualną prośbę nie nadpisuje stanu nowszej', async () => {
    // Adres zmienia się w trakcie lotu pierwszego żądania: wolniejsza
    // odpowiedź o STAREJ prośbie nie może wrócić na ekran.
    const stale = authorizationDetails('Stara prośba');
    const fresh = { ...authorizationDetails('Nowa prośba'), authorization_id: OTHER_AUTHORIZATION_ID };

    getAuthorizationDetails.mockImplementation((id: string) =>
      id === AUTHORIZATION_ID
        ? new Promise((resolve) => {
            setTimeout(() => {
              resolve({ data: stale, error: null });
            }, 20);
          })
        : Promise.resolve({ data: fresh, error: null }),
    );

    const { result, rerender } = renderHook(({ id }: { id: string }) => useConsent(id), {
      initialProps: { id: AUTHORIZATION_ID },
    });

    rerender({ id: OTHER_AUTHORIZATION_ID });

    await waitFor(() => {
      expect(result.current.state.status).toBe('details');
    });

    await act(async () => {
      await new Promise((resolve) => {
        setTimeout(resolve, 40);
      });
    });

    const state = result.current.state;

    if (state.status !== 'details') {
      throw new Error(`Oczekiwano stanu „details", jest „${state.status}"`);
    }

    expect(state.clientName).toBe('Nowa prośba');
  });
});

