import { existsSync, readFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';

import { LEGAL_PATHS } from '@oferty/shared';
import * as Sentry from '@sentry/react';
import { cleanup, fireEvent, render, screen, waitFor } from '@testing-library/react';
import { MemoryRouter, Route, Routes } from 'react-router';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

import { LOGIN_PATH, OFFERS_PATH, TEMPLATES_PATH } from '../../routes.js';
import { requireElement } from '../../test/require-element.js';
import { AppLayout } from './app-layout.js';

const signOut = vi.fn();

vi.mock('@sentry/react', () => ({ captureException: vi.fn() }));

vi.mock('../../lib/supabase.js', () => ({
  supabase: {
    auth: {
      signOut: (options: unknown): unknown => signOut(options),
    },
  },
}));

function renderLayout(): void {
  render(
    <MemoryRouter initialEntries={[OFFERS_PATH]}>
      <Routes>
        <Route
          path={OFFERS_PATH}
          element={
            <AppLayout>
              <p>lista ofert</p>
            </AppLayout>
          }
        />
        <Route path={LOGIN_PATH} element={<p>ekran logowania</p>} />
      </Routes>
    </MemoryRouter>,
  );
}

/** Adres Akademii wchodzi ze zmiennej BUILDA — w teście atrapa, nigdy domena produktowa. */
const MARKETING_URL = 'https://akademia.example.invalid';

beforeEach(() => {
  vi.stubEnv('VITE_AA_MARKETING_URL', MARKETING_URL);
});

afterEach(() => {
  cleanup();
  vi.unstubAllEnvs();
  vi.clearAllMocks();
});

describe('AppLayout', () => {
  it('pokazuje cztery pozycje w kolejności Oferty · Szablony · Ustawienia · Pomoc', () => {
    signOut.mockResolvedValue({ error: null });

    renderLayout();

    // Kolejność, nie sama obecność: makieta `183:58` stawia „Szablony”
    // MIĘDZY ofertami a ustawieniami, a asercja po samej obecności
    // przepuściłaby pozycję dopisaną na końcu listy.
    // Zapytanie zawężone do `<nav>`: stopka sidebara niesie od fazy 7 własny
    // link (Akademia), więc `aside a` mieszałby nawigację z brandingiem.
    const nav = requireElement(
      document.querySelector('aside nav'),
      'nawigacja sidebara',
    );

    // „Pomoc" (faza 9b, R14) stoi na KOŃCU pozycji wspólnych — po
    // „Ustawieniach", przed pozycjami administratora, które dokłada rola.
    expect([...nav.querySelectorAll('a')].map((link) => link.textContent)).toEqual([
      'Oferty',
      'Szablony',
      'Ustawienia',
      'Pomoc',
    ]);
    expect(screen.getAllByRole('link', { name: 'Szablony' })[0]?.getAttribute('href')).toBe(
      TEMPLATES_PATH,
    );
  });

  it('ikona pozycji „Szablony” jest ukryta przed czytnikiem i dziedziczy kolor po tekście', () => {
    signOut.mockResolvedValue({ error: null });

    renderLayout();

    const link = requireElement(
      screen.getAllByRole('link', { name: 'Szablony' })[0],
      'pozycja nawigacji „Szablony”',
    );
    const icon = requireElement(link.querySelector('svg'), 'ikona pozycji „Szablony”');

    expect(icon.getAttribute('aria-hidden')).toBe('true');
    expect(icon.getAttribute('stroke')).toBe('currentColor');
  });

  it('„Wyloguj się” kończy wyłącznie sesję tej przeglądarki i prowadzi na logowanie', async () => {
    signOut.mockResolvedValue({ error: null });

    renderLayout();
    fireEvent.click(
      requireElement(
        screen.getAllByRole('button', { name: 'Wyloguj się' })[0],
        'przycisk „Wyloguj się”',
      ),
    );

    await waitFor(() => {
      expect(screen.getByText('ekran logowania')).toBeDefined();
    });

    expect(signOut).toHaveBeenCalledWith({ scope: 'local' });
  });

  it('błąd wylogowania pokazuje komunikat i zostawia użytkownika w panelu', async () => {
    // Nawigacja na /logowanie przy żywej sesji tylko udawałaby wylogowanie —
    // guard wpuściłby z powrotem.
    signOut.mockResolvedValue({ error: { message: 'auth padło' } });

    renderLayout();
    fireEvent.click(
      requireElement(
        screen.getAllByRole('button', { name: 'Wyloguj się' })[0],
        'przycisk „Wyloguj się”',
      ),
    );

    expect((await screen.findByRole('alert')).textContent).toBe(
      'Nie udało się wylogować. Spróbuj ponownie.',
    );
    expect(screen.queryByText('ekran logowania')).toBeNull();
  });

  it('odrzucona obietnica wylogowania pokazuje ten sam komunikat', async () => {
    signOut.mockRejectedValue(new Error('sieć padła'));

    renderLayout();
    fireEvent.click(
      requireElement(
        screen.getAllByRole('button', { name: 'Wyloguj się' })[0],
        'przycisk „Wyloguj się”',
      ),
    );

    expect((await screen.findByRole('alert')).textContent).toBe(
      'Nie udało się wylogować. Spróbuj ponownie.',
    );
    expect(screen.queryByText('ekran logowania')).toBeNull();
  });

  it('menu mobile rozwija nawigację i „Wyloguj się”', () => {
    renderLayout();

    expect(screen.getAllByRole('link', { name: 'Oferty' })).toHaveLength(1);

    fireEvent.click(screen.getByRole('button', { name: 'Menu' }));

    expect(screen.getAllByRole('link', { name: 'Oferty' })).toHaveLength(2);
    expect(screen.getAllByRole('button', { name: 'Wyloguj się' })).toHaveLength(2);
  });

  it.each([
    ['Regulamin', LEGAL_PATHS.terms],
    ['Prywatność', LEGAL_PATHS.privacy],
  ])('link „%s” stoi w stopce sidebara i w menu mobile, w tym samym oknie', (label, path) => {
    // Bliźniaki `hidden md:flex` (aside) / `md:hidden` (menu) to DWA
    // wystąpienia w DOM — asercja „jest link" przepuściłaby brak jednego
    // z nich. Menu istnieje dopiero po otwarciu, więc bez kliknięcia test
    // policzyłby jeden link i przeszedł na złym kształcie.
    renderLayout();
    fireEvent.click(screen.getByRole('button', { name: 'Menu' }));

    const links = screen.getAllByRole('link', { name: label });

    expect(links).toHaveLength(2);

    // GDZIE stoją, nie tylko ile ich jest: dwa linki w samym menu mobilnym
    // też dałyby długość 2, a stopka sidebara zostałaby bez dokumentów.
    const sidebar = requireElement(document.querySelector('aside'), 'sidebar nawigacji');

    expect(links.filter((link) => sidebar.contains(link))).toHaveLength(1);

    for (const link of links) {
      // Trasa serwera na `APP_ORIGIN`, poza SPA: zwykłe `<a>` z pełnym
      // przeładowaniem, ten sam origin — dokument wraca „Wstecz".
      expect(link.getAttribute('href')).toBe(path);
      expect(link.getAttribute('target')).toBeNull();
    }
  });
});

describe('AppLayout — logo Traferto w nagłówku', () => {
  it('stoi w sidebarze desktop I w pasku mobile jako obraz, bez tekstowego wordmarka', () => {
    // Bliźniaki `hidden md:flex` (aside) / `md:hidden` (header) to DWA
    // wystąpienia w DOM — `getByAltText` rzuciłoby przy dwóch, a
    // `queryAllBy…[0]` przepuściłoby brak drugiego. Liczymy oba i sprawdzamy,
    // GDZIE stoją: dwa logo w samym sidebarze też dałyby długość 2.
    signOut.mockResolvedValue({ error: null });

    renderLayout();

    const logos = screen.getAllByAltText('Traferto');

    expect(logos).toHaveLength(2);

    const sidebar = requireElement(document.querySelector('aside'), 'sidebar nawigacji');
    const header = requireElement(document.querySelector('header'), 'pasek mobile');

    expect(logos.filter((logo) => sidebar.contains(logo))).toHaveLength(1);
    expect(logos.filter((logo) => header.contains(logo))).toHaveLength(1);

    for (const logo of logos) {
      expect(logo.tagName.toLowerCase()).toBe('img');
      expect(logo.getAttribute('src')).toBe('/brand/traferto-logo.svg');
    }

    // Logo w sidebarze stoi NAD nawigacją (miejsce dawnego wordmarka), nie w stopce.
    const sidebarLogo = requireElement(
      sidebar.querySelector('img[alt="Traferto"]'),
      'logo w sidebarze',
    );
    const nav = requireElement(sidebar.querySelector('nav'), 'nawigacja sidebara');

    expect(
      sidebarLogo.compareDocumentPosition(nav) & Node.DOCUMENT_POSITION_FOLLOWING,
    ).toBeTruthy();
    expect(requireElement(sidebar.lastElementChild, 'stopka sidebara').contains(sidebarLogo)).toBe(
      false,
    );

    // Asercja negatywna OBOK pozytywnej: sam brak starej nazwy przeszedłby
    // też na pustym nagłówku. Fragment z kotwicą po obu stronach — jedno
    // słowo „Oferty" jest nazwą pozycji nawigacji. Igła sklejona z kawałków,
    // żeby TEN plik nie był znaleziskiem grepa weryfikacji.
    const oldName = ['Oferta', 'Online'].join(' ');

    expect(document.body.textContent).not.toContain(oldName);
    expect(document.body.textContent).not.toMatch(/Oferta\s*Online/);
  });
});

describe('AppLayout — stopka sidebara ze znakiem Akademii', () => {
  it('układa znak-link, wiersz dokumentów i wiersz wersji w tej kolejności, bez osobnego linku tekstowego', () => {
    signOut.mockResolvedValue({ error: null });

    renderLayout();

    const sidebar = requireElement(document.querySelector('aside'), 'sidebar nawigacji');
    const footer = requireElement(sidebar.lastElementChild, 'stopka sidebara');

    // Kolejność, nie sama obecność: asercja po obecności przepuściłaby znak
    // dopisany pod wierszem wersji. Decyzja operatora ze smoke'u 2026-09-05:
    // znak JEST linkiem, osobny link tekstowy z hostem znika — stąd `a`, nie
    // `img` + `a` z makiety `183:58`.
    expect(
      [...footer.children].map((element) => element.tagName.toLowerCase()),
    ).toEqual(['a', 'p', 'p']);

    const logo = requireElement(footer.querySelector('a > img'), 'znak Akademii w linku');

    expect(logo.getAttribute('alt')).toBe('Akademia Automatyzacji');
    expect(logo.getAttribute('width')).toBe('108');
    expect(logo.getAttribute('height')).toBe('36');
    expect([...footer.querySelectorAll('p')].map((row) => row.textContent)).toEqual([
      'Regulamin · Prywatność',
      'v1.0 · Wyloguj się',
    ]);
  });

  it('znak prowadzi pod adres ze zmiennej builda i otwiera go w nowej karcie', () => {
    signOut.mockResolvedValue({ error: null });

    renderLayout();

    // Dostępną nazwą linku jest `alt` znaku — bez tekstu obok obraz to
    // jedyne, co czytnik ma do przeczytania.
    const link = requireElement(
      screen.getByRole('link', { name: 'Akademia Automatyzacji' }),
      'link do Akademii',
    );

    expect(link.getAttribute('href')).toBe(`${MARKETING_URL}/`);
    expect(link.getAttribute('target')).toBe('_blank');
    expect(link.getAttribute('rel')).toBe('noreferrer');
    expect(link.textContent).toBe('');
  });

  it.each([
    '',
    '   ',
    'akademia.example.invalid',
    'javascript:alert(1)',
    'data:text/html,<b>x</b>',
    'mailto:kontakt@example.invalid',
  ])(
    'przy wartości %o renderuje panel bez linku i bez wyjątku',
    (value) => {
      // Pusta wartość to zielony build i martwy link; wartość bez schematu to
      // `TypeError` z `new URL` W TRAKCIE RENDERU, a dashboard nie ma error
      // boundary — panel zamieniłby się w białą stronę. Schemat inny niż
      // `http:`/`https:` przechodzi przez `new URL`, ale nie ma prawa trafić
      // do klikalnego `href`. Wszystkie przypadki gaszą sam link: znak
      // zostaje jako goły obraz, wiersz wersji zostaje.
      signOut.mockResolvedValue({ error: null });
      vi.stubEnv('VITE_AA_MARKETING_URL', value);

      expect(() => {
        renderLayout();
      }).not.toThrow();

      const sidebar = requireElement(document.querySelector('aside'), 'sidebar nawigacji');
      const footer = requireElement(sidebar.lastElementChild, 'stopka sidebara');

      // Gaśnie znak-link (bezpośrednie dziecko stopki); linki „Regulamin"
      // i „Prywatność" mają własny wiersz nad wersją i od ENV nie zależą.
      expect(footer.querySelector(':scope > a')).toBeNull();
      expect(screen.getByRole('link', { name: 'Regulamin' })).toBeDefined();
      expect(
        [...footer.children].map((element) => element.tagName.toLowerCase()),
      ).toEqual(['img', 'p', 'p']);
      expect([...footer.querySelectorAll('p')].map((row) => row.textContent)).toEqual([
      'Regulamin · Prywatność',
      'v1.0 · Wyloguj się',
    ]);
    },
  );

  it('literówkę w adresie Akademii zgłasza do Sentry RAZ, pustą wartość — wcale', () => {
    // Regresja z review PR: pusty `catch` gasił link bez śladu, choć bliźniaczy
    // `VITE_OFFER_ORIGIN` raportował literówkę. Helper jest wołany w renderze
    // stopki, więc zatrzask ma trzymać jedno zgłoszenie na wartość — nie jedno
    // na każde przemontowanie panelu.
    signOut.mockResolvedValue({ error: null });
    vi.stubEnv('VITE_AA_MARKETING_URL', 'literowka.stopki.invalid-bez-schematu');

    renderLayout();
    cleanup();
    renderLayout();

    expect(Sentry.captureException).toHaveBeenCalledTimes(1);
    expect(vi.mocked(Sentry.captureException).mock.calls[0]?.[1]).toEqual({
      extra: { url: 'literowka.stopki.invalid-bez-schematu' },
    });

    vi.mocked(Sentry.captureException).mockClear();
    cleanup();
    vi.stubEnv('VITE_AA_MARKETING_URL', '');

    renderLayout();

    expect(Sentry.captureException).not.toHaveBeenCalled();
  });

  it('nie ma domeny Akademii zaszytej w kodzie źródłowym dashboardu', () => {
    // Adres wolno zmienić w Coolify bez przebudowy kodu (Z4). Skan po ŹRÓDLE,
    // nie po wyrenderowanym drzewie: literał w dowolnym komponencie
    // przeżyłby zmianę zmiennej i pokazywałby stary adres.
    // Igła sklejona z kawałków, żeby TEN plik nie był własnym znaleziskiem.
    const needle = ['akademia', 'automatyzacji'].join('');
    // Katalog roboczy vitest to `apps/dashboard` (`import.meta.url` w jsdom
    // nie jest adresem `file:`, więc `fileURLToPath` by tu rzucił).
    const sourceRoot = join(process.cwd(), 'src');

    expect(existsSync(sourceRoot)).toBe(true);

    // Porównanie bez wielkości liter: ta sama domena zapisana wielkimi
    // literami to wciąż ta domena (DNS ich nie rozróżnia), a gołe `includes`
    // by ją przepuściło.
    const offenders = collectSourceFiles(sourceRoot).filter((file) =>
      readFileSync(file, 'utf8').toLowerCase().includes(needle),
    );

    expect(offenders).toEqual([]);
  });
});

/** Rekurencyjny spis plików źródłowych dashboardu — bez `node_modules` i buildów. */
function collectSourceFiles(directory: string): readonly string[] {
  return readdirSync(directory, { withFileTypes: true }).flatMap((entry) => {
    const path = join(directory, entry.name);

    if (entry.isDirectory()) {
      return entry.name === 'node_modules' || entry.name === 'dist' ? [] : collectSourceFiles(path);
    }

    return /\.(ts|tsx|css|html)$/.test(entry.name) ? [path] : [];
  });
}

