import { MIN_USABLE_FRAME_PX } from '@oferty/shared';
import { act, cleanup, renderHook, waitFor } from '@testing-library/react';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

import type { AccountProfile } from '../account/use-profile.js';
import { useFirstSteps, type FirstStepId, type FirstStepsState } from './use-first-steps.js';

interface TableStub {
  rows: unknown[];
  error: unknown;
}

type TableName = 'mcp_tokens' | 'offer_templates' | 'offers' | 'visits';

/**
 * Atrapa BAZY, nie hooka: checklista liczy stan z danych, więc testowana jest
 * właśnie droga od odpowiedzi PostgREST-a do kroków karty. Atrapa oddaje
 * DOKŁADNIE te kolumny, o które pyta produkcja.
 */
const tables = vi.hoisted((): Record<TableName, TableStub> => ({
  mcp_tokens: { rows: [], error: null },
  offer_templates: { rows: [], error: null },
  offers: { rows: [], error: null },
  visits: { rows: [], error: null },
}));

/** Progi geometrii przekazane przez produkcję do sondy wizyt — `[kolumna, wartość]`. */
const visitFilters = vi.hoisted((): { calls: [string, unknown][] } => ({ calls: [] }));

const { listGrants, dismissFirstSteps, reloadProfile, track, captureException } = vi.hoisted(
  () => ({
    listGrants: vi.fn(),
    // Atrapa ODWZOROWUJE kontrakt zapisu (`Promise<boolean>`): od wyniku
    // zależy, czy hook poprosi bramkę o ponowny odczyt profilu.
    dismissFirstSteps: vi.fn<(userId: string) => Promise<boolean>>(),
    reloadProfile: vi.fn<() => void>(),
    track: vi.fn(),
    captureException: vi.fn(),
  }),
);

/**
 * Rzut SYNCHRONICZNY klienta (zepsuty `fetch`, wyłączony storage) — jedyna
 * droga do bloku `catch` w efekcie hooka. `null` = klient zachowuje się
 * normalnie; test ustawia tu tabelę, na której produkcja ma się wywrócić.
 */
const throwingTable = vi.hoisted((): { name: string | null } => ({ name: null }));

vi.mock('@sentry/react', () => ({ captureException }));

vi.mock('../../lib/supabase.js', () => ({
  supabase: {
    from: (table: TableName): unknown => ({
      select: (): unknown => {
        if (throwingTable.name === table) {
          throw new TypeError('fetch nie jest dostępny');
        }

        const builder: Record<string, unknown> = {
          // `gte` zapamiętuje ARGUMENTY, a nie tylko przepuszcza łańcuch:
          // sonda wizyt bez progu geometrii liczyłaby wizyty nieliczone.
          gte: (column: string, value: unknown): unknown => {
            visitFilters.calls.push([column, value]);

            return builder;
          },
          limit: (): unknown => ({
            abortSignal: (): Promise<unknown> =>
              Promise.resolve({
                data: tables[table].error === null ? tables[table].rows : null,
                error: tables[table].error,
              }),
          }),
        };

        return builder;
      },
    }),
    auth: { oauth: { listGrants: (): unknown => listGrants() } },
  },
}));

/** Zapis własnego wiersza ma własne testy w `features/account`. */
vi.mock('../account/use-profile.js', () => ({
  dismissFirstSteps: (userId: string): Promise<boolean> => dismissFirstSteps(userId),
}));

vi.mock('../../lib/analytics.js', () => ({ track }));

const accountProfile = vi.fn<() => AccountProfile | null>();

vi.mock('../auth/access-gate.js', () => ({
  useAccountAccess: (): AccountProfile | null => accountProfile(),
  useAccountAccessReload: (): (() => void) => reloadProfile,
}));

const OWNER_ID = '11111111-1111-4111-8111-111111111111';

function profile(overrides: Partial<AccountProfile> = {}): void {
  accountProfile.mockReturnValue({
    id: OWNER_ID,
    accessState: 'aktywne',
    role: 'user',
    source: 'zewnetrzne',
    termsAcceptedAt: new Date('2026-09-14T09:00:00+00:00'),
    deletionRequestedAt: null,
    hasWebhook: false,
    isFirstStepsDismissed: false,
    tourSeen: { oferty: true, oferta: true, szablony: true },
    ...overrides,
  });
}

/**
 * Sam render — CZEKANIE należy do testu i jest za każdym razem inne: jeden
 * czeka na kroki, drugi na fakt, że odczyt w ogóle poleciał. Wspólne
 * „poczekaj na cokolwiek" byłoby asercją prawdziwą dla każdej implementacji.
 */
function renderSteps(): () => FirstStepsState {
  const { result } = renderHook(() => useFirstSteps());

  return () => result.current;
}

function doneIds(state: FirstStepsState): readonly FirstStepId[] {
  return state.status === 'gotowa'
    ? state.steps.filter((step) => step.isDone).map((step) => step.id)
    : [];
}

beforeEach(() => {
  tables.mcp_tokens = { rows: [], error: null };
  tables.offer_templates = { rows: [], error: null };
  tables.offers = { rows: [], error: null };
  tables.visits = { rows: [], error: null };
  visitFilters.calls = [];
  listGrants.mockResolvedValue({ data: [], error: null });
  dismissFirstSteps.mockResolvedValue(true);
  throwingTable.name = null;
  profile();
});

afterEach(() => {
  cleanup();
  vi.clearAllMocks();
});

describe('useFirstSteps — kroki liczone z danych', () => {
  it('brak wiersza `mcp_tokens` i JEDNA zgoda OAuth → krok „MCP" gotowy', async () => {
    listGrants.mockResolvedValue({
      data: [{ client: { id: 'klient-1', name: 'Claude' }, granted_at: '2026-09-12T10:00:00Z' }],
      error: null,
    });

    const current = renderSteps();

    await waitFor(() => {
      expect(current().status).toBe('gotowa');
    });

    const state = current();

    expect(doneIds(state)).toEqual(['mcp']);
    expect(state.status === 'gotowa' ? state.doneCount : null).toBe(1);
    expect(state.status === 'gotowa' ? state.requiredCount : null).toBe(4);
  });

  it('oferty są, ale ani jednej wizyty LICZONEJ → krok „wizyta" NIEgotowy', async () => {
    tables.offers = { rows: [{ id: 'oferta-1' }, { id: 'oferta-2' }], error: null };
    tables.visits = { rows: [], error: null };

    const current = renderSteps();

    await waitFor(() => {
      expect(current().status).toBe('gotowa');
    });

    expect(doneIds(current())).toEqual(['oferta']);
  });

  it('jedna wizyta liczona → krok „wizyta" gotowy, a sonda pyta o próg geometrii', async () => {
    tables.offers = { rows: [{ id: 'oferta-1' }], error: null };
    tables.visits = { rows: [{ id: 'wizyta-1' }], error: null };

    const current = renderSteps();

    await waitFor(() => {
      expect(current().status).toBe('gotowa');
    });

    expect(doneIds(current())).toEqual(['oferta', 'wizyta']);
    // Ten sam próg co reszta panelu: bez niego wizyta z ukrytej karty
    // (geometria poniżej progu) odhaczałaby krok, którego nikt nie zrobił.
    expect(visitFilters.calls).toEqual([
      ['viewport_width', MIN_USABLE_FRAME_PX],
      ['doc_height', MIN_USABLE_FRAME_PX],
    ]);
  });

  it('webhook jest krokiem OPCJONALNYM — nie wchodzi do licznika', async () => {
    profile({ hasWebhook: true });

    const current = renderSteps();

    await waitFor(() => {
      expect(current().status).toBe('gotowa');
    });

    const state = current();

    expect(doneIds(state)).toEqual(['webhook']);
    // Webhook odhaczony, a licznik dalej „0 z 4": to krok poza obowiązkiem.
    expect(state.status === 'gotowa' ? state.doneCount : null).toBe(0);
  });
});

describe('useFirstSteps — kiedy karty NIE MA', () => {
  it('cztery kroki obowiązkowe zrobione → karta znika (4/4), a drugie wejście nie pyta bazy', async () => {
    /*
     * WŁASNY identyfikator konta: domknięcie 4/4 podnosi zatrzask MODUŁOWY,
     * więc gdyby ten przypadek użył `OWNER_ID`, każdy kolejny test w pliku
     * dostałby „ukryta" bez ani jednego zapytania — i przechodziłby z powodu
     * innego, niż opisuje.
     */
    const completedOwnerId = '22222222-2222-4222-8222-222222222222';

    profile({ id: completedOwnerId });
    tables.mcp_tokens = { rows: [{ owner_id: completedOwnerId }], error: null };
    tables.offer_templates = { rows: [{ id: 'szablon-1' }], error: null };
    tables.offers = { rows: [{ id: 'oferta-1' }], error: null };
    tables.visits = { rows: [{ id: 'wizyta-1' }], error: null };

    const current = renderSteps();

    // Odczekanie na PEŁNY przebieg: bez tego „ukryta" byłoby prawdziwe także
    // dla kodu, który nigdy nie doszedł do odpowiedzi (stan `ladowanie` jest
    // tu osobny właśnie po to, żeby dało się je rozróżnić).
    await waitFor(() => {
      expect(current().status).not.toBe('ladowanie');
    });

    expect(current().status).toBe('ukryta');

    // Drugie wejście na listę ofert: karta i tak nie powstanie, więc pięć sond
    // (w tym `listGrants()` do GoTrue) nie ma po co polecieć jeszcze raz.
    cleanup();
    listGrants.mockClear();

    const second = renderSteps();

    await act(async () => {
      await Promise.resolve();
    });

    expect(second().status).toBe('ukryta');
    expect(listGrants).not.toHaveBeenCalled();
  });

  it('`first_steps_dismissed_at` z profilu → karta znika i baza nie jest pytana', async () => {
    profile({ isFirstStepsDismissed: true });

    const current = renderSteps();

    // Efekty zdążyły się wykonać: gdyby hook pytał bazę, `listGrants` już by
    // poleciało — bez tego oczekiwania asercja „nie pytał" byłaby o wyścig.
    await act(async () => {
      await Promise.resolve();
    });

    expect(current().status).toBe('ukryta');
    expect(listGrants).not.toHaveBeenCalled();
  });

  it('konto w trybie ograniczonym nie dostaje checklisty (baner ma pierwszeństwo)', async () => {
    profile({ accessState: 'ograniczone' });

    const current = renderSteps();

    await act(async () => {
      await Promise.resolve();
    });

    expect(current().status).toBe('ukryta');
    expect(listGrants).not.toHaveBeenCalled();
  });

  /*
   * Krok „MCP" jest ALTERNATYWĄ dwóch sond. Brak wiersza `mcp_tokens` przy
   * NIEROZSTRZYGNIĘTYCH zgodach to „nie wiadomo", nie „nie ma" — a „nie wiadomo"
   * gasi CAŁĄ kartę na świeżym koncie, czyli dokładnie tam, gdzie jest
   * najpotrzebniejsza. Dwa przypadki, bo `listGrants` zawodzi na dwa sposoby.
   */
  it('brak tokenu + odmowa `listGrants` (pole `error`) → karta znika, a nie pokazuje „MCP" jako niezrobiony', async () => {
    tables.mcp_tokens = { rows: [], error: null };
    listGrants.mockResolvedValue({ data: null, error: { message: 'oauth server disabled' } });

    const current = renderSteps();

    await waitFor(() => {
      expect(current().status).not.toBe('ladowanie');
    });

    expect(current().status).toBe('ukryta');
  });

  it('brak tokenu + RZUT z `listGrants` → karta znika (gałąź `catch` sondy zgód)', async () => {
    tables.mcp_tokens = { rows: [], error: null };
    listGrants.mockRejectedValue(new TypeError('fetch nie jest dostępny'));

    const current = renderSteps();

    await waitFor(() => {
      expect(current().status).not.toBe('ladowanie');
    });

    expect(current().status).toBe('ukryta');
    // Rzut ZŁAPANY przez sondę nie jest awarią do zgłoszenia: wyłączony serwer
    // OAuth wygląda stąd tak samo jak chwilowy brak sieci.
    expect(captureException).not.toHaveBeenCalled();
  });

  it('awaria odczytu kroku → karta znika, zamiast pokazać go jako niezrobiony', async () => {
    tables.offer_templates = { rows: [], error: { code: '42501', message: 'permission denied' } };

    const current = renderSteps();

    await waitFor(() => {
      expect(current().status).toBe('ukryta');
    });
  });

  /*
   * Żadna z pięciu sond nie raportuje sama (każda oddaje `null`), więc bez
   * zgłoszenia z efektu hooka rzut synchroniczny klienta gasiłby kartę bez
   * jednego śladu. Asercja na `captureException`, nie na samym stanie:
   * „ukryta" jest prawdziwe także dla implementacji, która połyka wyjątek.
   */
  it('rzut synchroniczny klienta → karta znika I jeden raport do Sentry', async () => {
    throwingTable.name = 'offers';

    const current = renderSteps();

    await waitFor(() => {
      expect(captureException).toHaveBeenCalledTimes(1);
    });

    expect(current().status).toBe('ukryta');

    // Drugie wejście na listę ofert w tej samej sesji nie dokłada zdarzenia —
    // zatrzask jest modułowy, a kartę montuje każde wejście na ekran.
    cleanup();

    const second = renderSteps();

    // Rzut jest synchroniczny wewnątrz efektu, więc obietnica odrzuca się w tej
    // samej turze mikrozadań — po jej wypchnięciu ewentualny drugi raport już
    // by tu był.
    await act(async () => {
      await Promise.resolve();
    });

    expect(second().status).toBe('ukryta');
    expect(captureException).toHaveBeenCalledTimes(1);
  });
});

describe('useFirstSteps — zamknięcie ręczne', () => {
  it('`dismiss` chowa kartę, zapisuje własny wiersz i wysyła zdarzenie', async () => {
    const current = renderSteps();

    await waitFor(() => {
      expect(current().status).toBe('gotowa');
    });

    const state = current();

    expect(state.status).toBe('gotowa');

    if (state.status !== 'gotowa') {
      return;
    }

    act(() => {
      state.dismiss();
    });

    expect(current().status).toBe('ukryta');
    expect(dismissFirstSteps).toHaveBeenCalledWith(OWNER_ID);
    expect(track).toHaveBeenCalledWith('checklista_zamknieta');

    // Po UDANYM zapisie bramka czyta wiersz od nowa — bez tego karta wracała
    // po nawigacji SPA, a drugie kliknięcie dokładało drugi zapis i drugie
    // zdarzenie.
    await waitFor(() => {
      expect(reloadProfile).toHaveBeenCalledTimes(1);
    });
  });

  it('NIEUDANY zapis zamknięcia nie prosi bramki o ponowny odczyt', async () => {
    dismissFirstSteps.mockResolvedValue(false);

    const current = renderSteps();

    await waitFor(() => {
      expect(current().status).toBe('gotowa');
    });

    const state = current();

    if (state.status !== 'gotowa') {
      throw new Error('checklista miała być gotowa');
    }

    act(() => {
      state.dismiss();
    });

    await waitFor(() => {
      expect(dismissFirstSteps).toHaveBeenCalledTimes(1);
    });

    expect(reloadProfile).not.toHaveBeenCalled();
  });
});

