import * as Sentry from '@sentry/react';
import type { ErrorEvent } from '@sentry/react';
import { act, cleanup, render, screen } from '@testing-library/react';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

import { App } from './App.js';
import { CONSENT_TEXTS } from './features/oauth/texts.js';
import { LOGIN_PATH, OAUTH_CONSENT_PATH, OFFERS_PATH, TEMPLATES_PATH } from './routes.js';
import globalCss from './styles/global.css?inline';
import { requireElement } from './test/require-element.js';

vi.mock('@sentry/react', () => ({
  init: vi.fn(),
  // Ekran `/szablony` raportuje awarię odczytu do monitoringu — bez tej atrapy
  // test trasy przewraca się na module, którego nie testuje.
  captureException: vi.fn(),
}));

const getSession = vi.fn();
const getUser = vi.fn();
const getAuthorizationDetails = vi.fn();
const onAuthStateChange = vi.fn();

vi.mock('./lib/supabase.js', () => ({
  supabase: {
    auth: {
      getSession: (): unknown => getSession(),
      getUser: (): unknown => getUser(),
      onAuthStateChange: (callback: unknown): unknown => onAuthStateChange(callback),
      // Strona zgody OAuth pyta o tożsamość i o szczegóły prośby — bez tych
      // atrap test trasy przewraca się na module, którego nie testuje.
      oauth: {
        getAuthorizationDetails: (id: string): unknown => getAuthorizationDetails(id),
      },
    },
    // Lista ofert odpytuje bazę zaraz po zamontowaniu, a bramka dostępu
    // (faza 9b) czyta własny wiersz `profiles` — bez obu atrap testy tras
    // przewracają się na modułach, których nie testują. Kształt zapytania
    // profilu jest ten sam, co w produkcji (`select` → `eq` → `maybeSingle`
    // → `abortSignal`): atrapa węższa od kontraktu dawałaby pokrycie pozorne.
    from: (table: string): unknown =>
      table === 'profiles'
        ? {
            select: (): unknown => ({
              eq: (): unknown => ({
                abortSignal: (): unknown => ({
                  maybeSingle: async (): Promise<unknown> => ({
                    data: PROFILE_ROW,
                    error: null,
                  }),
                }),
              }),
            }),
          }
        : {
            select: (): unknown => ({
              order: (): unknown => ({
                abortSignal: async (): Promise<unknown> => ({ data: [], error: null }),
              }),
            }),
          },
  },
}));

/** Konto aktywne po regulaminie — bramka dostępu wpuszcza je do panelu. */
const PROFILE_ROW = {
  access_state: 'aktywne',
  role: 'user',
  source: 'zewnetrzne',
  terms_accepted_at: '2026-09-14T09:00:00+00:00',
  deletion_requested_at: null,
};

/**
 * Atrapa `fetch` dla ekranów bez sesji. Od IU-6 samodzielnej rejestracji
 * (D10) karta logowania NIE pyta o tryb rejestracji — odpowiedź z trybem
 * dostaje wyłącznie `/chce-dostep`, gdyby któryś scenariusz tam trafił.
 */
const fetchMock = vi.fn<(input: string) => Promise<Response>>();

const ROOT_ELEMENT_ID = 'root';
const OWNER_ID = '11111111-1111-4111-8111-111111111111';
/** Kształt wydawany przez Supabase: 32 znaki base32, bez myślników. */
const AUTHORIZATION_ID = 'drs4p6cdwu7jttylrcajgnhwnmg3iyha';
const CONSENT_URL = `${OAUTH_CONSENT_PATH}?authorization_id=${AUTHORIZATION_ID}`;

beforeEach(() => {
  vi.stubGlobal('fetch', fetchMock);
  fetchMock.mockResolvedValue(
    new Response(JSON.stringify({ data: { tryb: 'zamknieta' }, error: null }), {
      status: 200,
      headers: { 'content-type': 'application/json' },
    }),
  );
  getSession.mockResolvedValue({ data: { session: null } });
  getUser.mockResolvedValue({ data: { user: null }, error: { message: 'Auth session missing!' } });
  onAuthStateChange.mockReturnValue({ data: { subscription: { unsubscribe: vi.fn() } } });
});

afterEach(() => {
  cleanup();
  vi.clearAllMocks();
  vi.unstubAllEnvs();
  vi.unstubAllGlobals();
  document.body.innerHTML = '';
  window.history.pushState({}, '', '/');
});

describe('App', () => {
  it('bez sesji pokazuje na korzeniu panelu ekran logowania', async () => {
    render(<App />);

    expect((await screen.findByRole('heading', { level: 1 })).textContent).toBe('Zaloguj się albo dołącz');
  });

  it('bez sesji prowadzi z „/szablony” na ekran logowania', async () => {
    // Trasa szablonów siedzi wewnątrz `RequireSession` — wejście wprost pod
    // adres nie może pokazać nawet szkieletu widoku konta.
    window.history.pushState({}, '', TEMPLATES_PATH);

    render(<App />);

    expect((await screen.findByRole('heading', { level: 1 })).textContent).toBe('Zaloguj się albo dołącz');
  });

  it('z sesją „/szablony” zostaje pod swoim adresem i pokazuje panel', async () => {
    // Bez tej asercji poprzedni test niczego nie dowodzi: adres NIEISTNIEJĄCY
    // też kończy na ekranie logowania (fallback `*` → korzeń → guard).
    getSession.mockResolvedValue({
      data: { session: { user: { id: OWNER_ID } } },
    });
    window.history.pushState({}, '', TEMPLATES_PATH);

    render(<App />);

    expect(
      (await screen.findAllByRole('link', { name: 'Szablony' }))[0]?.getAttribute('href'),
    ).toBe(TEMPLATES_PATH);
    expect(window.location.pathname).toBe(TEMPLATES_PATH);
  });

  it('zalogowanego na „/logowanie” odsyła na listę ofert i NIE renderuje formularza', async () => {
    // Formularz wysyła magic link, a limit mailera GoTrue to rząd 2/h na konto:
    // powrót na `/logowanie` z zakładki i odruchowy klik spalają pulę
    // zalogowanemu handlowcowi na godzinę.
    getSession.mockResolvedValue({
      data: { session: { user: { id: OWNER_ID } } },
    });
    window.history.pushState({}, '', LOGIN_PATH);

    render(<App />);

    expect((await screen.findAllByRole('link', { name: 'Oferty' }))[0]).toBeDefined();
    expect(window.location.pathname).toBe(OFFERS_PATH);
    expect(screen.queryByRole('heading', { level: 1, name: 'Zaloguj się albo dołącz' })).toBeNull();
  });
});

describe('trasa strony zgody OAuth', () => {
  it('bez sesji ZOSTAJE pod swoim adresem i prosi o zalogowanie z powrotem do prośby', async () => {
    // `RequireSession` odesłałby na `/logowanie` i zgubił `authorization_id` —
    // po zalogowaniu użytkownik nie miałby jak wrócić do tej samej prośby.
    window.history.pushState({}, '', CONSENT_URL);

    render(<App />);

    expect(await screen.findByText(CONSENT_TEXTS.loginNotice)).toBeDefined();
    expect(window.location.pathname).toBe(OAUTH_CONSENT_PATH);
    expect(window.location.search).toBe(`?authorization_id=${AUTHORIZATION_ID}`);
  });

  it('z sesją pokazuje prośbę, a nie listę ofert', async () => {
    // `RedirectIfAuthenticated` wyrzuciłby stąd dokładnie tego, kto ma
    // decydować o zgodzie.
    getSession.mockResolvedValue({ data: { session: { user: { id: OWNER_ID } } } });
    getUser.mockResolvedValue({ data: { user: { id: OWNER_ID } }, error: null });
    getAuthorizationDetails.mockResolvedValue({
      data: {
        authorization_id: AUTHORIZATION_ID,
        redirect_uri: 'https://claude.ai/api/mcp/auth_callback',
        client: { id: 'klient', name: 'Claude', uri: '', logo_uri: '' },
        user: { id: OWNER_ID, email: 'kacper@twojafirma.pl' },
        scope: '',
      },
      error: null,
    });
    window.history.pushState({}, '', CONSENT_URL);

    render(<App />);

    expect(await screen.findByRole('button', { name: CONSENT_TEXTS.approve })).toBeDefined();
    expect(window.location.pathname).toBe(OAUTH_CONSENT_PATH);
  });
});

describe('start aplikacji bez DSN monitoringu', () => {
  beforeEach(() => {
    vi.resetModules();
    vi.stubEnv('VITE_SENTRY_DSN_DASHBOARD', '');

    const container = document.createElement('div');
    container.id = ROOT_ELEMENT_ID;
    document.body.append(container);
  });

  it('montuje aplikację i nie inicjuje monitoringu', async () => {
    await act(async () => {
      await import('./main.js');
    });

    expect(vi.mocked(Sentry.init)).not.toHaveBeenCalled();
    expect(document.getElementById(ROOT_ELEMENT_ID)?.textContent).toContain('Zaloguj się');
  });
});

describe('start aplikacji z DSN monitoringu', () => {
  beforeEach(() => {
    vi.resetModules();
    vi.stubEnv('VITE_SENTRY_DSN_DASHBOARD', 'https://klucz@example.invalid/1');

    const container = document.createElement('div');
    container.id = ROOT_ELEMENT_ID;
    document.body.append(container);
  });

  it('inicjuje monitoring bez automatycznego wysyłania PII', async () => {
    await act(async () => {
      await import('./main.js');
    });

    expect(vi.mocked(Sentry.init)).toHaveBeenCalledTimes(1);
    expect(vi.mocked(Sentry.init)).toHaveBeenCalledWith(
      expect.objectContaining({
        dsn: 'https://klucz@example.invalid/1',
        sendDefaultPii: false,
      }),
    );
  });

  it('przekazany beforeSend zdejmuje authorization_id z adresu strony', async () => {
    // Integracja `httpContext` dokłada `request.url = window.location.href` do
    // KAŻDEGO zdarzenia, a `sendDefaultPii: false` tego nie dotyczy — bez
    // `beforeSend` jednorazowy identyfikator prośby jechałby do Sentry mimo
    // starannie oczyszczonego `message`.
    await act(async () => {
      await import('./main.js');
    });

    const [options] = requireElement(
      vi.mocked(Sentry.init).mock.calls[0],
      'wywołanie Sentry.init',
    );
    const beforeSend = options?.beforeSend;

    if (typeof beforeSend !== 'function') {
      throw new Error('Sentry.init nie dostał beforeSend');
    }

    const event: ErrorEvent = {
      type: undefined,
      request: {
        url: 'https://panel.example/oauth/consent?authorization_id=drs4p6cdwu7jttylrcajgnhwnmg3iyha',
      },
    };

    const sent = beforeSend(event, {});

    if (sent === null || !('request' in sent)) {
      throw new Error('beforeSend nie oddał zdarzenia');
    }

    expect(sent.request?.url).toBe('https://panel.example/oauth/consent');
    expect(JSON.stringify(sent)).not.toContain('authorization_id');
  });
});

describe('warstwa stylów', () => {
  it('wystawia tokeny motywu i buduje z nich klasę użytkową', () => {
    expect(globalCss).toMatch(/--color-canvas:\s*#faf8f4/);
    expect(globalCss).toMatch(/\.bg-canvas\s*\{[^}]*var\(--color-canvas\)/);
  });

  it('buduje aktywny stan nawigacji z tokenu primary na 12% krycia', () => {
    expect(globalCss).toMatch(/\.bg-primary\\\/12\s*\{/);
  });

  it('buduje klasy z tokenów fazy 8 użytych na stronie zgody', () => {
    // Sam wpis w `@theme` nie wystarcza: klasa powstaje dopiero wtedy, gdy
    // Tailwind zobaczy ją w źródłach. Bez tej asercji literówka w nazwie
    // tokenu albo w klasie daje ekran bez tła ostrzeżenia i bez tytułu 24 px,
    // a wszystkie testy renderu i tak są zielone.
    expect(globalCss).toMatch(/--color-status-expired-soft:\s*#fbe9e2/);
    expect(globalCss).toMatch(/--text-kpi-sm:\s*24px/);
    expect(globalCss).toMatch(
      /\.bg-status-expired-soft\s*\{[^}]*var\(--color-status-expired-soft\)/,
    );
    expect(globalCss).toMatch(/\.text-kpi-sm\s*\{[^}]*var\(--text-kpi-sm\)/);
  });
});

describe('start aplikacji z niepoprawną konfiguracją builda', () => {
  beforeEach(() => {
    vi.resetModules();
    vi.stubEnv('VITE_SENTRY_DSN_DASHBOARD', 'https://klucz@example.invalid/1');

    const container = document.createElement('div');
    container.id = ROOT_ELEMENT_ID;
    document.body.append(container);
  });

  it('inicjuje monitoring PRZED walidacją zmiennych builda i zgłasza jej awarię', async () => {
    // `lib/supabase.ts` waliduje `VITE_SUPABASE_*` fail-fast w ciele modułu.
    // Przy statycznym imporcie `App` rzucało to przed `initMonitoring()`, więc
    // źle oznaczona zmienna w Coolify dawała białą stronę i ZERO zdarzeń
    // w Sentry.
    const failure = new Error('Brak zmiennej builda VITE_SUPABASE_URL');

    // Getter zamiast rzutu z fabryki: vitest opakowałby wyjątek fabryki we
    // własny błąd, a test ma dowodzić, że do monitoringu trafia DOKŁADNIE
    // wyjątek walidacji ENV.
    vi.doMock('./App.js', () => ({
      get App(): never {
        throw failure;
      },
    }));

    await expect(import('./main.js')).rejects.toBe(failure);

    expect(vi.mocked(Sentry.init)).toHaveBeenCalledTimes(1);
    expect(vi.mocked(Sentry.captureException)).toHaveBeenCalledWith(failure);
    // Użytkownik dostaje zdanie, nie pusty ekran.
    expect(document.getElementById(ROOT_ELEMENT_ID)?.textContent).toContain(
      'Nie udało się uruchomić panelu',
    );

    vi.doUnmock('./App.js');
  });

  it('łapie awarię rzuconą przy WYKONYWANIU ciała modułu aplikacji', async () => {
    // Kształt produkcyjny: `lib/supabase.ts` rzuca przy ewaluacji modułu, a nie
    // przy odczycie bindingu `App`. Przy statycznym imporcie `App` ten rzut
    // wypada PRZED `try` w `main.tsx`, więc `renderStartupFailure()` nigdy się
    // nie wykonuje — użytkownik dostaje białą stronę. Ten test jest jedyną
    // bramką między taką zmianą a cichą regresją ekranu startu.
    vi.doMock('./App.js', () => {
      throw new Error('Brak zmiennej builda VITE_SUPABASE_URL');
    });

    await expect(import('./main.js')).rejects.toThrow();

    expect(vi.mocked(Sentry.captureException)).toHaveBeenCalledTimes(1);
    expect(document.getElementById(ROOT_ELEMENT_ID)?.textContent).toContain(
      'Nie udało się uruchomić panelu',
    );

    vi.doUnmock('./App.js');
  });
});

