import { cleanup, render, renderHook } from '@testing-library/react';
import type { Config, Driver } from 'driver.js';
import { StrictMode, useState, type JSX, type ReactNode } from 'react';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

import type { AccountProfile, TourScreen } from '../account/use-profile.js';
import { useScreenTour } from './use-screen-tour.js';

/**
 * `driver.js` jako atrapa MODUŁU: hook odpowiada za to, KIEDY przewodnik
 * startuje, co dostaje w konfiguracji i co zapisuje po zamknięciu — a nie za
 * rysowanie nakładki, której jsdom i tak nie policzy.
 */
const { driverMock, drive, destroy, markTourSeen, reloadProfile, track } = vi.hoisted(() => ({
  driverMock: vi.fn(),
  drive: vi.fn(),
  destroy: vi.fn(),
  // Atrapa ODWZOROWUJE kontrakt zapisu (`Promise<boolean>`), bo od jego wyniku
  // zależy, czy hook poprosi bramkę o ponowny odczyt profilu.
  markTourSeen: vi.fn<(userId: string, screen: TourScreen) => Promise<boolean>>(),
  reloadProfile: vi.fn<() => void>(),
  track: vi.fn(),
}));

/**
 * Pełna atrapa `Driver`, nie okrojony obiekt z rzutowaniem: ten sam obiekt
 * dostaje hook i dostaje go `onDestroyed` w teście, więc atrapa musi mieć
 * kształt kontraktu biblioteki. Metody spoza scenariusza RZUCAJĄ — użycie,
 * którego test nie przewidział, ma się wywrócić, a nie po cichu udać.
 */
function driverStub(): Driver {
  const unused = (): never => {
    throw new Error('metoda driver.js nieużywana w tym teście');
  };

  return {
    drive: (): void => {
      drive();
    },
    destroy: (): void => {
      destroy();
    },
    isActive: (): boolean => true,
    refresh: unused,
    setConfig: unused,
    setSteps: unused,
    getConfig: unused,
    getState: unused,
    getActiveIndex: unused,
    isFirstStep: unused,
    isLastStep: unused,
    getActiveStep: unused,
    getActiveElement: unused,
    getPreviousElement: unused,
    getPreviousStep: unused,
    getNextStep: unused,
    moveNext: unused,
    movePrevious: unused,
    moveTo: unused,
    hasNextStep: unused,
    hasPreviousStep: unused,
    highlight: unused,
  };
}

const instance = driverStub();

vi.mock('driver.js', () => ({
  driver: (config: Config): Driver => {
    driverMock(config);

    return instance;
  },
}));

vi.mock('../account/use-profile.js', () => ({
  markTourSeen: (userId: string, screen: TourScreen): Promise<boolean> =>
    markTourSeen(userId, screen),
}));

vi.mock('../../lib/analytics.js', () => ({ track }));

const accountProfile = vi.fn<() => AccountProfile | null>();

vi.mock('../auth/access-gate.js', () => ({
  useAccountAccess: (): AccountProfile | null => accountProfile(),
  useAccountAccessReload: (): (() => void) => reloadProfile,
}));

const OWNER_ID = '11111111-1111-4111-8111-111111111111';

function profile(overrides: Partial<AccountProfile> = {}): void {
  accountProfile.mockReturnValue({
    id: OWNER_ID,
    accessState: 'aktywne',
    role: 'user',
    source: 'zewnetrzne',
    termsAcceptedAt: new Date('2026-09-14T09:00:00+00:00'),
    deletionRequestedAt: null,
    hasWebhook: false,
    isFirstStepsDismissed: false,
    tourSeen: { oferty: false, oferta: false, szablony: false },
    ...overrides,
  });
}

/** Cele kroków listy ofert — bez nich przewodnik nie ma czego pokazać. */
function mountTargets(): void {
  const checklist = document.createElement('section');
  const settings = document.createElement('a');

  checklist.dataset.tour = 'checklista';
  settings.dataset.tour = 'ustawienia';
  document.body.append(checklist, settings);
}

function StrictWrapper({ children }: { readonly children: ReactNode }): JSX.Element {
  return <StrictMode>{children}</StrictMode>;
}

function lastConfig(): Config {
  const [config] = driverMock.mock.calls.at(-1) ?? [];

  if (config === undefined) {
    throw new Error('driver() nie zostało wywołane');
  }

  return config;
}

beforeEach(() => {
  profile();
  mountTargets();
  markTourSeen.mockResolvedValue(true);
});

afterEach(() => {
  cleanup();
  document.body.innerHTML = '';
  vi.clearAllMocks();
});

describe('useScreenTour — kiedy startuje', () => {
  it('`tour_seen_offers = true` → `driver()` nie jest wołane', () => {
    profile({ tourSeen: { oferty: true, oferta: false, szablony: false } });

    renderHook(() => {
      useScreenTour('oferty', false);
    });

    expect(driverMock).not.toHaveBeenCalled();
  });

  it('dane ekranu jeszcze się ładują → przewodnik czeka', () => {
    renderHook(() => {
      useScreenTour('oferty', true);
    });

    expect(driverMock).not.toHaveBeenCalled();
  });

  it('konto ograniczone nie dostaje przewodnika', () => {
    profile({ accessState: 'ograniczone' });

    renderHook(() => {
      useScreenTour('oferty', false);
    });

    expect(driverMock).not.toHaveBeenCalled();
  });

  it('`false` → `driver()` DOKŁADNIE raz mimo podwójnego montażu StrictMode', () => {
    const { unmount } = renderHook(
      () => {
        useScreenTour('oferty', false);
      },
      { wrapper: StrictWrapper },
    );

    expect(driverMock).toHaveBeenCalledTimes(1);
    expect(drive).toHaveBeenCalledTimes(1);

    unmount();

    // Sprzątanie należy do hooka: wyrwana z drzewa nakładka zostawiłaby
    // zasłonięty ekran i przechwycone klawisze.
    expect(destroy).toHaveBeenCalled();
  });

  it('po sprzątnięciu efektu przewodnik WRACA, a nie gaśnie na zawsze', () => {
    /*
     * Ten test stoi obok testu StrictMode, bo tamten NIE MOŻE pokazać
     * regresji, o którą chodzi: w tym środowisku (`renderHook` + React
     * z builda produkcyjnego) `<StrictMode>` nie wykonuje efektu dwa razy —
     * zmierzone sondą na gołym `useEffect`: 1 przebieg, 0 sprzątań. W dev
     * React robi efekt → sprzątanie → efekt, a sprzątanie bezwarunkowo woła
     * `destroy()`, więc zatrzask „już startowałem", który nigdy nie wraca do
     * `false`, gasił przewodnik na zawsze. Obserwowalnym odpowiednikiem tego
     * cyklu jest tu zmiana zależności: sprzątanie MUSI odwracać setup na tyle,
     * żeby kolejny przebieg odtworzył przewodnik.
     */
    const { rerender, unmount } = renderHook(
      ({ isPending }: { readonly isPending: boolean }) => {
        useScreenTour('oferty', isPending);
      },
      { initialProps: { isPending: false } },
    );

    expect(driverMock).toHaveBeenCalledTimes(1);
    expect(destroy).toHaveBeenCalledTimes(0);

    // Sprzątanie efektu (w dev: pierwszy cykl StrictMode).
    rerender({ isPending: true });

    expect(destroy).toHaveBeenCalledTimes(1);

    // Drugi przebieg efektu — przewodnik ma tu ŻYĆ, a nie zostać zgaszony.
    rerender({ isPending: false });

    expect(driverMock).toHaveBeenCalledTimes(2);
    expect(drive).toHaveBeenCalledTimes(2);
    expect(destroy).toHaveBeenCalledTimes(1);

    unmount();

    expect(destroy).toHaveBeenCalledTimes(2);
  });

  it('bez ani jednego celu na ekranie przewodnik nie startuje i nie odhacza się', () => {
    // Kroki BEZ celu (`TOURS` ma takie na każdym ekranie) zostają w liście
    // zawsze, więc pusty ekran nadal ma kroki — bramką jest cel, nie długość.
    document.body.innerHTML = '';

    renderHook(() => {
      useScreenTour('oferty', false);
    });

    expect(driverMock).not.toHaveBeenCalled();
    expect(markTourSeen).not.toHaveBeenCalled();
  });
});

describe('useScreenTour — cel za zwiniętym menu ☰ (telefon)', () => {
  /**
   * PRAWDZIWY React, nie atrapa menu: `toggler.click()` w efekcie ustawia stan,
   * a React 19 (`createRoot`) domyka go w mikrotasku, NIE synchronicznie —
   * `buildSteps` tuż po kliknięciu widziało jeszcze zwinięte menu i brało ☰
   * (smoke 9b, tura 2 na telefonie). Atrapa w `tours.test.ts` dokładała listę
   * synchronicznie, więc tamten test tej wady nie łapał.
   */
  function MobileMenu(): JSX.Element {
    const [isOpen, setIsOpen] = useState(false);

    useScreenTour('oferty', false);

    return (
      <>
        <button
          type="button"
          aria-expanded={isOpen}
          data-tour="menu"
          onClick={() => {
            setIsOpen((open) => !open);
          }}
        >
          Menu
        </button>
        {isOpen ? (
          <nav>
            <a href="/ustawienia" data-tour="ustawienia">
              Ustawienia
            </a>
            <a href="/pomoc" data-tour="pomoc">
              Pomoc
            </a>
          </nav>
        ) : null}
      </>
    );
  }

  it('podświetla pozycję ROZWINIĘTEGO menu, nie przycisk ☰', async () => {
    // Cel `ustawienia` z `mountTargets` zostaje poza menu — w tym teście
    // pozycje nawigacji mają być WYŁĄCZNIE za ☰, jak na telefonie.
    document.body.innerHTML = '';
    const checklist = document.createElement('section');
    checklist.dataset.tour = 'checklista';
    document.body.append(checklist);

    render(<MobileMenu />);

    // Start jest w mikrotasku (React domyka rozwinięcie menu w swoim, wcześniejszym).
    expect(driverMock).not.toHaveBeenCalled();
    await Promise.resolve();

    const elements = lastConfig().steps?.map((step) => step.element) ?? [];
    const settingsLink = document.querySelector('a[data-tour="ustawienia"]');
    const helpLink = document.querySelector('a[data-tour="pomoc"]');

    expect(settingsLink).not.toBeNull();
    expect(elements).toContain(settingsLink);
    expect(elements).toContain(helpLink);
    expect(elements).not.toContain(document.querySelector('[data-tour="menu"]'));
  });

  it('sprzątnięcie efektu PRZED mikrotaskiem: przewodnik nie startuje, menu wraca do zwiniętego', async () => {
    document.body.innerHTML = '';
    const checklist = document.createElement('section');
    checklist.dataset.tour = 'checklista';
    document.body.append(checklist);

    const { unmount } = render(<MobileMenu />);

    unmount();
    await Promise.resolve();

    expect(driverMock).not.toHaveBeenCalled();
    expect(destroy).not.toHaveBeenCalled();
  });
});

describe('useScreenTour — konfiguracja', () => {
  it('pomija kroki bez celu, niesie polskie przyciski i własną klasę popovera', () => {
    renderHook(() => {
      useScreenTour('oferty', false);
    });

    const config = lastConfig();

    expect(config.skipMissingElement).toBe(true);
    expect(config.popoverClass).toBe('traferto-tour');
    expect(config.doneBtnText).toBe('Koniec');
    // Na ekranie stoją dwa z czterech celów listy ofert („Kopiuj" i „Pomoc"
    // ich nie mają), więc kroków jest dokładnie tyle, ile celów.
    expect(config.steps).toHaveLength(2);
  });
});

describe('useScreenTour — zamknięcie', () => {
  it('zamknięcie przez użytkownika zapisuje kolumnę i wysyła zdarzenie z numerem kroku', () => {
    renderHook(() => {
      useScreenTour('oferty', false);
    });

    const config = lastConfig();

    config.onDestroyed?.(undefined, { popover: {} }, {
      config,
      state: {},
      driver: instance,
      index: 1,
    });

    expect(markTourSeen).toHaveBeenCalledWith(OWNER_ID, 'oferty');
    // Numer dla człowieka (od 1), nie indeks tablicy.
    expect(track).toHaveBeenCalledWith('przewodnik_zakonczony_oferty', { krok: 2 });
  });

  it('po UDANYM zapisie prosi bramkę o ponowny odczyt profilu (przewodnik nie wraca)', async () => {
    renderHook(() => {
      useScreenTour('oferty', false);
    });

    const config = lastConfig();

    config.onDestroyed?.(undefined, { popover: {} }, {
      config,
      state: {},
      driver: instance,
      index: 0,
    });

    await vi.waitFor(() => {
      expect(reloadProfile).toHaveBeenCalledTimes(1);
    });
  });

  it('NIEUDANY zapis nie udaje sukcesu — bramka nie czyta profilu od nowa', async () => {
    markTourSeen.mockResolvedValue(false);

    renderHook(() => {
      useScreenTour('oferty', false);
    });

    const config = lastConfig();

    config.onDestroyed?.(undefined, { popover: {} }, {
      config,
      state: {},
      driver: instance,
      index: 0,
    });

    await vi.waitFor(() => {
      expect(markTourSeen).toHaveBeenCalledTimes(1);
    });

    expect(reloadProfile).not.toHaveBeenCalled();
  });

  it('wyjście z ekranu w połowie NIE odhacza przewodnika', () => {
    const { unmount } = renderHook(() => {
      useScreenTour('oferty', false);
    });

    const config = lastConfig();

    // Produkcyjna kolejność: sprzątanie efektu woła `destroy()`, a driver.js
    // odpala wtedy `onDestroyed` — to samo wywołanie, inna przyczyna.
    destroy.mockImplementation(() => {
      config.onDestroyed?.(undefined, { popover: {} }, {
        config,
        state: {},
        driver: instance,
        index: 0,
      });
    });

    unmount();

    expect(destroy).toHaveBeenCalled();
    expect(markTourSeen).not.toHaveBeenCalled();
    expect(track).not.toHaveBeenCalled();
  });
});

