import { cleanup, fireEvent, render, screen } from '@testing-library/react';
import { MemoryRouter, Route, Routes } from 'react-router';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

import {
  INVITATION_PATH,
  NO_ACCESS_PATH,
  OFFERS_PATH,
  consentReturnState,
  oauthConsentPath,
} from '../../routes.js';
import type { AccountProfile, ProfileState } from '../account/use-profile.js';
import { InvitationPage } from './invitation-page.js';
import { ACCESS_TEXTS } from './texts.js';

const { rpc, abortSignal, captureException, profileState } = vi.hoisted(() => {
  // Adnotacja typu, nie asercja: stan startowy jest jednym z wariantów unii.
  const profileState: { current: ProfileState } = { current: { status: 'ladowanie' } };

  return {
    rpc: vi.fn<(fn: string) => Promise<unknown>>(),
    abortSignal: vi.fn<(signal: AbortSignal) => void>(),
    captureException: vi.fn(),
    profileState,
  };
});

// Łańcuch jak w produkcji: `rpc(...).abortSignal(signal)` jest thenable.
vi.mock('../../lib/supabase.js', () => ({
  supabase: {
    rpc: (fn: string): unknown => ({
      abortSignal: (signal: AbortSignal): Promise<unknown> => {
        abortSignal(signal);

        return rpc(fn);
      },
    }),
  },
}));

vi.mock('@sentry/react', () => ({ captureException }));

// Atrapa OTYPOWANA na `ProfileState`: nowe wymagane pole profilu albo nowy
// wariant stanu wywraca kompilację tego pliku, zamiast cicho podawać ekranowi
// kształt spoza produkcji.
vi.mock('../account/use-profile.js', () => ({
  useProfile: (): ProfileState => profileState.current,
}));

vi.mock('../auth/session-context.js', () => ({
  useSessionState: (): unknown => ({
    status: 'authenticated',
    session: { user: { id: '11111111-1111-4111-8111-111111111111' } },
  }),
}));

function profile(overrides: Partial<AccountProfile> = {}): void {
  profileState.current = {
    status: 'gotowe',
    profile: {
      id: '00000000-0000-4000-8000-000000000001',
      hasWebhook: false,
      isFirstStepsDismissed: false,
      tourSeen: { oferty: true, oferta: true, szablony: true },
      accessState: 'oczekujace',
      role: 'user',
      source: 'akademia',
      termsAcceptedAt: null,
      deletionRequestedAt: null,
      ...overrides,
    },
  };
}

/** Kształt wydawany przez Supabase: 32 znaki base32. */
const AUTHORIZATION_ID = 'drs4p6cdwu7jttylrcajgnhwnmg3iyha';

function renderPage(locationState?: Record<string, string>): ReturnType<typeof render> {
  return render(
    <MemoryRouter
      initialEntries={[
        locationState === undefined
          ? INVITATION_PATH
          : { pathname: INVITATION_PATH, state: locationState },
      ]}
    >
      <Routes>
        <Route path={INVITATION_PATH} element={<InvitationPage />} />
        <Route path={OFFERS_PATH} element={<p>lista ofert</p>} />
        <Route path={NO_ACCESS_PATH} element={<p>ekran braku dostępu</p>} />
        <Route path={oauthConsentPath(AUTHORIZATION_ID).split('?')[0]} element={<p>strona zgody</p>} />
      </Routes>
    </MemoryRouter>,
  );
}

function acceptButton(): HTMLElement {
  return screen.getByRole('button', { name: ACCESS_TEXTS.acceptCta });
}

beforeEach(() => {
  rpc.mockResolvedValue({ data: 'aktywne', error: null });
  profile();
});

afterEach(() => {
  cleanup();
  vi.clearAllMocks();
});

describe('InvitationPage — ekran zgody', () => {
  // Jeden nagłówek dla trzech dróg (decyzja 3): ekran nie wie, którą drogą
  // wszedł użytkownik, więc dla `oczekujace` (zaproszenie albo lista
  // członków) i `aktywne` bez zgody (tryb `otwarta`) renderuje to samo.
  it.each([
    ['oczekujace (zaproszenie albo lista członków)', 'oczekujace'],
    ['aktywne bez zgody (tryb otwarta)', 'aktywne'],
  ] as const)('konto %s widzi nagłówek „Witaj w Traferto” i linki do dokumentów', (_, accessState) => {
    profile({ accessState });

    renderPage();

    // Literał, nie stała: test ma zapalić się także wtedy, gdy ktoś zmieni
    // brzmienie w `texts.ts` — nagłówek jest verbatim z decyzji operatora.
    expect(screen.getByRole('heading', { name: 'Witaj w Traferto' })).toBeDefined();
    expect(screen.getByRole('heading', { name: ACCESS_TEXTS.welcomeHeading })).toBeDefined();
    // Ekran nie ma prawa mówić o drodze wejścia.
    expect(screen.queryByText(/zaprosz/i)).toBeNull();
    expect(screen.queryByText(/akademi/i)).toBeNull();
    // Dokumenty stoją pod kartą (`AuthCard`) i DOKŁADNIE raz — checkbox
    // odwołuje się do nich, więc muszą być na tym samym ekranie.
    expect(screen.getAllByRole('link', { name: 'Regulamin' })).toHaveLength(1);
    expect(screen.getAllByRole('link', { name: 'Prywatność' })).toHaveLength(1);
  });

  it('bez zaznaczonego checkboxa przycisk jest aria-disabled i nie woła RPC', () => {
    renderPage();

    expect(acceptButton().getAttribute('aria-disabled')).toBe('true');

    fireEvent.click(acceptButton());

    expect(rpc).not.toHaveBeenCalled();
  });

  it('po zgodzie i kliknięciu woła accept_terms (nigdy accept_invitation) i wpuszcza na listę ofert', async () => {
    renderPage();

    fireEvent.click(screen.getByLabelText(ACCESS_TEXTS.consentLabel));

    expect(acceptButton().getAttribute('aria-disabled')).toBe('false');

    fireEvent.click(acceptButton());

    expect(await screen.findByText('lista ofert')).toBeDefined();
    expect(rpc).toHaveBeenCalledTimes(1);
    expect(rpc).toHaveBeenCalledWith('accept_terms');
    // Alias zostaje w bazie dla starego obrazu — panel od IU-7 go NIE woła.
    expect(rpc).not.toHaveBeenCalledWith('accept_invitation');
  });

  it('odmowa „brak_zaproszenia” kieruje na /brak-dostepu', async () => {
    rpc.mockResolvedValue({ data: null, error: { code: '42501', message: 'brak_zaproszenia' } });

    renderPage();
    fireEvent.click(screen.getByLabelText(ACCESS_TEXTS.consentLabel));
    fireEvent.click(acceptButton());

    expect(await screen.findByText('ekran braku dostępu')).toBeDefined();
    // Odmowa dostępu nie jest defektem panelu — nie ma czego zgłaszać.
    expect(captureException).not.toHaveBeenCalled();
  });

  // Awaria ≠ odmowa: dwa kody z różnych warstw kończą tak samo (komunikat,
  // raport, ZERO nawigacji) — `PGRST202` to obraz przed migracją (D15),
  // `08006` to sieć. Sukces bez zapisu zgody byłby tu najgorszym wynikiem.
  it.each([
    ['PGRST202 (brak funkcji accept_terms — kod przed migracją)', 'PGRST202'],
    ['08006 (awaria połączenia)', '08006'],
  ] as const)('awaria %s nie udaje odmowy ani sukcesu: komunikat i jeden raport', async (_, code) => {
    rpc.mockResolvedValue({ data: null, error: { code, message: 'awaria' } });

    renderPage();
    fireEvent.click(screen.getByLabelText(ACCESS_TEXTS.consentLabel));
    fireEvent.click(acceptButton());

    expect(await screen.findByRole('alert')).toHaveProperty(
      'textContent',
      ACCESS_TEXTS.acceptFailed,
    );
    expect(screen.queryByText('ekran braku dostępu')).toBeNull();
    expect(screen.queryByText('lista ofert')).toBeNull();
    expect(captureException).toHaveBeenCalledTimes(1);
  });
});

describe('InvitationPage — konto oczekujące, które zgodę ma już za sobą', () => {
  it('rozstrzyga samo: konto z dostępem wpuszcza do panelu bez pytania', async () => {
    profile({ termsAcceptedAt: new Date('2026-09-14T09:00:00+00:00') });

    renderPage();

    expect(await screen.findByText('lista ofert')).toBeDefined();
    expect(rpc).toHaveBeenCalledTimes(1);
    // Sonda automatyczna też jedzie na `accept_terms`, nie na aliasie.
    expect(rpc).toHaveBeenCalledWith('accept_terms');
    expect(screen.queryByText(ACCESS_TEXTS.consentLabel)).toBeNull();
  });

  it('awaria RPC nie zostawia ekranu w wiecznym ładowaniu i pozwala ponowić', async () => {
    profile({ termsAcceptedAt: new Date('2026-09-14T09:00:00+00:00') });
    rpc.mockResolvedValueOnce({ data: null, error: { code: '08006', message: 'sieć padła' } });

    renderPage();

    expect(await screen.findByRole('alert')).toHaveProperty(
      'textContent',
      ACCESS_TEXTS.acceptFailed,
    );
    expect(screen.queryByText('lista ofert')).toBeNull();
    expect(captureException).toHaveBeenCalledTimes(1);

    // Zatrzask pierwszej próby nie może zamykać drogi do drugiej.
    rpc.mockResolvedValue({ data: 'aktywne', error: null });
    fireEvent.click(screen.getByRole('button', { name: ACCESS_TEXTS.retryCta }));

    expect(await screen.findByText('lista ofert')).toBeDefined();
  });

  it('brak zaproszenia kieruje na /brak-dostepu bez ekranu zgody', async () => {
    profile({ termsAcceptedAt: new Date('2026-09-14T09:00:00+00:00') });
    rpc.mockResolvedValue({ data: null, error: { code: '42501', message: 'brak_zaproszenia' } });

    renderPage();

    expect(await screen.findByText('ekran braku dostępu')).toBeDefined();
  });

  it('sonda przerwana odmontowaniem nie ustawia stanu ani nie raportuje', async () => {
    profile({ termsAcceptedAt: new Date('2026-09-14T09:00:00+00:00') });

    let settle: (value: unknown) => void = () => {
      throw new Error('RPC nie została jeszcze wywołana');
    };

    rpc.mockImplementation(
      () =>
        new Promise((resolve) => {
          settle = resolve;
        }),
    );

    const { unmount } = renderPage();

    expect(rpc).toHaveBeenCalledTimes(1);
    expect(abortSignal).toHaveBeenCalledTimes(1);

    const [signal] = abortSignal.mock.calls[0] ?? [];

    if (signal === undefined) {
      throw new Error('RPC poszła bez sygnału przerwania');
    }

    expect(signal.aborted).toBe(false);
    unmount();
    expect(signal.aborted).toBe(true);

    // `postgrest-js` oddaje przerwanie jako `error` z pustym `code`, nie wyjątkiem.
    settle({ data: null, error: { code: '', message: 'AbortError' } });
    await Promise.resolve();
    await Promise.resolve();

    expect(captureException).not.toHaveBeenCalled();
  });

  it('po sukcesie wraca na prośbę OAuth ze stanu nawigacji, nie do listy ofert', async () => {
    renderPage(consentReturnState(AUTHORIZATION_ID));

    fireEvent.click(screen.getByRole('checkbox'));
    fireEvent.click(acceptButton());

    expect(await screen.findByText('strona zgody')).toBeDefined();
    expect(screen.queryByText('lista ofert')).toBeNull();
  });

  it('stan nawigacji spoza strony zgody nie zmienia celu po sukcesie', async () => {
    renderPage({ returnTo: '/ustawienia' });

    fireEvent.click(screen.getByRole('checkbox'));
    fireEvent.click(acceptButton());

    expect(await screen.findByText('lista ofert')).toBeDefined();
  });
});

