import { ACCOUNT_LIMITS, formatLimitForHuman } from '@oferty/shared';
import { cleanup, fireEvent, render, screen } from '@testing-library/react';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

import type { AccountProfile } from '../account/use-profile.js';
import { HelpPage } from './help-page.js';
import { HELP_TEXTS, PLUGIN_COMMAND } from './texts.js';

const OWNER_ID = '11111111-1111-4111-8111-111111111111';

const { from, update, eq, track, reloadProfile } = vi.hoisted(() => ({
  reloadProfile: vi.fn<() => void>(),
  from: vi.fn<(table: string) => unknown>(),
  // Atrapy OTYPOWANE: bez tego `mock.calls` niesie `any[]` i odczyt ładunku
  // wymagałby rzutowania, które przepuściłoby zmianę sygnatury.
  update: vi.fn<(patch: Record<string, unknown>) => unknown>(),
  eq: vi.fn<(column: string, value: string) => unknown>(),
  track: vi.fn<(event: string) => void>(),
}));

vi.mock('../../lib/supabase.js', () => ({
  supabase: {
    from: (table: string): unknown => from(table),
  },
}));

vi.mock('../../lib/analytics.js', () => ({
  track: (event: string): void => {
    track(event);
  },
}));

const profile = vi.fn<() => AccountProfile | null>();

vi.mock('../auth/access-gate.js', () => ({
  useAccountAccess: (): AccountProfile | null => profile(),
  useAccountAccessReload: (): (() => void) => reloadProfile,
}));

/** Profil zawężony do tego, co ekran pomocy realnie czyta (identyfikator). */
function readyProfile(): AccountProfile {
  return {
    id: OWNER_ID,
    accessState: 'aktywne',
    role: 'user',
    source: 'zewnetrzne',
    termsAcceptedAt: new Date('2026-09-14T09:00:00+00:00'),
    deletionRequestedAt: null,
    hasWebhook: false,
    isFirstStepsDismissed: false,
    tourSeen: { oferty: true, oferta: true, szablony: true },
  };
}

function pageText(): string {
  return document.body.textContent ?? '';
}

beforeEach(() => {
  profile.mockReturnValue(readyProfile());
  from.mockReturnValue({ update: (patch: Record<string, unknown>): unknown => update(patch) });
  update.mockReturnValue({ eq: (column: string, value: string): unknown => eq(column, value) });
  eq.mockResolvedValue({ error: null });
});

afterEach(() => {
  cleanup();
  vi.clearAllMocks();
});

describe('HelpPage — treść', () => {
  it('rysuje sześć sekcji pomocy', () => {
    render(<HelpPage />);

    const headings = [
      HELP_TEXTS.connectHeading,
      HELP_TEXTS.templatesHeading,
      HELP_TEXTS.offersHeading,
      HELP_TEXTS.limitsHeading,
      HELP_TEXTS.webhookHeading,
      HELP_TEXTS.skillHeading,
    ];

    for (const heading of headings) {
      // Pusta etykieta dałaby zielone `getByRole` na przypadkowym nagłówku.
      expect(heading).not.toBe('');
      expect(screen.getByRole('heading', { level: 2, name: heading })).toBeDefined();
    }

    expect(headings).toHaveLength(6);
    // Sekcje pomocy + karta przewodnika — żadnego nagłówka drugiego poziomu
    // poza tymi siedmioma, czyli sekcji jest DOKŁADNIE sześć.
    expect(screen.getAllByRole('heading', { level: 2 })).toHaveLength(headings.length + 1);
  });

  it('podaje limity z kontraktu, z dopiskiem o wartościach domyślnych', () => {
    render(<HelpPage />);

    // Kotwice po OBU stronach frazy: `toContain('10 szablonów')` przeszłoby
    // też dla „110 szablonów", a `toContain('200 MB')` dla „1200 MB".
    const text = pageText();

    expect(text).toContain(`: ${String(ACCOUNT_LIMITS.offersPerMonth)} ofert miesięcznie,`);
    expect(text).toContain(`, ${String(ACCOUNT_LIMITS.publicationsPerHour)} publikacji na godzinę,`);
    expect(text).toContain(`, ${String(ACCOUNT_LIMITS.templates)} szablonów i `);
    expect(text).toContain(
      ` i ${formatLimitForHuman(ACCOUNT_LIMITS.storageMaxBytes)} miejsca na grafiki.`,
    );
    expect(text).toContain(
      ` najwyżej ${formatLimitForHuman(ACCOUNT_LIMITS.assetMaxBytes)}.`,
    );

    // Druga strona tej samej pary: fraza zbudowana z kontraktu ma brzmieć
    // dokładnie tak, jak brzmi decyzja operatora cytowana w regulaminie.
    expect(`, ${String(ACCOUNT_LIMITS.templates)} szablonów i `).toBe(', 10 szablonów i ');
    expect(formatLimitForHuman(ACCOUNT_LIMITS.storageMaxBytes)).toBe('200 MB');
    expect(formatLimitForHuman(ACCOUNT_LIMITS.assetMaxBytes)).toBe('10 MB');

    expect(text).toContain('to wartości domyślne — Twoje konto może mieć ustawione inne.');
    // Ustawienia nie pokazują ani jednej z tych liczb, więc zdanie nie ma
    // prawa tam odesłać — strażnik na frazę, która to robiła.
    expect(text).not.toContain('zobaczysz w Ustawieniach');
  });

  it('niesie komendę pluginu verbatim i zdanie lustrzane o wizycie', () => {
    render(<HelpPage />);

    expect(PLUGIN_COMMAND).toBe('/plugin marketplace add AIBiz-Automatyzacje/oferty-plugin');
    expect(screen.getByText(PLUGIN_COMMAND)).toBeDefined();

    /*
     * Zdanie lustrzane — ta sama myśl stoi w widoku oferty i w kroku
     * przewodnika, ale w innym brzmieniu; tutaj obowiązuje wersja z planu.
     */
    expect(
      screen.getByText(
        'Otwarcie adresu oferty przez Ciebie liczy się tak samo jak otwarcie przez klienta.',
      ),
    ).toBeDefined();
  });

  it('nie zaprasza do kontaktu ANI JEDNYM zdaniem', () => {
    render(<HelpPage />);

    const text = pageText();

    // Bez tej asercji każdy wzorzec poniżej byłby zielony dla pustej strony.
    expect(text).not.toBe('');

    // Kotwice granicy słowa: dopasowanie podłańcuchem gubi odmianę i nie
    // odróżnia „skontaktuj się" od „skontaktujemy".
    const contactPatterns = [
      /\bnapisz\s+do\s+nas\b/iu,
      /\bskontaktuj\s+si[eę]\b/iu,
      /\bodezwij\s+si[eę]\b/iu,
      /\bdaj\s+nam\s+zna[cć]\b/iu,
    ];

    for (const pattern of contactPatterns) {
      expect(pattern.test(text)).toBe(false);
    }
  });
});

describe('HelpPage — „Pokaż przewodnik ponownie"', () => {
  it('zeruje trzy kolumny `tour_seen_*` jednym zapisem i wysyła zdarzenie', async () => {
    render(<HelpPage />);

    fireEvent.click(screen.getByRole('button', { name: HELP_TEXTS.tourRestart }));

    expect(from).toHaveBeenCalledWith('profiles');
    expect(update).toHaveBeenCalledTimes(1);
    expect(update).toHaveBeenCalledWith({
      tour_seen_offers: false,
      tour_seen_offer_details: false,
      tour_seen_templates: false,
    });
    // Filtr po `id` nie jest zabezpieczeniem (jest nim polityka), tylko
    // jedynym sposobem wskazania wiersza — bez niego `update` dotyczy
    // wszystkich wierszy, które polityka przepuści.
    expect(eq).toHaveBeenCalledWith('id', OWNER_ID);

    // Potwierdzenie pokazuje się dopiero po ODPOWIEDZI bazy: zdanie obiecuje
    // czynność, więc przed wynikiem zapisu nie ma prawa stać na ekranie.
    expect(await screen.findByText(HELP_TEXTS.tourRestartDone)).toBeDefined();
    // Zdarzenie opisuje FAKT, a nie sam gest — leci z gałęzi sukcesu.
    expect(track).toHaveBeenCalledWith('przewodnik_wlaczony_ponownie');
    expect(screen.queryByText(HELP_TEXTS.tourRestartFailed)).toBeNull();
    // Profil bramki jest czytany raz, nad `Outlet`-em: bez przeładowania
    // przewodnik wróciłby dopiero po pełnym odświeżeniu strony.
    expect(reloadProfile).toHaveBeenCalledTimes(1);
  });

  it('dwa kliknięcia przed odpowiedzią bazy to JEDEN zapis i JEDNO zdarzenie', async () => {
    let settle: (result: { error: null }) => void = () => undefined;

    eq.mockReturnValue(
      new Promise<{ error: null }>((resolve) => {
        settle = resolve;
      }),
    );

    render(<HelpPage />);

    const button = screen.getByRole('button', { name: HELP_TEXTS.tourRestart });

    fireEvent.click(button);
    fireEvent.click(button);

    expect(update).toHaveBeenCalledTimes(1);
    // `aria-disabled`, nie `disabled` — przycisk nie gubi fokusu w trakcie zapisu.
    expect(button.getAttribute('aria-disabled')).toBe('true');

    settle({ error: null });

    expect(await screen.findByText(HELP_TEXTS.tourRestartDone)).toBeDefined();
    expect(track).toHaveBeenCalledTimes(1);
    expect(button.getAttribute('aria-disabled')).toBe('false');
  });

  it('region na żywo stoi w drzewie od początku, a niepowodzenie ogłasza jako `alert`', async () => {
    eq.mockResolvedValue({ error: { code: '42501', message: 'permission denied' } });

    render(<HelpPage />);

    // Pusty kontener `status` istnieje PRZED kliknięciem — czytnik ekranu
    // ogłasza zmianę treści regionu, nie sam region.
    expect(screen.getByRole('status').textContent).toBe('');

    fireEvent.click(screen.getByRole('button', { name: HELP_TEXTS.tourRestart }));

    expect((await screen.findByRole('alert')).textContent).toBe(HELP_TEXTS.tourRestartFailed);
    expect(screen.queryByRole('status')).toBeNull();
  });

  it('nieudany zapis → zdanie o nieudanej próbie i BEZ przeładowania profilu', async () => {
    eq.mockResolvedValue({ error: { code: '42501', message: 'permission denied' } });

    render(<HelpPage />);

    fireEvent.click(screen.getByRole('button', { name: HELP_TEXTS.tourRestart }));

    expect(await screen.findByText(HELP_TEXTS.tourRestartFailed)).toBeDefined();
    expect(screen.queryByText(HELP_TEXTS.tourRestartDone)).toBeNull();
    expect(reloadProfile).not.toHaveBeenCalled();
    // Nic nie zostało włączone ponownie, więc licznik tej czynności nie tyka.
    expect(track).not.toHaveBeenCalled();
  });

  it('bez profilu z bramki nie zapisuje niczego, nie liczy zdarzenia, a zdanie mówi o nieudanej próbie', () => {
    profile.mockReturnValue(null);

    render(<HelpPage />);

    fireEvent.click(screen.getByRole('button', { name: HELP_TEXTS.tourRestart }));

    expect(update).not.toHaveBeenCalled();
    // Zdarzenie „przewodnik włączony ponownie" mówi o SKUTKU, którego tu nie
    // ma — inaczej metryka liczyłaby też kliknięcia zakończone komunikatem
    // o niepowodzeniu.
    expect(track).not.toHaveBeenCalled();
    // Nic nie zapisano, więc obietnica „pokaże się przy następnym wejściu"
    // byłaby tu nieprawdą.
    expect(screen.getByText(HELP_TEXTS.tourRestartFailed)).toBeDefined();
    expect(screen.queryByText(HELP_TEXTS.tourRestartDone)).toBeNull();
  });
});

