import { cleanup, renderHook, waitFor } from '@testing-library/react';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

import type { ProfileState } from './use-profile.js';

/**
 * `vi.hoisted`, żeby atrapy przetrwały `vi.resetModules()`: zatrzask raportu
 * do Sentry jest stanem MODUŁU, więc każdy test wczytuje hook od nowa i musi
 * trzymać tę samą funkcję `captureException`, którą hook wtedy zobaczy.
 */
const { from, select, update, eq, maybeSingle, abortSignal, captureException } = vi.hoisted(() => ({
  from: vi.fn<(table: string) => unknown>(),
  update: vi.fn<(patch: Record<string, unknown>) => unknown>(),
  // Atrapy OTYPOWANE: bez tego `mock.calls` niesie `any[]`, a odczyt listy
  // kolumn wymagałby rzutowania, które przepuściłoby zmianę sygnatury.
  select: vi.fn<(columns: string) => unknown>(),
  eq: vi.fn<(column: string, value: string) => unknown>(),
  maybeSingle: vi.fn(),
  abortSignal: vi.fn(),
  captureException: vi.fn(),
}));

vi.mock('../../lib/supabase.js', () => ({
  supabase: {
    from: (table: string): unknown => from(table),
  },
}));

vi.mock('@sentry/react', () => ({ captureException }));

const OWNER_ID = '11111111-1111-4111-8111-111111111111';

/** Wiersz dokładnie w kolumnach grantu z migracji `20260914100000`. */
const ACTIVE_ROW = {
  id: OWNER_ID,
  access_state: 'aktywne',
  role: 'user',
  source: 'zewnetrzne',
  terms_accepted_at: '2026-09-14T09:00:00+00:00',
  deletion_requested_at: null,
  webhook_host: null,
  first_steps_dismissed_at: null,
  tour_seen_offers: false,
  tour_seen_offer_details: false,
  tour_seen_templates: false,
};

function respondWith(result: unknown): void {
  maybeSingle.mockResolvedValue(result);
}

async function renderProfile(): Promise<() => ProfileState> {
  // Świeży moduł per test: zatrzask „zgłoszone raz na proces" nie może
  // przeciekać między testami.
  vi.resetModules();
  const { useProfile } = await import('./use-profile.js');
  const { result } = renderHook(() => useProfile(OWNER_ID));

  await waitFor(() => {
    expect(result.current.status).not.toBe('ladowanie');
  });

  return () => result.current;
}

beforeEach(() => {
  from.mockReturnValue({ select: (columns: string): unknown => select(columns) });
  select.mockReturnValue({ eq: (column: string, value: string): unknown => eq(column, value) });
  // Kolejność łańcucha jak w produkcji: `abortSignal` PRZED `maybeSingle()`.
  eq.mockReturnValue({ abortSignal: (): unknown => abortSignal() });
  abortSignal.mockReturnValue({ maybeSingle });
  respondWith({ data: ACTIVE_ROW, error: null });
});

afterEach(() => {
  cleanup();
  vi.clearAllMocks();
});

describe('useProfile — odczyt własnego wiersza', () => {
  it('pyta o profile własnym identyfikatorem i oddaje kolumny dostępu', async () => {
    const current = await renderProfile();
    const state = current();

    expect(from).toHaveBeenCalledWith('profiles');
    // Filtr po `id` NIE jest ozdobą: administrator widzi wszystkie wiersze,
    // więc bez niego `maybeSingle()` wywraca się na „więcej niż jeden wiersz".
    expect(eq).toHaveBeenCalledWith('id', OWNER_ID);

    const [columns = ''] = select.mock.calls[0] ?? [];
    // Bez tej asercji `toContain` na pustym łańcuchu byłoby zielone dla kodu,
    // który nie wybiera ani jednej kolumny.
    expect(columns).not.toBe('');
    expect(columns).toContain('access_state');
    expect(columns).toContain('terms_accepted_at');
    // Kolumny onboardingu (faza 9b): bez nich checklista i przewodnik nie
    // mają skąd wziąć stanu, a kolumnowy grant SELECT robi z literówki
    // awarię CAŁEGO odczytu profilu, czyli bramki dostępu.
    expect(columns).toContain('first_steps_dismissed_at');
    expect(columns).toContain('tour_seen_offers');
    expect(columns).toContain('tour_seen_offer_details');
    expect(columns).toContain('tour_seen_templates');
    expect(columns).toContain('webhook_host');

    expect(state.status).toBe('gotowe');

    if (state.status !== 'gotowe') {
      return;
    }

    expect(state.profile.accessState).toBe('aktywne');
    expect(state.profile.role).toBe('user');
    expect(state.profile.termsAcceptedAt).toEqual(new Date('2026-09-14T09:00:00+00:00'));
    expect(state.profile.deletionRequestedAt).toBeNull();
    expect(state.profile.id).toBe(OWNER_ID);
    expect(state.profile.hasWebhook).toBe(false);
    expect(state.profile.isFirstStepsDismissed).toBe(false);
    expect(state.profile.tourSeen).toEqual({ oferty: false, oferta: false, szablony: false });
  });

  it('webhook i flagi onboardingu czyta z wiersza, nie z domysłu', async () => {
    respondWith({
      data: {
        ...ACTIVE_ROW,
        webhook_host: 'hooks.example.com',
        first_steps_dismissed_at: '2026-09-14T11:00:00+00:00',
        tour_seen_offers: true,
      },
      error: null,
    });

    const state = (await renderProfile())();

    expect(state.status).toBe('gotowe');

    if (state.status !== 'gotowe') {
      return;
    }

    expect(state.profile.hasWebhook).toBe(true);
    expect(state.profile.isFirstStepsDismissed).toBe(true);
    expect(state.profile.tourSeen).toEqual({ oferty: true, oferta: false, szablony: false });
  });

  it('rolę spoza zamkniętej listy sprowadza do zwykłego konta, nie do admina', async () => {
    respondWith({ data: { ...ACTIVE_ROW, role: 'superadmin' }, error: null });

    const state = (await renderProfile())();

    expect(state.status).toBe('gotowe');
    expect(state.status === 'gotowe' ? state.profile.role : null).toBe('user');
  });

  it('brak wiersza z żywą sesją to stan `brak`, nie awaria', async () => {
    respondWith({ data: null, error: null });

    const state = (await renderProfile())();

    expect(state.status).toBe('brak');
    // Skasowane konto nie jest awarią do zgłoszenia — bramka po prostu wylogowuje.
    expect(captureException).not.toHaveBeenCalled();
  });

  it('błąd odczytu to `awaria` (nie „brak konta") i jeden raport na proces', async () => {
    respondWith({ data: null, error: { code: '08006', message: 'connection failure' } });

    const state = (await renderProfile())();

    expect(state.status).toBe('awaria');
    expect(captureException).toHaveBeenCalledTimes(1);
  });

  it('nieparsowalną datę zgody traktuje jak awarię, nie jak brak zgody', async () => {
    // Cicha degradacja do `null` wysyłałaby człowieka w kółko na ekran
    // regulaminu, którego przyjęcie nic by nie zmieniało.
    respondWith({ data: { ...ACTIVE_ROW, terms_accepted_at: 'wczoraj' }, error: null });

    const state = (await renderProfile())();

    expect(state.status).toBe('awaria');
  });

  it('nieznany stan dostępu to awaria, nie ciche wpuszczenie do panelu', async () => {
    respondWith({ data: { ...ACTIVE_ROW, access_state: 'zawieszone' }, error: null });

    const state = (await renderProfile())();

    expect(state.status).toBe('awaria');
  });
});

/**
 * Zapisy własnego wiersza mają u KONSUMENTÓW atrapy (`use-screen-tour`,
 * `use-first-steps`, `help-page`), więc bez tego bloku ani tabela
 * `TOUR_PATCHES`, ani filtr `.eq('id', …)`, ani stempel czasu nie były pokryte
 * ani jedną asercją dotykającą ich kodu.
 */
describe('zapisy własnego wiersza', () => {
  /** Łańcuch `from().update().eq()` — inny niż odczyt, więc własny montaż. */
  function arrangeUpdate(result: unknown): void {
    from.mockReturnValue({ update: (patch: Record<string, unknown>): unknown => update(patch) });
    update.mockReturnValue({ eq: (column: string, value: string): unknown => eq(column, value) });
    eq.mockResolvedValue(result);
  }

  async function loadWrites(): Promise<typeof import('./use-profile.js')> {
    vi.resetModules();

    return import('./use-profile.js');
  }

  beforeEach(() => {
    arrangeUpdate({ error: null });
  });

  it.each([
    ['oferty', { tour_seen_offers: true }],
    ['oferta', { tour_seen_offer_details: true }],
    ['szablony', { tour_seen_templates: true }],
  ] as const)('markTourSeen(%s) zapisuje własną kolumnę wiersza konta', async (screen, patch) => {
    const { markTourSeen } = await loadWrites();

    await expect(markTourSeen(OWNER_ID, screen)).resolves.toBe(true);

    expect(from).toHaveBeenCalledWith('profiles');
    // Cały ładunek, nie `objectContaining`: zapis ma ruszyć DOKŁADNIE jedną
    // kolumnę z grantu, a nie przy okazji zerować dwie pozostałe.
    expect(update).toHaveBeenCalledWith(patch);
    // Filtr po `id` to jedyny sposób wskazania wiersza — bez niego `update`
    // dotyczy wszystkich wierszy, które polityka przepuści.
    expect(eq).toHaveBeenCalledWith('id', OWNER_ID);
    expect(captureException).not.toHaveBeenCalled();
  });

  it('dismissFirstSteps stempluje chwilę zamknięcia datą ISO 8601', async () => {
    const { dismissFirstSteps } = await loadWrites();

    await expect(dismissFirstSteps(OWNER_ID)).resolves.toBe(true);

    const [patch] = update.mock.calls[0] ?? [];
    const stamp = patch?.['first_steps_dismissed_at'];

    // Kolumna jest `timestamptz`: łańcuch musi dać się sparsować, a nie tylko
    // „istnieć" — `toBeDefined()` przeszłoby dla dowolnego śmiecia.
    expect(typeof stamp).toBe('string');
    expect(new Date(String(stamp)).toISOString()).toBe(stamp);
    expect(eq).toHaveBeenCalledWith('id', OWNER_ID);
  });

  it('odmowa zapisu (błąd z `eq`) oddaje false i JEDEN raport na proces', async () => {
    arrangeUpdate({ error: { code: '42501', message: 'permission denied' } });

    const { dismissFirstSteps, markTourSeen } = await loadWrites();

    await expect(dismissFirstSteps(OWNER_ID)).resolves.toBe(false);
    await expect(markTourSeen(OWNER_ID, 'oferty')).resolves.toBe(false);

    // Zatrzask zapisów jest modułowy: druga odmowa w tej samej sesji nie
    // dokłada zdarzenia, bo jedna przyczyna (odebrany grant) dotyczy każdego
    // konta i każdego gestu.
    expect(captureException).toHaveBeenCalledTimes(1);
  });
});

