import { cleanup, render, screen } from '@testing-library/react';
import type { JSX } from 'react';
import { MemoryRouter, Route, Routes } from 'react-router';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

import { INVITATION_PATH, LOGIN_PATH, OFFERS_PATH } from '../../routes.js';
import { RestrictedBanner, RESTRICTED_BANNER_TEXT } from '../access/restricted-banner.js';
import { ACCESS_TEXTS } from '../access/texts.js';
import type { AccountProfile, ProfileState } from '../account/use-profile.js';
import { AccessGate } from './access-gate.js';

const { signOut, captureException, profileState } = vi.hoisted(() => {
  // Adnotacja typu, nie asercja: stan startowy jest jednym z wariantów unii.
  const profileState: { current: ProfileState } = { current: { status: 'ladowanie' } };

  return {
    signOut: vi.fn<(options: { readonly scope: string }) => unknown>(),
    captureException: vi.fn(),
    profileState,
  };
});

vi.mock('../../lib/supabase.js', () => ({
  supabase: {
    auth: {
      signOut: (options: { readonly scope: string }): unknown => signOut(options),
    },
  },
}));

vi.mock('@sentry/react', () => ({ captureException }));

/**
 * Hook profilu jest tu atrapą, bo testujemy BRAMKĘ, a nie odczyt z bazy —
 * ten ma własny plik (`features/account/use-profile.test.ts`). Atrapa jest
 * OTYPOWANA na `ProfileState`: gdyby profil dostał nowe wymagane pole albo
 * stan nowy wariant, ten plik przestałby się kompilować zamiast cicho
 * podawać bramce kształt, którego produkcja nie zna.
 */
vi.mock('../account/use-profile.js', async (importOriginal) => ({
  // Reguła `needsTermsScreen` zostaje PRAWDZIWA — to ją bramka egzekwuje.
  ...(await importOriginal<typeof import('../account/use-profile.js')>()),
  useProfile: (): ProfileState => profileState.current,
}));

/** Sesja jest zawsze obecna: bramka dostępu siedzi wewnątrz `RequireSession`. */
vi.mock('./session-context.js', () => ({
  useSessionState: (): unknown => ({
    status: 'authenticated',
    session: { user: { id: '11111111-1111-4111-8111-111111111111' } },
  }),
}));

const PANEL_TEXT = 'treść panelu';

function profile(overrides: Partial<AccountProfile> = {}): void {
  profileState.current = {
    status: 'gotowe',
    profile: {
      id: '00000000-0000-4000-8000-000000000001',
      hasWebhook: false,
      isFirstStepsDismissed: false,
      tourSeen: { oferty: true, oferta: true, szablony: true },
      accessState: 'aktywne',
      role: 'user',
      source: 'zewnetrzne',
      termsAcceptedAt: new Date('2026-09-14T09:00:00+00:00'),
      deletionRequestedAt: null,
      ...overrides,
    },
  };
}

/** Drzewo bramki — to samo dla `render` i dla `rerender` (ponowny odczyt). */
function gateTree(): JSX.Element {
  return (
    <MemoryRouter initialEntries={[OFFERS_PATH]}>
      <Routes>
        <Route
          path={OFFERS_PATH}
          element={
            <AccessGate>
              <p>{PANEL_TEXT}</p>
              {/* Baner rysuje `AppLayout`; tutaj stoi w tym samym miejscu drzewa. */}
              <RestrictedBanner />
            </AccessGate>
          }
        />
        <Route path={LOGIN_PATH} element={<p>ekran logowania</p>} />
        <Route path={INVITATION_PATH} element={<p>ekran zaproszenia</p>} />
      </Routes>
    </MemoryRouter>
  );
}

function renderGate(): ReturnType<typeof render> {
  return render(gateTree());
}

beforeEach(() => {
  signOut.mockResolvedValue({ error: null });
  profile();
});

afterEach(() => {
  cleanup();
  vi.clearAllMocks();
});

describe('AccessGate', () => {
  it('konto aktywne po regulaminie wpuszcza do panelu i nie pokazuje banera', () => {
    renderGate();

    expect(screen.getByText(PANEL_TEXT)).toBeDefined();
    expect(screen.queryByText(RESTRICTED_BANNER_TEXT)).toBeNull();
    expect(signOut).not.toHaveBeenCalled();
  });

  it('konto ograniczone wpuszcza do panelu RAZEM z banerem', () => {
    profile({ accessState: 'ograniczone' });

    renderGate();

    expect(screen.getByText(PANEL_TEXT)).toBeDefined();
    expect(screen.getByText(RESTRICTED_BANNER_TEXT)).toBeDefined();
  });

  it('konto oczekujące kieruje na /zaproszenie', () => {
    profile({ accessState: 'oczekujace', termsAcceptedAt: null });

    renderGate();

    expect(screen.getByText('ekran zaproszenia')).toBeDefined();
    expect(screen.queryByText(PANEL_TEXT)).toBeNull();
  });

  it('konto bez zgody na dokumenty kieruje na /zaproszenie mimo stanu aktywnego', () => {
    // Tryb otwarty: konto wstaje `aktywne`, ale regulaminu jeszcze nie widziało.
    profile({ termsAcceptedAt: null });

    renderGate();

    expect(screen.getByText('ekran zaproszenia')).toBeDefined();
  });

  it('brak wiersza profilu wylogowuje raz i kieruje na /logowanie', async () => {
    profileState.current = { status: 'brak' };

    renderGate();

    expect(await screen.findByText('ekran logowania')).toBeDefined();
    expect(signOut).toHaveBeenCalledTimes(1);
    // Zakres `local`: globalny ubiłby też sesje mintowane dla kanału MCP.
    expect(signOut).toHaveBeenCalledWith({ scope: 'local' });
    expect(screen.queryByText(PANEL_TEXT)).toBeNull();
  });

  it('nieudane wylogowanie nie odsyła na logowanie przy żywej sesji, tylko mówi wprost', async () => {
    // Nawigacja na `/logowanie` z żywą sesją odbiłaby się z powrotem tutaj.
    profileState.current = { status: 'brak' };
    signOut.mockResolvedValue({ error: { message: 'sieć' } });

    renderGate();

    expect(await screen.findByRole('alert')).toHaveProperty(
      'textContent',
      ACCESS_TEXTS.logoutFailed,
    );
    expect(screen.queryByText('ekran logowania')).toBeNull();
    expect(captureException).toHaveBeenCalledTimes(1);
  });

  it('awaria odczytu profilu ani nie wpuszcza, ani nie wylogowuje', () => {
    profileState.current = { status: 'awaria' };

    renderGate();

    expect(screen.getByRole('alert')).toHaveProperty('textContent', ACCESS_TEXTS.profileFailed);
    expect(screen.queryByText(PANEL_TEXT)).toBeNull();
    expect(signOut).not.toHaveBeenCalled();
  });

  it('nieudany PONOWNY odczyt profilu zostawia panel, zamiast zamieniać go w ekran awarii', () => {
    // Zapisy onboardingu (checklista, koniec przewodnika) proszą bramkę
    // o ponowny odczyt wiersza. Są best-effort, więc awaria tego odczytu nie
    // ma prawa zdemolować panelu, w którym człowiek właśnie pracuje.
    const { rerender } = renderGate();

    expect(screen.getByText(PANEL_TEXT)).toBeDefined();

    profileState.current = { status: 'awaria' };
    rerender(gateTree());

    expect(screen.getByText(PANEL_TEXT)).toBeDefined();
    expect(screen.queryByRole('alert')).toBeNull();
  });

  it('pusta odpowiedź PONOWNEGO odczytu nie wylogowuje z panelu', () => {
    const { rerender } = renderGate();

    expect(screen.getByText(PANEL_TEXT)).toBeDefined();

    profileState.current = { status: 'brak' };
    rerender(gateTree());

    expect(screen.getByText(PANEL_TEXT)).toBeDefined();
    expect(signOut).not.toHaveBeenCalled();
    expect(screen.queryByText('ekran logowania')).toBeNull();
  });

  it('w trakcie odczytu profilu pokazuje ekran ładowania, nie panel', () => {
    profileState.current = { status: 'ladowanie' };

    renderGate();

    expect(screen.getByRole('status')).toBeDefined();
    expect(screen.queryByText(PANEL_TEXT)).toBeNull();
  });
});

