import type { AccountProfile } from '../account/use-profile.js';
import { cleanup, render, screen } from '@testing-library/react';
import { MemoryRouter, Route, Routes } from 'react-router';
import { afterEach, describe, expect, it, vi } from 'vitest';

import { OFFERS_PATH, USERS_PATH } from '../../routes.js';
import { RequireAdmin } from './require-admin.js';

/**
 * Bramka roli. Atrapa dotyczy KONTEKSTU bramki dostępu, nie samego
 * `RequireAdmin` — testujemy zachowanie („wpuszcza / odsyła"), a nie sposób,
 * w jaki profil trafia do drzewa.
 */
const { useAccountAccess } = vi.hoisted(() => ({ useAccountAccess: vi.fn() }));

vi.mock('./access-gate.js', () => ({ useAccountAccess }));

function profile(role: AccountProfile['role']): AccountProfile {
  return {
    id: '00000000-0000-4000-8000-000000000001',
    hasWebhook: false,
    isFirstStepsDismissed: false,
    tourSeen: { oferty: true, oferta: true, szablony: true },
    accessState: 'aktywne',
    role,
    source: 'akademia',
    termsAcceptedAt: new Date('2026-09-01T10:00:00.000Z'),
    deletionRequestedAt: null,
  };
}

function renderGate(): void {
  render(
    <MemoryRouter initialEntries={[USERS_PATH]}>
      <Routes>
        <Route
          path={USERS_PATH}
          element={
            <RequireAdmin>
              <p>ekran administratora</p>
            </RequireAdmin>
          }
        />
        <Route path={OFFERS_PATH} element={<p>lista ofert</p>} />
      </Routes>
    </MemoryRouter>,
  );
}

afterEach(() => {
  cleanup();
  vi.clearAllMocks();
});

describe('RequireAdmin', () => {
  it('wpuszcza konto z rolą admin', () => {
    useAccountAccess.mockReturnValue(profile('admin'));

    renderGate();

    expect(screen.getByText('ekran administratora')).toBeDefined();
  });

  it('odsyła zwykłe konto na listę ofert BEZ komunikatu', () => {
    useAccountAccess.mockReturnValue(profile('user'));

    renderGate();

    expect(screen.getByText('lista ofert')).toBeDefined();
    expect(screen.queryByText('ekran administratora')).toBeNull();
    // Zero zdań o uprawnieniach: dla handlowca ten ekran nie istnieje.
    expect(screen.queryByRole('alert')).toBeNull();
  });

  it('bez profilu w kontekście odmawia — domyślną odpowiedzią bramki jest odmowa', () => {
    useAccountAccess.mockReturnValue(null);

    renderGate();

    expect(screen.getByText('lista ofert')).toBeDefined();
  });
});
